insert into private.study_guides (guide, chunks, sha256) values ('study_guide_bua101', 41, '4ff00fde2dea479bf68751c623772e39e42cb7d3f29846455e4e89e7bec7240e');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 1, $study_guide${"guide":"study_guide_bua101","code":"BUA101","courseId":"3377fae6-5ab9-5742-95e3-75b94650a294","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"f041360f-0ed4-5d49-87f5-ea47e587979f","create":true,"after":{"title":"Introduction to Business I","body":"Every topic is examinable.","outcomes":["Explain what businesses do, the environments they operate in and their major functional areas.","Describe economic systems, demand and supply, and how government and economic measures affect business.","Explain international trade, trade barriers and the forms of international business.","Apply ethics and corporate social responsibility to business decisions.","Compare the forms of business ownership and explain corporate governance, mergers and alliances.","Explain entrepreneurship, small-business start-up and financing, and franchising.","Describe the roles, functions and skills of managers.","Explain production systems, value chains, supply chains and quality.","Apply the main theories of employee motivation.","Describe e-business models and the business communication process."],"assessment":["The exam is objective (CBT), with some theory questions. Expect definitions, lists, counts, Nigerian institutions and examples."]}},"retire":[],"notes":[{"kind":"note","itemId":"323e5369-3db7-5f26-a4fc-c4f2d02fbd8c","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Developing a Business Mindset","body":"What a business is and how it adds value; types of business and stakeholders; making the leap from buyer to seller; the business environments (internal, external, general, task) and Nigerian regulators; the functional areas; careers in business; the seven traits of professionalism.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"What a business is and how it adds value; types of business and stakeholders; making the leap from buyer to seller; the business environments (internal, external, general, task) and Nigerian regulators; the functional areas; careers in business; the seven traits of professionalism."}],"lessons":[{"number":"1.1","title":"What businesses do","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business:","bold":true},{"text":" any profit-seeking organisation that provides goods and services designed to satisfy customers' needs. Another definition: purposeful or deliberate activities concerned with the provision of goods and services which are distributed through an organised system (distribution)."}]},{"text":[{"text":"Primary purpose of a business:","bold":true},{"text":" to generate and provide "},{"text":"customer value","bold":true},{"text":". Profit is the reward for doing this well."}]},{"text":[{"text":"Adding value:","bold":true},{"text":" a business is a system that transforms "},{"text":"lower-value inputs","bold":true},{"text":" into "},{"text":"higher-value outputs","bold":true},{"text":". At every stage it adds value to make the product appealing to the next customer in the chain."}]},{"text":[{"text":"Business model:","bold":true},{"text":" a concise description of how a business intends to "},{"text":"generate revenue","bold":true},{"text":"."}]},{"text":[{"text":"Revenue","bold":true},{"text":" = money brought in from sales. "},{"text":"Profit","bold":true},{"text":" = revenue minus costs."}]}]},{"type":"paragraph","text":[{"text":"3 major types of organisation:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Not-for-profit (nonprofit):","bold":true},{"text":" provides goods and services "},{"text":"without a profit motive","bold":true},{"text":", e.g. the World Health Organization (WHO), the Red Cross, a mosque or church charity."}]},{"text":[{"text":"Goods-producing:","bold":true},{"text":" creates value by making \"things\", mostly "},{"text":"tangible","bold":true},{"text":" (digital products such as software are the notable exception)."}]},{"text":[{"text":"Service:","bold":true},{"text":" creates value by "},{"text":"performing activities","bold":true},{"text":" that deliver a benefit, e.g. banks, hairdressers, consultants, MTN's call and data services."}]}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"What it does"}],[{"text":"Example"}]],"rows":[[[{"text":"Manufacturing"}],[{"text":"Makes a product and sells it"}],[{"text":"Dangote Cement"}]],[[{"text":"Wholesale"}],[{"text":"Sells goods in "},{"text":"large quantities to retailers","bold":true}],[{"text":"A distributor supplying shops"}]],[[{"text":"Retail"}],[{"text":"Sells to "},{"text":"final consumers","bold":true}],[{"text":"Shoprite, a corner shop"}]],[[{"text":"Service-based"}],[{"text":"Profits by providing services, not goods"}],[{"text":"Bank, salon, software developer"}]]]},{"type":"paragraph","text":[{"text":"Stakeholders and what they receive","bold":true}]},{"type":"table","header":[[{"text":"Stakeholder"}],[{"text":"Gives the business"}],[{"text":"Receives"}]],"rows":[[[{"text":"Shareholders (owners)"}],[{"text":"Capital"}],[{"text":"Dividends","bold":true}]],[[{"text":"Employees"}],[{"text":"Labour"}],[{"text":"Wages and salaries","bold":true}]],[[{"text":"Customers"}],[{"text":"Payment"}],[{"text":"Goods and services (value)"}]],[[{"text":"Government"}],[{"text":"Infrastructure","bold":true},{"text":", law and order"}],[{"text":"Taxes","bold":true}]],[[{"text":"Community"}],[{"text":"Location, goodwill"}],[{"text":"Community services","bold":true},{"text":", jobs"}]],[[{"text":"Suppliers"}],[{"text":"Inputs"}],[{"text":"Payment"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"software development company","bold":true},{"text":" that builds systems for clients sells its expertise, so it is a "},{"text":"service business","bold":true},{"text":". A car dealership, bakery or furniture store deals in physical goods."}]},{"text":[{"text":"McDonald's, Apple and Tesla are profit-seeking; WHO is not-for-profit. Nonprofits still need money and good management; $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 2, $study_guide$they simply do not distribute profit to owners."}]},{"text":[{"text":"Understanding what businesses do means recognising their "},{"text":"creation of products and services","bold":true},{"text":", not tax avoidance or isolation from competition."}]},{"text":[{"text":"Trap: "},{"text":"dividends","bold":true},{"text":" go to shareholders; "},{"text":"wages","bold":true},{"text":" go to employees. \"Provision of infrastructure\" is what government gives, not what shareholders receive."}]}]}]},{"number":"1.2","title":"Making the leap from buyer to seller","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"As a consumer you already know a lot: the impact of poor customer service, product value, and the whole experience of searching for, buying and owning products."}]},{"text":[{"text":"3 steps to make the leap from consumer to business professional:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Seeing business from the inside out:","bold":true},{"text":" think about the cost of making, promoting and distributing a product, not just buying it; see business as an integrated system of "},{"text":"inputs, processes and outputs","bold":true},{"text":"."}]},{"text":[{"text":"Appreciating the role of business in society.","bold":true}]},{"text":[{"text":"Using this course to jump-start your career.","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"4 ways business benefits society:","bold":true},{"text":" (1) offering valuable goods and services; (2) providing employment; (3) paying taxes; (4) contributing to national growth, stability and security."}]},{"text":[{"text":"4 negative effects:","bold":true},{"text":" (1) generating pollution and creating waste; (2) creating health and safety risks; (3) disrupting communities; (4) causing financial instability."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Making the leap begins with "},{"text":"grasping customer preferences","bold":true},{"text":": what customers want and value. Ignoring market shifts or chasing profit margins alone is the opposite."}]},{"text":[{"text":"A "},{"text":"business mindset","bold":true},{"text":" means "},{"text":"comprehending operational success factors","bold":true},{"text":": the many decisions and challenges a company must handle before it can deliver products that satisfy customers. It is not targeting only quick wins or shunning all uncertainty."}]},{"text":[{"text":"The course builds a business vocabulary, introduces jobs (accounting, economics, HR, management, finance, marketing) and shows the legal and ethical questions managers face."}]}]}]},{"number":"1.3","title":"The environments of business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"No business operates in a vacuum. "},{"text":"Business environment:","bold":true},{"text":" all the forces, inside and outside a firm, that affect and are affected by it."}]},{"text":[{"text":"2 types:","bold":true},{"text":" "},{"text":"internal","bold":true},{"text":" and "},{"text":"external","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Internal environment"}],[{"text":"External environment"}]],"rows":[[[{"text":"Inside the firm; "},{"text":"controllable","bold":true}],[{"text":"Outside the firm; "},{"text":"uncontrollable","bold":true}]],[[{"text":"Staff, structure, resources, management, "},{"text":"organisational (workplace) culture","bold":true},{"text":", values, operational procedures"}],[{"text":"Economy, technology, politics, law, society, competitors, customers"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The external environment splits into:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"General (macro) forces:","bold":true},{"text":" affect all firms: "},{"text":"political-legal, economic, socio-cultural, technological","bold":true},{"text":" (PESTLE adds legal and environmental/ecological)."}]},{"text":[{"text":"Task (micro, operating) forces:","bold":true},{"text":" close to the firm: customers, competitors, suppliers, investors."}]}]}]}]},{"type":"paragraph","text":[{"text":"The 5 environments every business operates in:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Social:","bold":true},{"text":" trends and forces in society at large."}]},{"text":[{"text":"Technological:","bold":true},{"text":" forces from the practical application of science to innovations, products and processes."}]},{"text":[{"text":"Economic:","bold":true},{"text":" conditions and forces that affect the cost and availability of goods, services and labour, and so shape the behaviour of buyers and sellers."}]},{"text":[{"text":"Legal and regulatory:","bold":true},{"text":" laws and regulations at local, state, national and international levels."}]},{"text":[{"text":"Market:","bold":true},{"text":" target customers, the buying influences that shape their behaviour, and competitors marketing similar products."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Features of the business environment:","bold":true},{"text":" "},{"text":"dynamic","bold":true},{"text":" (always changing), "},{"text":"uncertain","bold":true},{"text":", "},{"text":"relative","bold":true},{"text":" (differs by place and firm), complex, multi-faceted. "},{"text":"Certainty is not a feature.","bold":true}]},{"text":[{"text":"Importance:","bold":true},{"text":" identifying opportunities and threats, improving performance, coping with rapid changes, better planning. (\"All of these\" is the answer.)"}]},{"text":[{"text":"Environmental scanning:","bold":true},{"text":" careful monitoring of the internal and external environments to detect early signs of opportunities and threats that may influence current and future plans."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Political-legal environment","bold":true},{"text":" = the relationship $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 3, $study_guide$between "},{"text":"business and government","bold":true},{"text":". Customs, values, attitudes and demographics are the "},{"text":"socio-cultural","bold":true},{"text":" environment; intensity of competition is the "},{"text":"market/competitive","bold":true},{"text":" environment."}]},{"text":[{"text":"Technological conditions are a "},{"text":"general","bold":true},{"text":" force; customers, competitors and investors are task forces."}]},{"text":[{"text":"Emerging technology and political change are "},{"text":"external","bold":true},{"text":"; staff dynamics, corporate values and operating protocols are "},{"text":"internal","bold":true},{"text":"."}]},{"text":[{"text":"Traps: SWOT analysis uses scanning results (strengths, weaknesses, opportunities, threats) but is not the definition of scanning. PESTLE covers only the external macro environment."}]}]}]},{"number":"1.4","title":"Regulators and the Nigerian legal environment","mustKnow":[{"type":"table","header":[[{"text":"Body"}],[{"text":"Full name"}],[{"text":"Main job"}]],"rows":[[[{"text":"CAC","bold":true}],[{"text":"Corporate Affairs Commission"}],[{"text":"Established by the "},{"text":"Companies and Allied Matters Act","bold":true},{"text":" (first 1990; now "},{"text":"CAMA 2020","bold":true},{"text":") and "},{"text":"implements its provisions","bold":true},{"text":": registers companies, business names and incorporated trustees; regulates their formation, management and winding up"}]],[[{"text":"SON","bold":true}],[{"text":"Standards Organisation of Nigeria"}],[{"text":"Sets and enforces "},{"text":"product standards","bold":true}]],[[{"text":"SEC","bold":true}],[{"text":"Securities and Exchange Commission"}],[{"text":"Apex regulator of the Nigerian capital market","bold":true}]],[[{"text":"NEPC","bold":true}],[{"text":"Nigerian Export Promotion Council"}],[{"text":"Promotes "},{"text":"non-oil exports","bold":true}]],[[{"text":"NAFDAC","bold":true}],[{"text":"National Agency for Food and Drug Administration and Control"}],[{"text":"Regulates food, drugs, cosmetics, chemicals and packaged water"}]]]},{"type":"paragraph","text":[{"text":"Functions of SON:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Organises "},{"text":"tests","bold":true},{"text":" and does what is necessary to ensure compliance with approved standards."}]},{"text":[{"text":"Investigates the "},{"text":"quality of facilities, materials and products","bold":true},{"text":" used in production."}]},{"text":[{"text":"Registers and regulates standard marks and specifications.","bold":true}]},{"text":[{"text":"Certifies products","bold":true},{"text":" in commerce and industry (also factories and laboratories)."}]},{"text":[{"text":"Advises government","bold":true},{"text":" on problems relating to standards specification."}]}]},{"type":"paragraph","text":[{"text":"Functions of NEPC:","bold":true},{"text":" provides "},{"text":"grants and incentives","bold":true},{"text":" to exporters, provides "},{"text":"information on products","bold":true},{"text":" and markets, provides "},{"text":"lists of exportable products","bold":true},{"text":", and trains exporters."}]},{"type":"paragraph","text":[{"text":"Functions of SEC:","bold":true},{"text":" registers securities and capital market operators, protects investors, "},{"text":"disseminates information to investors on securities","bold":true},{"text":", and keeps the market fair and transparent."}]},{"type":"paragraph","text":[{"text":"Challenges of complying with government regulations:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Corruption.","bold":true}]},{"text":[{"text":"Costs of compliance","bold":true},{"text":" (fees, paperwork, staff time, upgrades)."}]},{"text":[{"text":"Complexity of regulations.","bold":true}]},{"text":[{"text":"Political "},{"text":"instability","bold":true},{"text":" and frequent policy changes."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: "},{"text":"political stability","bold":true},{"text":" is not a compliance challenge; it helps business."}]},{"text":[{"text":"The stock exchange (Nigerian Exchange, NGX, formerly the Nigerian Stock Exchange, NSE) is a market "},{"text":"regulated by SEC","bold":true},{"text":"; it is not the apex regulator."}]},{"text":[{"text":"\"Providing opportunities for businesses to raise funds\" is a capital market role, "},{"text":"not","bold":true},{"text":" SON's. \"Disseminating information on securities\" is SEC's, "},{"text":"not","bold":true},{"text":" NEPC's."}]},{"text":[{"text":"Testing the "},{"text":"quality of materials and facilities","bold":true},{"text":" points to "},{"text":"SON","bold":true},{"text":", not NAFDAC; NAFDAC is about food, drugs and similar regulated products."}]}]}]},{"number":"1.5","title":"The major functional areas","mustKnow":[{"type":"paragraph","text":[{"text":"The 6 major functional areas:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Research and development (R&D):","bold":true},{"text":" conceiving and designing new products."}]},{"text":[{"text":"Manufacturing, production and operations:","bold":true},{"text":" where the company makes what it makes, or does what it does (service firms)."}]},{"text":[{"text":"Marketing, sales, distribution and customer support:","bold":true},{"text":" marketing identifies opportunities and customer wants, works with R&D to develop products, creates branding and advertising, and sets prices; sales builds relationships and persuades customers to buy; distribution moves products, before and after the sale; customer support helps buyers after purchase."}]},{"text":[{"text":"Finance and accounting:","bold":true},{"text":" ensures the company has the funds it needs, monitors and controls spending, and drafts reports for management, investors and government regulators."}]},{"text":[{"text":"Human resources (HR):","bold":true},{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 4, $study_guide$:" recruiting, hiring, developing and supporting employees."}]},{"text":[{"text":"Business services:","bold":true},{"text":" law, banking, real estate and similar, done in-house, by outside firms or both."}]}]},{"type":"paragraph","text":[{"text":"Other functions you will meet in options:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Employment relations and HRM:","bold":true},{"text":" puts the "},{"text":"right people in the right posts under the right conditions","bold":true},{"text":"; handles "},{"text":"remuneration","bold":true},{"text":" (pay and benefits)."}]},{"text":[{"text":"Insurance and risk management:","bold":true},{"text":" identifies risks such as "},{"text":"safety issues that could lead to lawsuits","bold":true},{"text":", and "},{"text":"implements plans and strategies to minimise business losses","bold":true},{"text":" (avoid, reduce, retain or transfer risk, e.g. by buying insurance)."}]},{"text":[{"text":"Information technology (IT):","bold":true},{"text":" systems that deliver the right information to the right people at the right time; supports every other area."}]},{"text":[{"text":"Reasons for separating operations into functional areas:","bold":true},{"text":" "},{"text":"efficiency, expertise, effectiveness","bold":true},{"text":" (through specialisation). "},{"text":"Increased costs is not a reason.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"HR activities:","bold":true},{"text":" "},{"text":"acquisition","bold":true},{"text":" (getting staff, made up of "},{"text":"recruitment","bold":true},{"text":" then "},{"text":"selection","bold":true},{"text":"), development (training), compensation, maintenance. "},{"text":"Recruitment","bold":true},{"text":" = advertising to attract a "},{"text":"pool of candidates","bold":true},{"text":"; "},{"text":"selection","bold":true},{"text":" = choosing from that pool."}]},{"text":[{"text":"Marketing "},{"text":"identifies customer wants and develops products","bold":true},{"text":" to satisfy them, and covers "},{"text":"advertising, selling and distributing","bold":true},{"text":"; \"market outreach\" (promoting products) is marketing. Process optimisation is operations; fiscal planning is finance; product innovation is R&D."}]},{"text":[{"text":"Mining","bold":true},{"text":" is an industry, not a functional area."}]},{"text":[{"text":"Production, R&D and HR together aid business processes toward profit and essential services. Dividends, wages and regular orders are not functions."}]},{"text":[{"text":"Not every company has a formal R&D function; many service firms and small businesses do not, though most still need to improve their offerings."}]}]}]},{"number":"1.6","title":"Careers in business and professionalism","mustKnow":[{"type":"paragraph","text":[{"text":"7 important business professions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Operations manager:","bold":true},{"text":" all people and processes that create the goods and perform the services a company sells."}]},{"text":[{"text":"Human resources specialist:","bold":true},{"text":" recruiting, training and development, compensation and benefits, employee and labour relations, health and safety."}]},{"text":[{"text":"Information technology manager:","bold":true},{"text":" designs, implements and maintains information systems."}]},{"text":[{"text":"Marketing specialist:","bold":true},{"text":" branding, e-commerce, advertising, public relations, social media."}]},{"text":[{"text":"Sales professional:","bold":true},{"text":" suits people who thrive on competition, enjoy solving problems and like working with many people."}]},{"text":[{"text":"Accountant:","bold":true},{"text":" management accountants "},{"text":"collect, analyse and report","bold":true},{"text":" on financial matters."}]},{"text":[{"text":"Financial manager:","bold":true},{"text":" "},{"text":"controllers","bold":true},{"text":" oversee financial reports and often manage accounting; "},{"text":"treasurers and finance officers","bold":true},{"text":" set long-term financial goals and budgets, "},{"text":"invest the firm's funds and raise capital","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Professionalism:","bold":true},{"text":" the quality of performing at a high level and conducting oneself with "},{"text":"purpose and pride","bold":true},{"text":"."}]},{"text":[{"text":"7 traits:","bold":true},{"text":" (1) striving to excel; (2) being dependable and accountable; (3) being a team player; (4) communicating effectively; (5) demonstrating etiquette; (6) making ethical decisions; (7) maintaining a confident, positive outlook."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Accountant vs financial manager: the accountant "},{"text":"records and reports","bold":true},{"text":"; the financial manager "},{"text":"plans and acts","bold":true},{"text":" on the numbers. A \"financial resource director\" manages a company's financial resources."}]},{"text":[{"text":"Logistics and distribution","bold":true},{"text":" is a business career; structural engineering, clinical healthcare and crop cultivation are not."}]},{"text":[{"text":"Dependable:","bold":true},{"text":" meet commitments, on schedule and within budget. "},{"text":"Team player:","bold":true},{"text":" pull your own weight while watching the team's success. "},{"text":"Etiquette:","bold":true},{"text":" expected norms of behaviour in a situation. "},{"text":"Ethical decisions:","bold":true},{"text":" avoid ethical lapses; weigh options carefully in ethical dilemmas."}]},{"text":[{"text":"7 guidelines for communicating effectively:","bold":true},{"text":" listen actively; provide practical information; give facts rather than vague impressions; do not present opinions as facts; be concise and efficient; clarify expectations and responsibilities; offer compe$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 5, $study_guide$lling, persuasive arguments and recommendations."}]},{"text":[{"text":"Trap: professionalism is "},{"text":"not","bold":true},{"text":" holding a degree, wearing formal clothes or obeying without question."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business = profit-seeking provider of goods and services; purpose = customer value; it adds value by turning inputs into higher-value outputs."}]},{"text":[{"text":"Business model = how a business intends to generate revenue."}]},{"text":[{"text":"Types: not-for-profit, goods-producing, service; also manufacturing, wholesale (to retailers), retail (to consumers)."}]},{"text":[{"text":"Shareholders get dividends, employees wages, government taxes."}]},{"text":[{"text":"Leap from buyer to seller: inside-out view, role in society, jump-start your career."}]},{"text":[{"text":"Environments: internal (controllable) vs external (uncontrollable); general vs task; five environments: social, technological, economic, legal-regulatory, market."}]},{"text":[{"text":"CAC (CAMA), SON (standards), SEC (apex capital market regulator), NEPC (exports)."}]},{"text":[{"text":"Six functional areas: R&D, production/operations, marketing, finance and accounting, HR, business services; plus insurance and risk management."}]},{"text":[{"text":"Seven professions; professionalism has seven traits."}]}]}],"theory":{"itemId":"673bffa2-543e-5b27-b905-4445464c011f","question":[{"type":"paragraph","text":[{"text":"Explain the five environments in which every business operates, and state two ways business benefits society."}]}]},"practice":[{"topic":"Developing a Business Mindset","named":false}]}},{"kind":"note","itemId":"b9f822a9-93cf-51c1-8461-5cef9fa94f0b","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Understanding Basic Economics","body":"What an economy is and its levels; scarcity and the factors of production; the economic systems (market, command, mixed, with socialism and communism); demand, supply and equilibrium; the macro view (competition, business cycles, unemployment, inflation); government's role in a free market; the economic measures and monitors (GDP, GNP, CPI, PPI and others).","noteType":"guide_topic","number":2,"mustKnow":[{"text":"What an economy is and its levels; scarcity and the factors of production; the economic systems (market, command, mixed, with socialism and communism); demand, supply and equilibrium; the macro view (competition, business cycles, unemployment, inflation); government's role in a free market; the economic measures and monitors (GDP, GNP, CPI, PPI and others)."}],"lessons":[{"number":"2.1","title":"The economy and the factors of production","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Economics:","bold":true},{"text":" the study of how a society uses scarce resources to produce and distribute goods and services."}]},{"text":[{"text":"Economy:","bold":true},{"text":" the system (framework) through which a society produces, distributes, exchanges and consumes goods and services. More fully: the management of national, regional or household resources in terms of production capacity, monetary system, distribution of resources, and the principles or ideology that govern how resources are shared. It sums up a society's economic activities as they affect individuals and businesses."}]},{"text":[{"text":"5 levels at which we speak of \"an economy\":","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Nation:","bold":true},{"text":" e.g. the Nigerian, Ghanaian, US or Cuban economy."}]},{"text":[{"text":"State or region:","bold":true},{"text":" e.g. the Lagos State economy, the Northern region economy."}]},{"text":[{"text":"Industry:","bold":true},{"text":" e.g. the oil and gas economy, the agricultural economy of Nigeria."}]},{"text":[{"text":"Household or family:","bold":true},{"text":" e.g. a family's income and spending."}]},{"text":[{"text":"Institution:","bold":true},{"text":" e.g. the Unilag economy, the volume and size of all business activity around the campus."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Microeconomics:","bold":true},{"text":" the study of individual units: a consumer, a household, a firm, a single market (a firm's earnings, a worker's salary, a company's overheads)."}]},{"text":[{"text":"Macroeconomics:","bold":true},{"text":" the study of the economy as a whole: total output (GDP), inflation, unemployment, growth."}]},{"text":[{"text":"4 traditional factors of production:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Land","bold":true},{"text":" (natural resources): land, water, minerals, forests, crude oil."}]},{"text":[{"text":"Labour","bold":true},{"text":" (human resources): the physical and mental effort of people."}]},{"text":[{"text":"Capital:","bold":true},{"text":" man-made aids to production: machines, tools, buildings, and the money used to buy them."}]},{"text":[{"text":"Entrepreneurship:","bold":true},{"text":" the willingness to take risks to combine the other factors into a business."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Scarcity","bold":true},{"text":" is the basic economic problem: unlimited wants, limited resources. Every choice is a "},{"text":"trade-off","bold":true},{"text":"; the best alternative given up is the "},{"text":"opportunity cost","bold":true},{"text":" (spend ₦20,000 on a phone accessory and the textbooks you could have bought are the opportunity cost)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" technology, information and knowledge improve how the factors work, and "},{"text":"knowledge","bold":true},{"text":" is sometimes added as a fifth factor. But when a question asks for the "},{"text":"four traditional","bold":true},{"text":" factors, the answer is land, labour, capital and entrepreneurship. \"Technology\", \"money supply\" or \"government\" are not among the $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 6, $study_guide$four."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"Economy\" is not a tax mechanism, an advertising system or a staff-control tool. It is the whole framework for producing and exchanging goods and services."}]}]}]},{"number":"2.2","title":"Economic systems","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Economic system:","bold":true},{"text":" the policies that define how a society distributes its resources to satisfy its people's needs. Every system must answer: "},{"text":"what","bold":true},{"text":" to produce, "},{"text":"how","bold":true},{"text":" to produce it, and "},{"text":"for whom","bold":true},{"text":"."}]},{"text":[{"text":"3 broad systems:","bold":true},{"text":" market, command (planned), mixed."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Market (free-market, capitalism)"}],[{"text":"Command (planned)"}],[{"text":"Mixed"}]],"rows":[[[{"text":"Who owns resources"}],[{"text":"Private individuals and firms"}],[{"text":"Government owns key businesses"}],[{"text":"Private, public and joint sectors co-exist"}]],[[{"text":"Who decides what to produce"}],[{"text":"Demand and supply (price mechanism)"}],[{"text":"Central government planning"}],[{"text":"Both market forces and government"}]],[[{"text":"Competition"}],[{"text":"Strong"}],[{"text":"Lacking"}],[{"text":"Present, but regulated"}]],[[{"text":"Consumer choice"}],[{"text":"Freedom of choice"}],[{"text":"Limited"}],[{"text":"Economic freedom with social welfare"}]],[[{"text":"Government role"}],[{"text":"Limited intervention"}],[{"text":"Controls wages, means of production, what and how to produce"}],[{"text":"Regulates, redistributes; regulatory bodies prominent"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Market economy characteristics:","bold":true},{"text":" competition, private ownership of resources, freedom of choice, price mechanism, limited government intervention, efficient allocation of resources (at the equilibrium point)."}]},{"text":[{"text":"Command economy characteristics:","bold":true},{"text":" government ownership of key businesses, government intervention, government control of wages and means of production, centralised economic planning, lack of competition, limited consumer choice, government decides what and how to produce. Resources are allocated by "},{"text":"central government authority","bold":true},{"text":"."}]},{"text":[{"text":"Mixed economy characteristics:","bold":true},{"text":" social welfare, mixed ownership of property, economic freedom, co-existence of private, public and joint sectors, resources allocated by both government and market forces, prominent government-owned regulatory bodies, redistribution of resources to achieve economic and social goals. Also called a "},{"text":"welfarist state","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Capitalism","bold":true},{"text":" is the market system: private owners and the profit motive drive the economy. "},{"text":"Pure capitalism","bold":true},{"text":" (no government role at all) does not exist anywhere."}]},{"text":[{"text":"Planned systems come in two forms:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communism:","bold":true},{"text":" the government owns and operates all productive resources; private property is largely eliminated. The state decides all production and prices. Cuba and North Korea are the usual examples."}]},{"text":[{"text":"Socialism:","bold":true},{"text":" the government owns and runs "},{"text":"selected major industries","bold":true},{"text":" (e.g. power, transport, banking), while private businesses operate in the rest. It stresses social welfare and equal distribution."}]}]}]},{"text":[{"text":"Mixed economy","bold":true},{"text":" = market freedom "},{"text":"plus","bold":true},{"text":" state control. Nigeria is a mixed economy: private firms such as Dangote, MTN and the banks operate alongside government agencies and regulators such as the Central Bank of Nigeria (CBN), SEC and SON. Most countries today are mixed."}]},{"text":[{"text":"Privatisation","bold":true},{"text":" moves businesses from government to private ownership; "},{"text":"nationalisation","bold":true},{"text":" is the reverse. "},{"text":"Deregulation","bold":true},{"text":" removes or relaxes government rules on an industry (e.g. Nigeria's telecoms deregulation, which let private mobile operators in)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a mixed economy combines market and command features. It is not a mix of \"tradition and customs\" (that is a "},{"text":"traditional economy","bold":true},{"text":", based on custom), and it is not \"all economic systems\"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" state production quotas, absence of competition and uniform allocation describe a command economy, never a free market."}]}]}]},{"number":"2.3","title":"Demand, supply and equilibrium","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand:","bold":true},{"text":" the quantity of a good or service buyers are willing and able to buy at various prices."}]},{"text":[{"text":"Law of demand:","bold":true},{"text":" other things being equal, as price "},{"text":"falls","bold":true},{"text":", quantity demanded "},{"text":"rises","bold":true},{"text":"; as price rises, quantity demanded falls. Lower prices spur demand. The demand curve slopes "},{"text":"downward","bold":true},{"text":"."}]},{"text":[{"text":"Supply:","bold":true},{"text":" the quantity sellers are willing and able to offer for sale at various prices."}]},{"text":[{"text":"Law of supply:","bold":true},{"text":" other things being equal, as price "},{"text":"rises","bold":true},{"text":", quantity supplied "},{"text":"rises","bold":true},{"text":"; rising prices lift supply. The supply curve slopes "},{"text":"upward","bold":true},{"text":"."}]},{"text":[{"text":"Equilibrium price ($study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 7, $study_guide$market price):","bold":true},{"text":" the price at which the demand curve and supply curve intersect, where quantity demanded equals quantity supplied. It is the optimal price for allocating resources or goods."}]},{"text":[{"text":"Relevance of demand and supply (price mechanism) in a market economy:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It determines the distribution of goods and the allocation of resources."}]},{"text":[{"text":"It reduces, if not eliminates, government intervention in resource allocation in many sectors."}]},{"text":[{"text":"It determines the production of goods and their prices."}]},{"text":[{"text":"The equilibrium price stands as the optimal price to allocate resources or goods."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Demand shifters:","bold":true},{"text":" income, prices of substitutes and complements, tastes, expectations, number of buyers. "},{"text":"Supply shifters:","bold":true},{"text":" input costs, technology, expectations, number of producers, prices of other goods the producer could make. Dearer diesel cuts the supply of bread at every price."}]},{"text":[{"text":"A change in the good's "},{"text":"own price","bold":true},{"text":" moves you "},{"text":"along","bold":true},{"text":" the curve (change in quantity demanded or supplied). A change in any other factor "},{"text":"shifts","bold":true},{"text":" the curve."}]},{"text":[{"text":"Surplus:","bold":true},{"text":" price above equilibrium, so supply exceeds demand; sellers cut prices. "},{"text":"Shortage:","bold":true},{"text":" price below equilibrium, so demand exceeds supply; prices rise. Both push the market back to equilibrium."}]}]}]},{"number":"2.4","title":"The macro view: competition, business cycles, unemployment and inflation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Competition:","bold":true},{"text":" rivalry among businesses for the same customers. "},{"text":"4 market structures:","bold":true}]}]},{"type":"table","header":[[{"text":"Structure"}],[{"text":"Number of sellers"}],[{"text":"Products"}],[{"text":"Example"}]],"rows":[[[{"text":"Pure (perfect) competition","bold":true}],[{"text":"Very many"}],[{"text":"Identical; no seller controls price"}],[{"text":"Farm produce such as maize or tomatoes in an open market"}]],[[{"text":"Monopolistic competition","bold":true}],[{"text":"Many"}],[{"text":"Slightly different (branding, quality)"}],[{"text":"Restaurants, fast food, hair salons, clothing"}]],[[{"text":"Oligopoly","bold":true}],[{"text":"Few large firms"}],[{"text":"Similar or differentiated; high entry barriers"}],[{"text":"Telecoms (MTN, Airtel, Glo, 9mobile), cement, airlines"}]],[[{"text":"Monopoly","bold":true}],[{"text":"One"}],[{"text":"No close substitute"}],[{"text":"Electricity transmission, water utilities"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Business cycle:","bold":true},{"text":" the rise and fall of economic activity over time. Phases: "},{"text":"expansion","bold":true},{"text":" (growth) → "},{"text":"peak","bold":true},{"text":" → "},{"text":"contraction","bold":true},{"text":" (recession) → "},{"text":"trough","bold":true},{"text":" → recovery."}]},{"text":[{"text":"Recession:","bold":true},{"text":" a period of falling economic activity; commonly, two consecutive quarters of falling GDP. "},{"text":"Depression:","bold":true},{"text":" a deep, prolonged recession."}]},{"text":[{"text":"Unemployment:","bold":true},{"text":" people actively seeking work who cannot find it. "},{"text":"4 types:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Frictional:","bold":true},{"text":" temporarily between jobs (e.g. a new graduate searching)."}]},{"text":[{"text":"Structural:","bold":true},{"text":" skills do not match available jobs, often from technology or industry change."}]},{"text":[{"text":"Cyclical:","bold":true},{"text":" caused by a downturn in the business cycle."}]},{"text":[{"text":"Seasonal:","bold":true},{"text":" tied to seasons (e.g. farm labour after harvest)."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Inflation:","bold":true},{"text":" a steady, general rise in the prices of goods and services over time; it reduces the purchasing power of money. "},{"text":"Deflation:","bold":true},{"text":" a sustained fall in general prices. Inflation is a measure of the condition of the economy."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Monopolies often arise in utilities because building power or water networks is so costly that one supplier serving an area is more efficient. Electric utilities are the standard example; fast food, online retail and smartphones face many competitors."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a "},{"text":"recession","bold":true},{"text":" is the contraction phase; the "},{"text":"trough","bold":true},{"text":" is its lowest point, not the start."}]}]}]},{"number":"2.5","title":"Government's role in a free-market system","mustKnow":[{"type":"paragraph","text":[{"text":"6 roles of government in a free-market system:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Provide the legal and social framework","bold":true},{"text":" and enforce the rules of fair play: protecting property rights, enforcing contracts, protecting consumers."}]},{"text":[{"text":"Ensure economic stability","bold":true},{"text":" through different models and frameworks, including "},{"text":"monetary","bold":true},{"text":" decisions."}]},{"text":[{"text":"Maintain competition","bold":true},{"text":" in the marketplace, with an "},{"text":"anti-trust","bold":true},{"text":" body to monitor abuse."}]},{"text":[{"text":"Provide public goods and services","bold":true},{"text":", e.g. postal system, water, education, health."}]},{"text":[{"text":"Redistribute income","bold":true},{"text":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 8, $study_guide$" to cater for the weak and under-privileged and reduce the income gap."}]},{"text":[{"text":"Deal with the international community and economic blocs","bold":true},{"text":" to determine trade and economic relationships."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Monetary policy:","bold":true},{"text":" the central bank's control of the "},{"text":"money supply and interest rates","bold":true},{"text":" to stabilise the economy. In Nigeria this is done by the "},{"text":"Central Bank of Nigeria (CBN)","bold":true},{"text":"."}]},{"text":[{"text":"Fiscal policy:","bold":true},{"text":" the government's use of "},{"text":"taxation and public spending","bold":true},{"text":" to influence the economy."}]},{"text":[{"text":"Taxes:","bold":true},{"text":" a major source of government revenue (income tax, companies income tax, value added tax (VAT), customs duties)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In a free market the government "},{"text":"sets and enforces the rules","bold":true},{"text":"; it does not fix all prices, direct all firms or cancel market forces (those describe a command economy)."}]},{"text":[{"text":"Regulation","bold":true},{"text":" protects stakeholders. Nigerian examples: the "},{"text":"Federal Competition and Consumer Protection Commission (FCCPC)","bold":true},{"text":" fights unfair competition and protects consumers; "},{"text":"SON","bold":true},{"text":" (Standards Organisation of Nigeria) sets product standards; "},{"text":"NAFDAC","bold":true},{"text":" regulates food and drugs; "},{"text":"SEC","bold":true},{"text":" regulates the capital market; "},{"text":"CAC","bold":true},{"text":" (Corporate Affairs Commission) registers businesses under the Companies and Allied Matters Act (CAMA) 2020."}]},{"text":[{"text":"Monetary tools:","bold":true},{"text":" raising interest rates and reducing money supply to fight inflation (tight policy); lowering rates to boost borrowing and growth (loose policy)."}]},{"text":[{"text":"Fiscal tools:","bold":true},{"text":" cutting taxes or raising spending to stimulate a slow economy; raising taxes or cutting spending to cool an overheating one."}]},{"text":[{"text":"Trap:","bold":true},{"text":" monetary = central bank, money and interest rates. Fiscal = government, taxes and spending. Exams swap them."}]}]}]},{"number":"2.6","title":"Economic measures and monitors","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Gross Domestic Product (GDP):","bold":true},{"text":" the total value of all final goods and services produced "},{"text":"within a country's borders","bold":true},{"text":" in a given period (usually a year), whoever owns the producers. It is the main measure of "},{"text":"economic growth","bold":true},{"text":" and a key macroeconomic indicator."}]},{"text":[{"text":"Gross National Product (GNP):","bold":true},{"text":" the total value of goods and services produced by a country's "},{"text":"citizens and businesses","bold":true},{"text":", wherever in the world they are located."}]},{"text":[{"text":"Per capita income:","bold":true},{"text":" national income divided by population; average income per person."}]},{"text":[{"text":"Consumer Price Index (CPI):","bold":true},{"text":" measures changes over time in the prices of a \"basket\" of goods and services typically bought by consumers; the main measure of "},{"text":"inflation","bold":true},{"text":"."}]},{"text":[{"text":"Producer Price Index (PPI):","bold":true},{"text":" measures changes over time in the prices producers receive for their goods (wholesale prices); it often signals future consumer price changes."}]},{"text":[{"text":"Unemployment rate:","bold":true},{"text":" the percentage of the labour force actively seeking work but without a job."}]}]},{"type":"paragraph","text":[{"text":"Measures and monitors of an economy:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"GDP and per capita income."}]},{"text":[{"text":"Level of investment (e.g. foreign direct investment, FDI) and volume of international trade (export trade, and non-oil exports in Nigeria)."}]},{"text":[{"text":"Inflation rate and CPI; consumption level and the purchasing power of the currency (e.g. the naira)."}]},{"text":[{"text":"National employment figures and the unemployment level or rate."}]},{"text":[{"text":"Level of infrastructural development."}]},{"text":[{"text":"Non-economic metrics: life expectancy, poverty rate, literacy rate, political stability."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"GDP vs GNP:","bold":true},{"text":" profits made in Nigeria by a foreign-owned company count in Nigeria's "},{"text":"GDP","bold":true},{"text":" but in its home country's "},{"text":"GNP","bold":true},{"text":". Income earned abroad by Nigerian firms counts in Nigeria's GNP, not its GDP."}]},{"text":[{"text":"In Nigeria, GDP, CPI and unemployment figures are published by the "},{"text":"National Bureau of Statistics (NBS)","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" GDP measures growth; CPI measures the price level (inflation); the unemployment rate measures joblessness; interest rates measure the cost of borrowing. Only GDP measures growth directly."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a firm's quarterly earnings, a worker's salary or a company's overheads are "},{"text":"micro","bold":true},{"text":" figures, not macroeconomic indicators."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Economy = framework for producing, distributing and exchanging goods and services; can be national, regional, industry, household or institutional."}]},{"text":[{"text":"Scarcity forces trade-offs; the 4 traditional factors are land, labour, capital, entrepreneurship (not technology)."}]},{"text":[{"text":"Market = price mechanism and private ownership; command = central gove$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 9, $study_guide$rnment allocates; mixed = market freedom plus state control."}]},{"text":[{"text":"Communism: state owns all productive resources; socialism: state owns selected major industries."}]},{"text":[{"text":"Law of demand: lower price, more demanded. Law of supply: higher price, more supplied. Equilibrium where the curves meet."}]},{"text":[{"text":"Market structures: pure competition, monopolistic competition, oligopoly, monopoly (utilities)."}]},{"text":[{"text":"Business cycle: expansion, peak, contraction, trough. Unemployment: frictional, structural, cyclical, seasonal. Inflation = general rise in prices."}]},{"text":[{"text":"Government in a free market enforces fair-play rules, keeps competition, provides public goods, redistributes income, stabilises via monetary (CBN) and fiscal (tax and spending) policy."}]},{"text":[{"text":"GDP measures growth (within borders); GNP counts citizens' output anywhere; CPI tracks consumer prices; PPI tracks producer prices."}]}]}],"theory":{"itemId":"a920fd06-e86d-5415-ba0d-9a989c7f7d21","question":[{"type":"paragraph","text":[{"text":"Distinguish between a market economy and a command economy, and explain the role of government in a free-market system."}]}]},"practice":[{"topic":"Understanding Basic Economics","named":false}]}},{"kind":"note","itemId":"d03011c7-23bf-530b-8fb1-301f792707a2","sourceKey":"guide-topic:3","position":3,"payload":{"title":"The Global Marketplace","body":"Why nations trade; absolute and comparative advantage; balance of trade and balance of payments; exchange rates; free trade vs protectionism and the trade barriers; the WTO, IMF, World Bank and the trading blocs; cultural, legal, political and economic differences abroad; the forms of international business; multidomestic, global and transnational strategies.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"Why nations trade; absolute and comparative advantage; balance of trade and balance of payments; exchange rates; free trade vs protectionism and the trade barriers; the WTO, IMF, World Bank and the trading blocs; cultural, legal, political and economic differences abroad; the forms of international business; multidomestic, global and transnational strategies."}],"lessons":[{"number":"3.1","title":"What international trade is and why nations trade","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"International trade:","bold":true},{"text":" the exchange of goods and services across national borders. Trade inside one country is "},{"text":"domestic trade","bold":true},{"text":"."}]},{"text":[{"text":"Global (international) business:","bold":true},{"text":" a business that operates in several countries. A "},{"text":"domestic business","bold":true},{"text":" operates in one country only."}]},{"text":[{"text":"Multinational corporation (MNC):","bold":true},{"text":" a company with operations (offices, factories, sales units) in several national markets, e.g. MTN, Nestlé, Unilever."}]},{"text":[{"text":"Importing:","bold":true},{"text":" buying goods or services from another country. "},{"text":"Exporting:","bold":true},{"text":" producing in one country and selling to buyers in another. Both are forms of global business engagement."}]},{"text":[{"text":"Why nations and firms trade:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To focus on their "},{"text":"strengths","bold":true},{"text":" (what they produce best)."}]},{"text":[{"text":"To "},{"text":"expand markets","bold":true},{"text":": broader market access and more customers."}]},{"text":[{"text":"To pursue "},{"text":"economies of scale","bold":true},{"text":" (lower cost per unit from larger output)."}]},{"text":[{"text":"To "},{"text":"acquire","bold":true},{"text":" materials, goods and services they lack or cannot make cheaply."}]},{"text":[{"text":"To "},{"text":"keep up with customers","bold":true},{"text":" who have gone international."}]},{"text":[{"text":"To "},{"text":"keep up with competitors","bold":true},{"text":" already abroad."}]}]}]}]},{"type":"table","header":[[{"text":"Term"}],[{"text":"Meaning"}],[{"text":"Credited to"}]],"rows":[[[{"text":"Absolute advantage","bold":true}],[{"text":"A country can produce a good "},{"text":"more efficiently","bold":true},{"text":" (with fewer resources) than any other country"}],[{"text":"Adam Smith"}]],[[{"text":"Comparative advantage","bold":true}],[{"text":"A country produces the goods it makes "},{"text":"relatively","bold":true},{"text":" most efficiently (lowest opportunity cost) and trades for the rest, even if it is not the best at anything"}],[{"text":"David Ricardo"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"International trade is "},{"text":"driven by comparative advantage","bold":true},{"text":". Nigeria exports crude oil and imports machinery because each country gains by specialising where its opportunity cost is lowest."}]},{"text":[{"text":"Example of comparative advantage: suppose Country A can make both cloth and cocoa faster than Country B, but its lead is much bigger in cloth. A should specialise in cloth and B in cocoa; both end up with more by trading."}]},{"text":[{"text":"Benefits of trade:","bold":true},{"text":" broader market access, lower costs through scale, wider choice of products, access to resources and technology. "},{"text":"Trap:","bold":true},{"text":" \"higher production costs\" and \"narrower product range\" are not benefits; trade tends to lower costs and widen choice."}]},{"text":[{"text":"A franchise or a partnership is a form of ownership or arrangement; neither term by itself means a firm operates in several countries."}]}]}]},{"number":"3.2","title":"Measuring trade and exchange rates","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Balance of trade:","bold":true},{"text":" the difference between the value of a country's "},{"text":"exports","bold":true},{"text":" and the value of its "},{"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 10, $study_guide$text":"imports","bold":true},{"text":" over a period (goods and services)."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trade surplus (favourable balance):","bold":true},{"text":" exports > imports."}]},{"text":[{"text":"Trade deficit (unfavourable balance):","bold":true},{"text":" imports > exports."}]}]}]},{"text":[{"text":"Balance of payments:","bold":true},{"text":" the "},{"text":"total","bold":true},{"text":" of all money flowing into and out of a country over a period. It includes the balance of trade "},{"text":"plus","bold":true},{"text":" investment flows, foreign aid, loans, interest, dividends and transfers (e.g. remittances). It is the broader measure."}]},{"text":[{"text":"Exchange rate:","bold":true},{"text":" the rate at which one country's currency can be exchanged for another's, e.g. ₦ per US dollar."}]},{"text":[{"text":"Floating exchange rate:","bold":true},{"text":" set mainly by demand and supply in the currency market. "},{"text":"Fixed (pegged) rate:","bold":true},{"text":" held by the government or central bank at a set level."}]}]},{"type":"table","header":[[{"text":"If the naira"}],[{"text":"Nigerian exports become"}],[{"text":"Imports into Nigeria become"}]],"rows":[[[{"text":"Weakens","bold":true},{"text":" (more ₦ per $; depreciation or devaluation)"}],[{"text":"Cheaper to foreigners (helps exporters)"}],[{"text":"Dearer (hurts importers)"}]],[[{"text":"Strengthens","bold":true},{"text":" (fewer ₦ per $)"}],[{"text":"Dearer to foreigners"}],[{"text":"Cheaper"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" balance of trade is "},{"text":"not","bold":true},{"text":" GDP (total output), employment levels or inflation (price increases). It is only the export-import difference."}]},{"text":[{"text":"Trap:","bold":true},{"text":" balance of trade covers trade only; balance of payments covers trade "},{"text":"and","bold":true},{"text":" all other money flows. A country can have a trade deficit but still receive large inflows, e.g. foreign investment or diaspora remittances."}]},{"text":[{"text":"In Nigeria the Central Bank of Nigeria (CBN) manages monetary and exchange-rate policy. Exchange-rate movements are part of the economic environment of global business: a firm that buys raw materials in dollars and sells in naira is hurt when the naira falls."}]}]}]},{"number":"3.3","title":"Conflicts in international trade","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Free trade:","bold":true},{"text":" international trade with no government barriers. Supported because it raises efficiency, lowers prices and widens choice."}]},{"text":[{"text":"Protectionism:","bold":true},{"text":" government policies that restrict imports to protect domestic industries and jobs."}]},{"text":[{"text":"Trade conflicts","bold":true},{"text":" arise mainly from "},{"text":"barriers like import duties","bold":true},{"text":", tariffs and quotas, which can trigger retaliation (a "},{"text":"trade war","bold":true},{"text":"), e.g. the US-China trade tensions in which each side raised tariffs on the other's goods."}]}]},{"type":"paragraph","text":[{"text":"Main trade barriers and restrictions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Tariff:","bold":true},{"text":" a tax or levy on "},{"text":"imported","bold":true},{"text":" (inbound) goods. Raises the price of foreign products and protects local producers; also earns government revenue."}]},{"text":[{"text":"Import quota:","bold":true},{"text":" a limit on the "},{"text":"quantity","bold":true},{"text":" of a product that may be imported."}]},{"text":[{"text":"Embargo:","bold":true},{"text":" a total "},{"text":"ban","bold":true},{"text":" on trade in a product or with a country (often for political reasons)."}]},{"text":[{"text":"Restrictive import standards:","bold":true},{"text":" strict rules on quality, health, safety or labelling that make importing harder."}]},{"text":[{"text":"Export subsidy:","bold":true},{"text":" government payment or aid to domestic exporters so they can sell more cheaply abroad."}]},{"text":[{"text":"Sanctions:","bold":true},{"text":" politically motivated restrictions on trade with a country."}]},{"text":[{"text":"Anti-dumping measures:","bold":true},{"text":" actions against "},{"text":"dumping","bold":true},{"text":", i.e. selling goods abroad below cost or below the price charged at home, often to drive out local competitors."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" a tariff is "},{"text":"not","bold":true},{"text":" an export incentive payment (that is a subsidy), not a type of money (currency) and not a trade agreement."}]},{"text":[{"text":"Tariff vs quota:","bold":true},{"text":" a tariff works through "},{"text":"price","bold":true},{"text":"; a quota works through "},{"text":"quantity","bold":true},{"text":". An embargo is the extreme case: quantity is zero."}]},{"text":[{"text":"In Nigeria, import duties are collected by the Nigeria Customs Service. Restrictive standards are applied through bodies such as the Standards Organisation of Nigeria (SON)."}]},{"text":[{"text":"Arguments for protection: protect infant industries, save jobs, national security, fight unfair practices like dumping. Arguments against: higher prices for consumers, less choice, inefficient local firms and retaliation. Open policies, cooperative alliances and stable exchange rates tend to "},{"text":"reduce","bold":true},{"text":" conflict, not cause it."}]}]}]},{"number":"3.4","title":"International trade organisations and trading blocs","mustKnow":[{"type":"table","header":[[{"text":"Organisation"}],[{"text":"Main role"}]],"rows":[[[{"text":"WTO","bold":true},{"text":" (World Trade Organization), 1995, Geneva; replaced GATT"}],[{"text":"Promotes free and fair trade globally","bold":true},{"text":": sets trade $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 11, $study_guide$rules, negotiates trade agreements, settles trade disputes"}]],[[{"text":"IMF","bold":true},{"text":" (International Monetary Fund)"}],[{"text":"Promotes "},{"text":"financial and exchange-rate stability","bold":true},{"text":"; lends to countries with balance-of-payments problems"}]],[[{"text":"World Bank","bold":true}],[{"text":"Lends and gives aid for "},{"text":"long-term development","bold":true},{"text":" projects (roads, power, health, education) in developing countries"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Trading bloc:","bold":true},{"text":" a group of countries that reduce trade barriers among themselves and often act together on trade."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"ECOWAS","bold":true},{"text":" (Economic Community of West African States): founded 1975 by the Treaty of Lagos; promotes economic integration and free movement of people and goods in West Africa. Nigeria is a member."}]},{"text":[{"text":"AU","bold":true},{"text":" (African Union): replaced the Organisation of African Unity (OAU) in 2002; HQ Addis Ababa. Its "},{"text":"AfCFTA","bold":true},{"text":" (African Continental Free Trade Area) aims at a single African market."}]},{"text":[{"text":"EU","bold":true},{"text":" (European Union): European states with a single market; many share one currency, the "},{"text":"euro","bold":true},{"text":"."}]},{"text":[{"text":"NAFTA / USMCA:","bold":true},{"text":" the North American Free Trade Agreement (USA, Canada, Mexico) was replaced in 2020 by the "},{"text":"United States-Mexico-Canada Agreement (USMCA)","bold":true},{"text":"."}]},{"text":[{"text":"APEC","bold":true},{"text":" (Asia-Pacific Economic Cooperation): Pacific Rim economies (including the USA, China, Japan and Australia) promoting freer trade in the region."}]},{"text":[{"text":"ASEAN","bold":true},{"text":" (Association of Southeast Asian Nations)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the question \"which organisation promotes free trade globally?\" is the "},{"text":"WTO","bold":true},{"text":", not the IMF (finance), the UN (peace and security) or the WHO (health)."}]},{"text":[{"text":"IMF vs World Bank:","bold":true},{"text":" IMF = short-term financial stability and currency problems; World Bank = long-term development projects. Both were created at Bretton Woods in 1944 and are based in Washington, DC."}]},{"text":[{"text":"Blocs encourage trade "},{"text":"inside","bold":true},{"text":" the bloc but can make it harder for outsiders. ECOWAS, for instance, has a common external tariff applied to goods from outside the region."}]}]}]},{"number":"3.5","title":"The global business environment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Global business environment:","bold":true},{"text":" the many forces that affect how a firm operates abroad, especially "},{"text":"cultural, political (legal) and economic","bold":true},{"text":" differences between countries. It is never just one factor (only money, only technology or only regulation)."}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cultural differences:","bold":true},{"text":" language, religion, values, customs, social behaviour, attitudes to time, gift-giving, negotiation styles and body language. "},{"text":"Ethnocentrism","bold":true},{"text":" (judging others by your own culture) and "},{"text":"stereotyping","bold":true},{"text":" cause failure abroad."}]},{"text":[{"text":"Legal and political differences:","bold":true},{"text":" each country has its own laws on contracts, tax, ownership, labour and product standards; political stability and government attitudes to foreign firms vary. "},{"text":"Bribery","bold":true},{"text":" is illegal in most countries, e.g. the US Foreign Corrupt Practices Act forbids US firms to bribe foreign officials."}]},{"text":[{"text":"Economic differences:","bold":true},{"text":" level of development, income, infrastructure, inflation and "},{"text":"currency exchange rates","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A firm entering a new country must research its culture: a product name, colour or advert that works in Lagos may offend or confuse buyers elsewhere."}]},{"text":[{"text":"Trap:","bold":true},{"text":" ignoring local customs is a common reason firms fail abroad; it is never a sound strategy."}]},{"text":[{"text":"Political risk includes sudden policy changes, import bans, nationalisation of foreign assets and unrest."}]}]}]},{"number":"3.6","title":"Forms of international business and strategic approaches","mustKnow":[{"type":"paragraph","text":[{"text":"Forms of international business activity","bold":true},{"text":" (roughly from least to most commitment and risk):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Importing and exporting:","bold":true},{"text":" buying from and selling to other countries; the simplest entry."}]},{"text":[{"text":"International licensing:","bold":true},{"text":" a firm lets a foreign company use its patent, trademark, technology or brand for a fee ("},{"text":"royalty","bold":true},{"text":")."}]},{"text":[{"text":"International franchising:","bold":true},{"text":" a franchisor lets a foreign franchisee run a business under its name and system for fees, e.g. fast-food chains."}]},{"text":[{"text":"Contract manufacturing:","bold":true},{"text":" a firm pays a foreign producer to make its goods, which it then sells under its own name."}]},{"text":[{"text":"Strategic alliance:","bold":true},{"text":" a long-term partnership between firms to share resources or knowledge, "},{"text":"without","bold":true},{"text":" creating a new company."}]},{"text":[{"text":"Joint venture:","bold":true},{"text":" two or more firms (often a foreign and a local one) jointly "},{"text":"create and own","bold":tru$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 12, $study_guide$e},{"text":" a new business, sharing costs, risks and profits."}]},{"text":[{"text":"Foreign direct investment (FDI):","bold":true},{"text":" owning physical assets in another country, e.g. building a factory or buying a local firm, often run as a "},{"text":"subsidiary","bold":true},{"text":". Firms that do this widely become "},{"text":"multinational corporations","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Strategic approaches to international markets:","bold":true}]},{"type":"table","header":[[{"text":"Approach"}],[{"text":"Product and marketing"}],[{"text":"Also called"}]],"rows":[[[{"text":"Multidomestic","bold":true}],[{"text":"Each country unit operates fairly independently; offerings "},{"text":"tailored","bold":true},{"text":" to each local market"}],[{"text":"Adaptation"}]],[[{"text":"Global","bold":true}],[{"text":"Same","bold":true},{"text":" product and marketing worldwide, controlled from headquarters; lowest cost"}],[{"text":"Standardisation"}]],[[{"text":"Transnational","bold":true}],[{"text":"Mix: global efficiency where possible, local adaptation where needed (\"think globally, act locally\")"}],[]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A sound international strategy usually involves "},{"text":"tailoring offerings to regions","bold":true},{"text":" (adaptation) to suit local tastes, culture and needs. Overlooking local customs, shunning rivals or cutting exports are not strategies."}]},{"text":[{"text":"Standardisation vs adaptation:","bold":true},{"text":" standardisation gives economies of scale and one brand image; adaptation fits local markets better but costs more."}]},{"text":[{"text":"Licensing vs franchising:","bold":true},{"text":" licensing transfers the right to use a patent, trademark or technology; franchising transfers a whole way of running the business."}]},{"text":[{"text":"Strategic alliance vs joint venture:","bold":true},{"text":" both are partnerships; only a joint venture creates a "},{"text":"new jointly owned entity","bold":true},{"text":"."}]},{"text":[{"text":"Exporting, licensing and franchising need little investment and carry low risk, but give less control. FDI gives most control and profit but carries most risk."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"International trade = cross-border exchange of goods and services, driven by comparative advantage."}]},{"text":[{"text":"Absolute advantage (Smith) = most efficient producer; comparative advantage (Ricardo) = lowest opportunity cost."}]},{"text":[{"text":"Balance of trade = exports minus imports; balance of payments = all money flows in and out."}]},{"text":[{"text":"A weaker naira makes exports cheaper and imports dearer."}]},{"text":[{"text":"Barriers: tariffs (levy on imports), quotas, embargoes, standards, subsidies, sanctions, anti-dumping; barriers like import duties cause trade conflicts."}]},{"text":[{"text":"WTO = free trade; IMF = financial stability; World Bank = development. Blocs: ECOWAS, AU, EU, USMCA, APEC, ASEAN."}]},{"text":[{"text":"Global environment = cultural, political/legal and economic differences."}]},{"text":[{"text":"Forms: import/export, licensing, franchising, contract manufacturing, alliances, joint ventures, FDI; an MNC operates in several national markets."}]},{"text":[{"text":"Strategies: multidomestic (adapt), global (standardise), transnational (mix)."}]}]}],"theory":{"itemId":"f4adf133-ee00-5bcd-a52b-549479b7fd84","question":[{"type":"paragraph","text":[{"text":"Explain four forms of international business activity a Nigerian firm could use to enter a foreign market."}]}]},"practice":[{"topic":"The Global Marketplace","named":false}]}},{"kind":"note","itemId":"a2b5c425-5cbd-5484-9cc8-9ccaa7ac9fbf","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Business Ethics and Corporate Social Responsibility","body":"What ethics and business ethics mean; unethical behaviour and what shapes behaviour; ethical dilemmas versus ethical lapses and how to make ethical decisions; CSR and its four perspectives; CSR towards the natural environment, consumers, employees and the community.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"What ethics and business ethics mean; unethical behaviour and what shapes behaviour; ethical dilemmas versus ethical lapses and how to make ethical decisions; CSR and its four perspectives; CSR towards the natural environment, consumers, employees and the community."}],"lessons":[{"number":"4.1","title":"Ethics and ethical behaviour in business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ethics:","bold":true},{"text":" the rules or standards of right and wrong that govern the conduct of a person or a group."}]},{"text":[{"text":"Business ethics:","bold":true},{"text":" the standards of right and wrong (moral principles such as "},{"text":"honesty","bold":true},{"text":" and "},{"text":"fairness","bold":true},{"text":") that guide the decisions and behaviour of a business and its people."}]},{"text":[{"text":"Ethical company:","bold":true},{"text":" one that holds itself to standards that consider the needs of all its "},{"text":"stakeholders","bold":true},{"text":", not only its owners."}]},{"text":[{"text":"Stakeholders:","bold":true},{"text":" groups affected by, or able to affect, a business: owners/shareholders, employees, customers, suppliers, the community, government and society at large."}]}]},{"type":"paragraph","text":[{"text":"Three marks of unethical behaviour:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Competing unfairly and dishonestly:","bold":true},{"text":" bribery, fixing prices with rivals, stealing trade secrets, "},{"text":"insider trading","bold":true},{"text":" (using confidential company information to buy or sell shares)."}]},{"text":[{"text":"Communicating untruthfully:","bold":true},{"text":" false or misleading advertising, hiding pro$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 13, $study_guide$duct defects, falsifying financial records."}]},{"text":[{"text":"Causing harm to others:","bold":true},{"text":" selling unsafe products, polluting, exploiting workers, cheating investors."}]}]},{"type":"paragraph","text":[{"text":"Factors that influence ethical behaviour:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Cultural differences:","bold":true},{"text":" what is acceptable (gifts, payments, hiring relatives) varies between countries and communities."}]},{"text":[{"text":"Knowledge:","bold":true},{"text":" people sometimes act wrongly because they do not know the facts, the law or the consequences."}]},{"text":[{"text":"Organisational behaviour:","bold":true},{"text":" the company's culture, leadership example, rewards and pressures."}]}]},{"type":"paragraph","text":[{"text":"Tools firms use to promote ethics:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Code of ethics:","bold":true},{"text":" a written statement of the principles that guide an organisation's decisions."}]},{"text":[{"text":"Ethics training","bold":true},{"text":" and ethics officers or hotlines."}]},{"text":[{"text":"Whistle-blowing:","bold":true},{"text":" disclosure by an insider of illegal or unethical conduct by others in the organisation."}]}]},{"type":"paragraph","text":[{"text":"Benefits of ethical practice:","bold":true},{"text":" enhanced "},{"text":"brand reputation","bold":true},{"text":", customer trust and loyalty, higher staff morale and retention, investor confidence, fewer fines and lawsuits."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Legal is not the same as ethical.","bold":true},{"text":" The law sets the minimum. An act can be legal yet unethical (charging desperate customers outrageous prices during a fuel scarcity), so ethics usually asks more than the law does."}]},{"text":[{"text":"Top managers "},{"text":"set the tone","bold":true},{"text":". A strong code of ethics means little if leaders reward results \"by any means\". In companies, the board of directors also sets the tone for ethical behaviour and can remove managers who behave unethically."}]},{"text":[{"text":"Unethical behaviour produces the opposite of the benefits: eroded consumer confidence, increased litigation costs, lower staff morale, regulatory sanctions and a damaged name."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"profit pursuit above all\", \"neglecting worker rights\" and \"bypassing legal oversight\" describe unethical conduct; they are never definitions of business ethics."}]}]}]},{"number":"4.2","title":"Ethical dilemmas, ethical lapses and making ethical decisions","mustKnow":[{"type":"table","header":[[],[{"text":"Ethical dilemma"}],[{"text":"Ethical lapse"}]],"rows":[[[{"text":"Meaning"}],[{"text":"A situation where "},{"text":"more than one side","bold":true},{"text":" of an issue can be supported with "},{"text":"valid arguments","bold":true}],[{"text":"A situation where an individual or group makes a decision that is clearly "},{"text":"wrong, illegal or unethical","bold":true}]],[[{"text":"Is the right answer clear?"}],[{"text":"No; it is a choice between competing goods or interests"}],[{"text":"Yes; the person knows (or should know) it is wrong"}]],[[{"text":"Example"}],[{"text":"Closing a loss-making plant to save the company, which costs local jobs"}],[{"text":"Inflating expense claims; selling expired drugs"}]]]},{"type":"paragraph","text":[{"text":"Four questions for making an ethical decision:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Is it legal?","bold":true},{"text":" Does it break any law or company policy?"}]},{"text":[{"text":"Is it balanced?","bold":true},{"text":" Is it fair to everyone affected in the short and long term?"}]},{"text":[{"text":"Can you live with it?","bold":true},{"text":" Would you be comfortable if your family or the newspapers knew about it?"}]},{"text":[{"text":"Is it feasible?","bold":true},{"text":" Can it actually work in the real world?"}]}]},{"type":"paragraph","text":[{"text":"Common ways of judging right and wrong:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Utilitarianism:","bold":true},{"text":" choose the action that gives the greatest good to the greatest number of people."}]},{"text":[{"text":"Individual rights:","bold":true},{"text":" respect people's basic rights (life, privacy, free speech, fair treatment)."}]},{"text":[{"text":"Justice:","bold":true},{"text":" treat people fairly and consistently, distributing benefits and burdens fairly."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In a "},{"text":"dilemma","bold":true},{"text":", both choices can be defended: a manager may be torn between loyalty to a long-serving supplier and a cheaper new one. The difficulty is not knowing the rule but weighing interests."}]},{"text":[{"text":"In a "},{"text":"lapse","bold":true},{"text":", the right choice is obvious and the person simply fails to make it, often under pressure to meet targets."}]},{"text":[{"text":"Trap:","bold":true},{"text":" exams swap the two definitions. \"Valid arguments on more than one side\" = "},{"text":"dilemma","bold":true},{"text":". \"Clearly wrong decision\" = "},{"text":"lapse","bold":true},{"text":"."}]},{"text":[{"text":"True professionals avoid committing ethical lapses and carefully weigh all the options when facing ethical dilemmas."}]}]}]},{"number":"4.3","title":"Corporate social responsibility and its perspectives","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporate social responsibility (CSR):","bold":true},{"text":" the idea that a business has obligations to society "},{"text":"beyond","bold":true},{"text":" its obligation to its owners or shareholders; a "},{"text":"duty to contribute to the well-being of society","bold":true},{"text":", not only to make profit."}]},{"text":[{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 14, $study_guide$:"CSR covers four broad groups: the "},{"text":"natural environment","bold":true},{"text":", "},{"text":"consumers","bold":true},{"text":", "},{"text":"employees","bold":true},{"text":" and the "},{"text":"community","bold":true},{"text":" (plus investors)."}]}]},{"type":"paragraph","text":[{"text":"Four perspectives on CSR:","bold":true}]},{"type":"table","header":[[{"text":"Perspective"}],[{"text":"Core view"}]],"rows":[[[{"text":"1. Minimalist","bold":true}],[{"text":"A firm's only social responsibility is to make "},{"text":"profits for its owners within the law","bold":true},{"text":" (obey laws, pay taxes)."}]],[[{"text":"2. Defensive","bold":true}],[{"text":"Firms engage in CSR mainly to "},{"text":"protect themselves","bold":true},{"text":": to avoid criticism, boycotts or tougher regulation."}]],[[{"text":"3. Cynical","bold":true}],[{"text":"CSR is a "},{"text":"public-relations or marketing tool","bold":true},{"text":"; firms adopt it only because it pays, often doing little real good."}]],[[{"text":"4. Proactive","bold":true}],[{"text":"CSR is a "},{"text":"moral obligation","bold":true},{"text":"; businesses have a duty to contribute to society because it is right, and see it as part of doing business."}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Philanthropy:","bold":true},{"text":" donating money, staff time or other resources to social causes "},{"text":"without expecting a direct business benefit","bold":true},{"text":"."}]},{"text":[{"text":"Strategic CSR:","bold":true},{"text":" social contributions "},{"text":"aligned with the company's overall business strategy","bold":true},{"text":", so that both society and the company benefit."}]}]},{"type":"paragraph","text":[{"text":"Carroll's four responsibilities","bold":true},{"text":" (bottom to top of the pyramid):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Economic:","bold":true},{"text":" be profitable (the base on which everything else rests)."}]},{"text":[{"text":"Legal:","bold":true},{"text":" obey the law."}]},{"text":[{"text":"Ethical:","bold":true},{"text":" do what is right and fair, beyond what the law requires."}]},{"text":[{"text":"Philanthropic:","bold":true},{"text":" be a good corporate citizen; give back to the community."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"minimalist","bold":true},{"text":" view is the "},{"text":"economic perspective","bold":true},{"text":", linked with the economist Milton Friedman: the business of business is to make profit, staying within the rules. Note that it does "},{"text":"not","bold":true},{"text":" say \"ignore society\" or \"exclude stakeholders\"; it says the firm serves society by making lawful profit, paying taxes and providing jobs."}]},{"text":[{"text":"The "},{"text":"proactive","bold":true},{"text":" view is the "},{"text":"duty-based (ethical) stance","bold":true},{"text":": CSR is done because it is morally right. A "},{"text":"compliance-focused","bold":true},{"text":" lens matches the defensive view; a "},{"text":"profit-driven","bold":true},{"text":" lens matches the minimalist or cynical view; a "},{"text":"charitable-giving","bold":true},{"text":" angle is philanthropy only."}]},{"text":[{"text":"Greenwashing","bold":true},{"text":" (exaggerating how environmentally friendly a firm is) is typical of the cynical view."}]},{"text":[{"text":"Strategic CSR example:","bold":true},{"text":" a telecoms company funding digital-skills training for young people builds future customers and staff while helping society. "},{"text":"Philanthropy example:","bold":true},{"text":" a bank donating to flood victims with no link to its business."}]},{"text":[{"text":"CSR towards the community","bold":true},{"text":" includes backing local nonprofits and charities, funding schools, scholarships, health centres and roads, employing local people and buying from local suppliers. Many large Nigerian firms, such as Dangote, MTN and the banks, run foundations for this purpose."}]},{"text":[{"text":"Remember the positive role of business in society: offering valuable goods and services, providing employment, paying taxes and contributing to national growth, stability and security. Its potential negative effects: generating pollution and waste, creating health and safety risks, disrupting communities and causing financial instability. CSR aims to increase the first and reduce the second."}]}]}]},{"number":"4.4","title":"CSR towards the natural environment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Pollution:","bold":true},{"text":" damage to the air, water or land caused by waste, chemicals, smoke, noise and other harmful releases."}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Air pollution:","bold":true},{"text":" factory and generator fumes, vehicle exhaust, "},{"text":"gas flaring","bold":true},{"text":"."}]},{"text":[{"text":"Water pollution:","bold":true},{"text":" oil spills, untreated industrial waste discharged into rivers and lagoons."}]},{"text":[{"text":"Land pollution:","bold":true},{"text":" dumping of solid and toxic waste, plastics."}]}]}]},{"text":[{"text":"Carbon footprint:","bold":true},{"text":" the total greenhouse gases (mainly carbon dioxide) produced by an organisation's activities."}]},{"text":[{"text":"Sustainability (sustainable development):","bold":true},{"text":" meeting the needs of the present "},{"text":"without compromising the ability of future generations to meet their own needs","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Responsible environmental actions:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Lowering carbon footprints","bold":true},{"text":" (cleaner energy, efficient machines and transport)."}]},{"text":[{"text":"Proper "},{"text":"waste management","bold":true},{"text":": reduce, reuse, recycle."}]},{"text":[{"text":"Con$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 15, $study_guide$serving natural resources","bold":true},{"text":" (water, forests, energy) rather than depleting them."}]},{"text":[{"text":"Obeying environmental regulations","bold":true},{"text":" and cleaning up damage caused."}]},{"text":[{"text":"Designing greener products and packaging."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In Nigeria, the "},{"text":"National Environmental Standards and Regulations Enforcement Agency (NESREA)","bold":true},{"text":" enforces environmental standards, and oil spills and gas flaring in the Niger Delta are the best-known local examples of corporate environmental harm."}]},{"text":[{"text":"Trade-offs:","bold":true},{"text":" going green can raise costs in the short run, which is why some firms resist. Proactive firms see sustainability as a long-term saving and a source of reputation."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"boosting emissions\", \"disregarding regulations\" and \"depleting natural reserves\" are the opposite of environmental CSR. The correct answer is always the one that "},{"text":"reduces harm","bold":true},{"text":", such as lowering carbon footprints."}]}]}]},{"number":"4.5","title":"CSR towards consumers and employees","mustKnow":[{"type":"paragraph","text":[{"text":"Consumer rights","bold":true},{"text":" (first set out by US President John F. Kennedy in 1962):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"The right to safety:","bold":true},{"text":" to buy products that are safe to use."}]},{"text":[{"text":"The right to be informed:","bold":true},{"text":" to honest, clear information (labels, prices, ingredients, risks)."}]},{"text":[{"text":"The right to choose:","bold":true},{"text":" to choose freely among competing products at fair prices."}]},{"text":[{"text":"The right to be heard:","bold":true},{"text":" to have complaints listened to and handled."}]}]},{"type":"paragraph","text":[{"text":"Later additions: the right to "},{"text":"redress","bold":true},{"text":" (compensation for faulty goods), to "},{"text":"consumer education","bold":true},{"text":", to "},{"text":"privacy","bold":true},{"text":" of personal data and to a "},{"text":"healthy environment","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"CSR towards consumers","bold":true},{"text":" means "},{"text":"ensuring product safety and clarity","bold":true},{"text":": safe products, honest advertising, clear labels, fair pricing, good quality and listening to customer complaints."}]}]},{"type":"paragraph","text":[{"text":"CSR towards employees:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Equality:","bold":true},{"text":" equal opportunity in hiring, pay and promotion regardless of sex, religion, ethnicity or disability; no discrimination or harassment."}]},{"text":[{"text":"Fair (equitable) pay","bold":true},{"text":" and benefits."}]},{"text":[{"text":"Occupational safety and health:","bold":true},{"text":" a safe, healthy workplace, protective equipment and training."}]},{"text":[{"text":"Respect for "},{"text":"workers' rights","bold":true},{"text":", reasonable hours and paid overtime."}]},{"text":[{"text":"Training and career development."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Nigerian consumer bodies: the "},{"text":"Federal Competition and Consumer Protection Commission (FCCPC)","bold":true},{"text":", set up under the Federal Competition and Consumer Protection Act 2018; "},{"text":"NAFDAC","bold":true},{"text":" (food and drugs); the "},{"text":"Standards Organisation of Nigeria (SON)","bold":true},{"text":" (product standards)."}]},{"text":[{"text":"Breaching consumer CSR: selling fake or expired drugs, short-measuring goods, hidden charges, ignoring complaints, lowering quality while keeping the price."}]},{"text":[{"text":"Equality","bold":true},{"text":" at work also means valuing "},{"text":"diversity","bold":true},{"text":": a workforce of different backgrounds, ages, sexes and abilities, with reasonable accommodation for people with disabilities."}]},{"text":[{"text":"Safety:","bold":true},{"text":" construction, mining, manufacturing and oil firms carry the highest risks. Skimping on safety measures, overlooking worker rights and extending unpaid hours are clear failures of CSR towards employees; "},{"text":"offering equitable pay","bold":true},{"text":" is a clear example of meeting it."}]},{"text":[{"text":"Trap:","bold":true},{"text":" fair treatment of employees is "},{"text":"not","bold":true},{"text":" charity; it is part of a firm's basic ethical and legal responsibility."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business ethics = standards of right and wrong (honesty, fairness) guiding business conduct."}]},{"text":[{"text":"Unethical behaviour: competing unfairly, communicating untruthfully, causing harm. Influences: culture, knowledge, organisational behaviour."}]},{"text":[{"text":"Ethical behaviour builds brand reputation, trust and morale; code of ethics and whistle-blowing support it."}]},{"text":[{"text":"Dilemma = valid arguments on more than one side; lapse = a clearly wrong decision."}]},{"text":[{"text":"Four questions: legal? balanced? can you live with it? feasible?"}]},{"text":[{"text":"CSR = duty to society's well-being beyond profit. Perspectives: minimalist (profit within the law), defensive, cynical, proactive (moral obligation)."}]},{"text":[{"text":"Philanthropy (giving, no direct benefit) vs strategic CSR (aligned with business strategy)."}]},{"text":[{"text":"Environment: cut pollution and carbon footprint, manage waste, practise sustainability."}]},{"text":[{"text":"Consumers: safety, information, choice, being heard. Employees: equality, fair pay, safety. Community: support local causes."}]}]}],"theory":{"itemId":"63ce438b-49e2-5b06-8a85-df5c773c3a39","question":[{"type":"paragraph","text":[{"text":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 16, $study_guide$Define corporate social responsibility and explain the four perspectives on CSR."}]}]},"practice":[{"topic":"Business Ethics and Corporate Social Responsibility","named":false}]}},{"kind":"note","itemId":"a90608d7-39fa-5c67-b58b-1238ac3fd96d","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Forms of Business Ownership","body":"Sole proprietorship, partnership (types of agreement and partner), companies (private vs public, memorandum and articles, corporation pros and cons), cooperatives, public enterprises and privatisation; corporate governance (principles, actors, board duties, three models); mergers and acquisitions, strategic alliances and joint ventures.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"Sole proprietorship, partnership (types of agreement and partner), companies (private vs public, memorandum and articles, corporation pros and cons), cooperatives, public enterprises and privatisation; corporate governance (principles, actors, board duties, three models); mergers and acquisitions, strategic alliances and joint ventures."}],"lessons":[{"number":"5.1","title":"Forms of ownership and the sole proprietorship","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Form of business ownership:","bold":true},{"text":" the category a business is registered under with government. It decides how much ownership and managerial control the owner has, how the business pays tax and how far the owner is personally liable if the business fails."}]},{"text":[{"text":"Liability:","bold":true},{"text":" "},{"text":"unlimited","bold":true},{"text":" = the owner's personal property (house, car, savings) can be taken to pay business debts, so he can lose everything; "},{"text":"limited","bold":true},{"text":" = owners lose at most what they invested."}]},{"text":[{"text":"Sole proprietorship:","bold":true},{"text":" a business in which a "},{"text":"single person owns, finances, manages and controls","bold":true},{"text":" all its activities, with all the authority, responsibility and risk. It is the "},{"text":"most common (numerous)","bold":true},{"text":" form of business."}]}]},{"type":"paragraph","text":[{"text":"Features:","bold":true},{"text":" no separation of ownership and management · easy set-up (minimal formalities) · owner keeps all profit · unlimited liability · single ownership · profit taxed "},{"text":"once","bold":true},{"text":", as the owner's personal income."}]},{"type":"table","header":[[{"text":"Advantages"}],[{"text":"Disadvantages"}]],"rows":[[[{"text":"Independence and full control (the single most important advantage)"}],[{"text":"Unlimited liability"}]],[[{"text":"Quick decisions (no hierarchy)"}],[{"text":"Limited capital"}]],[[{"text":"Possible tax benefits (losses offset personal income)"}],[{"text":"Limited managerial expertise"}]],[[{"text":"Flexibility; easy to form and wind up"}],[{"text":"Uncertain continuity (depends on owner's life and health)"}]],[[{"text":"Owner keeps all profit"}],[{"text":"Not suitable for large-scale operations"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A sole proprietor "},{"text":"cannot issue or sell stock (shares)","bold":true},{"text":"; only companies can. \"Profits taxed twice\" is a "},{"text":"company","bold":true},{"text":" feature, never a sole proprietorship one."}]},{"text":[{"text":"A sole trader who registers a business name with the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":" still has "},{"text":"unlimited","bold":true},{"text":" liability: a business name is not a company."}]},{"text":[{"text":"Examples: a provision shop, a tailor, a barber or a phone-repair stand on campus."}]}]}]},{"number":"5.2","title":"Partnerships","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Partnership:","bold":true},{"text":" a business relation between "},{"text":"two or more persons","bold":true},{"text":" who join hands, finance and skills to form a business with the objective of a profitable return. Partners "},{"text":"divide the profits","bold":true},{"text":" among themselves, usually by their agreement."}]},{"text":[{"text":"In a "},{"text":"general partnership","bold":true},{"text":" liability is "},{"text":"unlimited","bold":true},{"text":" and "},{"text":"each partner","bold":true},{"text":" can be held liable for the business's "},{"text":"entire","bold":true},{"text":" debt. Partners have "},{"text":"joint authority","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Features (5):","bold":true},{"text":" agreement between partners · shared ownership · sharing of profit (and, implicitly, loss) · mutual business (each partner is owner "},{"text":"and agent","bold":true},{"text":"; one partner's act binds all, the test of partnership) · unlimited liability."}]},{"type":"table","header":[[{"text":"Advantages"}],[{"text":"Disadvantages"}]],"rows":[[[{"text":"Shared responsibility"}],[{"text":"Unlimited (full personal) liability in general partnerships"}]],[[{"text":"Complementary skills"}],[{"text":"Conflict between partners"}]],[[{"text":"Easier capital access than a sole trader"}],[{"text":"Shared profits can cause disputes"}]],[[{"text":"Profits taxed as personal income"}],[{"text":"Limited life span (withdrawal, death or bankruptcy of a partner)"}]],[[{"text":"Limited government regulation; low start-up costs"}],[]]]},{"type":"paragraph","text":[{"text":"Partnership deed:","bold":true},{"text":" the legal document founding the firm: names of partners, capital contributions, profit-sharing ratios, decision-making, admission and retirement of partners, dispute resolution, duration, commencement date."}]},{"type":"paragraph","text":[{"text":"Partnership agreement (Articles of Partnership):","bold":true},{"text":" internal contract on management, ownership, investment, profits and losses."}]},{"type":"paragraph","text":[{"text":"3 types:","bold":true}]},{"type":"list","ordered":true,"start":1$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 17, $study_guide$,"items":[{"text":[{"text":"General:","bold":true},{"text":" all partners share liabilities, profits and assets equally and can manage."}]},{"text":[{"text":"Limited:","bold":true},{"text":" at least one "},{"text":"general partner","bold":true},{"text":" (unlimited liability, manages) plus "},{"text":"limited partners","bold":true},{"text":" (liability limited to their investment, no day-to-day role; they invest and take a profit share)."}]},{"text":[{"text":"Limited liability partnership (LLP):","bold":true},{"text":" works like a general partnership but protects each partner from "},{"text":"malpractice or negligence claims","bold":true},{"text":" arising from other partners; common in professions such as law and accounting."}]}]},{"type":"paragraph","text":[{"text":"Types of partner:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Active:","bold":true},{"text":" manages; unlimited liability."}]},{"text":[{"text":"Sleeping (dormant):","bold":true},{"text":" contributes capital and shares profit, does not manage; still unlimited liability."}]},{"text":[{"text":"Secret:","bold":true},{"text":" connection hidden from outsiders; contributes capital, manages; unlimited liability."}]},{"text":[{"text":"Nominal:","bold":true},{"text":" lends only name and reputation; no capital, no management, no profit share; liable to outsiders who lent believing he was a partner. Two kinds: by "},{"text":"estoppel","bold":true},{"text":" (he says or acts as if he is a partner) and by "},{"text":"holding out","bold":true},{"text":" (he does not deny it when others call him one)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole proprietorship vs partnership:","bold":true},{"text":" both have low start-up costs and unlimited liability, and profits pass through to the owners' personal tax. One owner vs two or more; one keeps all profit vs shared profit; one decides vs shared decisions."}]},{"text":[{"text":"Trap: a "},{"text":"sleeping","bold":true},{"text":" partner is not a "},{"text":"limited","bold":true},{"text":" partner. Only a limited partner's liability stops at his investment. Limited partnerships and LLPs are now recognised in Nigeria under the "},{"text":"Companies and Allied Matters Act (CAMA) 2020","bold":true},{"text":"."}]},{"text":[{"text":"Elements of an agreement: business name and purpose, partners' details, capital contributed, ownership percentage, profit and loss distribution, management and voting, adding or removing partners."}]}]}]},{"number":"5.3","title":"Companies and corporations","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporation (company):","bold":true},{"text":" a business recognised by the state as a "},{"text":"legal entity separate from its owners (shareholders)","bold":true},{"text":". It can own property, sue and be sued in its own name. It is \"an artificial being, invisible, intangible, existing only in contemplation of law\". "},{"text":"Limited liability results from this separate legal existence.","bold":true}]},{"text":[{"text":"Ownership is by shareholders","bold":true},{"text":"; it is transferable by buying and selling shares."}]},{"text":[{"text":"Board of directors:","bold":true},{"text":" elected by shareholders to represent them, set the company's direction and select top executives. "},{"text":"Management","bold":true},{"text":" (CEO and officers) runs day-to-day operations."}]},{"text":[{"text":"In Nigeria a company is registered with the CAC and needs "},{"text":"both a Memorandum and Articles of Association","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memorandum:","bold":true},{"text":" regulates the company's "},{"text":"external","bold":true},{"text":" relationship (name, objects)."}]},{"text":[{"text":"Articles:","bold":true},{"text":" regulate "},{"text":"internal","bold":true},{"text":" relationships between the company and its members."}]}]}]}]},{"type":"paragraph","text":[{"text":"Private vs public limited company","bold":true}]},{"type":"table","header":[[{"text":"Private (Ltd, \"unquoted\")"}],[{"text":"Public (Plc, \"quoted\", joint stock company)"}]],"rows":[[[{"text":"Articles restrict share transfer"}],[{"text":"Public may subscribe; shares freely transferable"}]],[[{"text":"2 to 50 shareholders"}],[{"text":"Minimum 7, no maximum"}]],[[{"text":"Small, limited capital"}],[{"text":"Large capital"}]],[[{"text":"Accounts not published"}],[{"text":"Annual accounts must be published"}]],[[{"text":"Does not issue debentures to the public"}],[{"text":"Issues debentures"}]],[[{"text":"Cannot be quoted on the stock exchange"}],[{"text":"Can be quoted on the stock exchange"}]],[[{"text":"Name ends \"Limited\"/\"Ltd\" (e.g. AGRO Nigeria Limited)"}],[{"text":"Name ends \"Plc\" (e.g. GTBank Plc, Vitafoam Nigeria Plc)"}]]]},{"type":"paragraph","text":[{"text":"Owned by shareholders but "},{"text":"controlled by the board","bold":true},{"text":" (public)."}]},{"type":"paragraph","text":[{"text":"Corporation: advantages (6)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Limited liability protection"}]},{"text":[{"text":"Credibility and trust"}]},{"text":[{"text":"Access to investment (issue shares; easier loans)"}]},{"text":[{"text":"Tax benefits and incentives"}]},{"text":[{"text":"Perpetual life","bold":true},{"text":" (continues across generations of owners)"}]},{"text":[{"text":"Easy ownership transfer"}]}]},{"type":"paragraph","text":[{"text":"Disadvantages (5)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Administrative responsibilities (records, annual returns, company law)"}]},{"text":[{"text":"Set-up and maintenance costs"}]},{"text":[{"text":"Public disclosure requirements"}]},{"text":[{"text":"Additional tax burden, including "},{"text":"double taxation","bold":true},{"text":": profit is taxed as company income, then dividends$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 18, $study_guide$ are taxed again as shareholders' personal income"}]},{"text":[{"text":"Lack of control for shareholders (ownership separated from management)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Managers' power is "},{"text":"not","bold":true},{"text":" complete: shareholders can vote out directors, and the board can remove managers."}]},{"text":[{"text":"Plc means "},{"text":"public limited company","bold":true},{"text":"; \"public liability company\" is a wrong expansion. Nigeria also allows companies limited by "},{"text":"guarantee","bold":true},{"text":" (often non-profits) and "},{"text":"unlimited","bold":true},{"text":" companies. Under CAMA 2020, a "},{"text":"single person","bold":true},{"text":" may now form a private company; for this course, keep 2 to 50 as the private range and a minimum of 7 for a public company."}]},{"text":[{"text":"Limited liability company (LLC)","bold":true},{"text":" in the American sense is a hybrid: members get "},{"text":"limited liability","bold":true},{"text":" plus "},{"text":"flexibility in management and tax treatment","bold":true},{"text":" (taxed like a sole proprietorship, partnership or corporation; pass-through avoids double taxation). Drawbacks: more paperwork than a partnership, differing state rules, harder to attract investors, uncertain continuity when members change. An LLC can have one or many members and is not identical to a corporation. In Nigerian usage \"limited liability company\" usually just means a private limited company."}]},{"text":[{"text":"Other company words: "},{"text":"parent/holding company","bold":true},{"text":" controls a "},{"text":"subsidiary","bold":true},{"text":"; a "},{"text":"mutual company","bold":true},{"text":" is owned by its customers or policyholders (a rare, specialised form)."}]}]}]},{"number":"5.4","title":"Cooperatives, public enterprises and privatisation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cooperative society:","bold":true},{"text":" a voluntary association of persons united by a common bond who venture into business "},{"text":"with the sole purpose of providing service to members in the most efficient and affordable manner","bold":true},{"text":". It is a registered body corporate (owns property, contracts, sues)."}]},{"text":[{"text":"Features:","bold":true},{"text":" owned and democratically run by members · voluntary membership · "},{"text":"one member, one vote","bold":true},{"text":" · profits shared among members or reinvested · separate legal identity."}]},{"text":[{"text":"5 types:","bold":true},{"text":" producer, consumer, credit unions (thrift and credit), marketing, housing."}]}]},{"type":"table","header":[[{"text":"Advantages (7)"}],[{"text":"Disadvantages (6)"}]],"rows":[[[{"text":"Shared benefits"}],[{"text":"Slow, conflict-prone decisions"}]],[[{"text":"Democratic structure"}],[{"text":"Limited capital"}]],[[{"text":"Risk sharing"}],[{"text":"Limited growth"}]],[[{"text":"Stability"}],[{"text":"Inequality in contribution"}]],[[{"text":"Economy in operations (no middlemen)"}],[{"text":"Inefficient management (unpaid, inexperienced)"}]],[[{"text":"Government support (cheap loans, subsidies, lower tax)"}],[{"text":"Excessive government control"}]],[[{"text":"Social utility (stops concentration of economic power)"}],[]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Public enterprise:","bold":true},{"text":" a business "},{"text":"owned (wholly or mainly) and controlled by government","bold":true},{"text":" to provide essential services in the public interest. Also called "},{"text":"government parastatals, public corporations, state-owned enterprises","bold":true},{"text":" and government-owned companies."}]},{"text":[{"text":"Objectives:","bold":true},{"text":" provide essential services (power, water, transport), control strategic sectors, prevent private monopoly exploitation, create jobs, earn revenue, develop neglected areas."}]},{"text":[{"text":"2 sources of finance:","bold":true},{"text":" "},{"text":"internal","bold":true},{"text":" (revenue from operations, retained surplus) and "},{"text":"external","bold":true},{"text":" (government grants and subventions, loans, bonds)."}]},{"text":[{"text":"Privatisation:","bold":true},{"text":" transfer of ownership of a public enterprise, "},{"text":"partly or wholly","bold":true},{"text":", to private investors. It may be "},{"text":"partial or full","bold":true},{"text":"."}]},{"text":[{"text":"Commercialisation:","bold":true},{"text":" government keeps ownership but the enterprise must run on commercial, profit-making lines (also partial or full)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"government sectors\" is "},{"text":"not","bold":true},{"text":" a name for public enterprises."}]},{"text":[{"text":"Nigerian public enterprises have included the Nigerian Ports Authority and the Nigerian Railway Corporation. Problems: political interference, overstaffing, inefficiency, corruption and dependence on subsidies, which led to privatisation."}]},{"text":[{"text":"Nigeria's programme is run by the "},{"text":"Bureau of Public Enterprises (BPE)","bold":true},{"text":" under the "},{"text":"National Council on Privatisation","bold":true},{"text":", guided by the Public Enterprises (Privatisation and Commercialisation) Act 1999. The best-known example is the 2013 sale of the power generation and distribution companies created from PHCN."}]},{"text":[{"text":"For privatisation:","bold":true},{"text":" efficiency, less burden on the budget, revenue for government, new investment, wider share ownership. "},{"text":"Against:","bold":true},{"text":" job losses, higher prices, private monopoly, foreign domination."}]}]}]},{"number":"5.5","title":"Corporate governance","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporate governance:","bold":true},{"text":" the system of rules, practices and pr$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 19, $study_guide$ocesses by which a company is "},{"text":"directed and controlled","bold":true},{"text":", ensuring accountability to stakeholders, transparency and ethical behaviour (oversight and management systems). The "},{"text":"board of directors","bold":true},{"text":" is the primary force in it."}]},{"text":[{"text":"5 principles:","bold":true},{"text":" accountability, transparency, fairness, responsibility, risk management."}]},{"text":[{"text":"4 key actors:","bold":true},{"text":" board of directors, management, shareholders, audit committee (within the board; checks financial reports, compliance and audits)."}]},{"text":[{"text":"Stakeholders considered (7):","bold":true},{"text":" shareholders, management, board, employees, customers, suppliers, community."}]},{"text":[{"text":"6 board responsibilities:","bold":true},{"text":" set corporate strategy · oversee management (appoint, evaluate, remove the CEO) · ensure compliance · risk management · financial reporting (with the audit committee) · succession planning."}]}]},{"type":"paragraph","text":[{"text":"3 governance models","bold":true}]},{"type":"table","header":[[{"text":"Model"}],[{"text":"Who controls"}],[{"text":"Key marks"}]],"rows":[[[{"text":"Anglo-American","bold":true}],[{"text":"Board and shareholders"}],[{"text":"Shareholder Model is principal (others: Stewardship, Political). Management maximises shareholder interest; insiders plus independent directors; chairperson and CEO ideally different people; big decisions put to shareholder vote"}]],[[{"text":"Continental","bold":true}],[{"text":"Two-tier:","bold":true},{"text":" supervisory board (outsiders: shareholders, unions, banks) and management board (insiders)"}],[{"text":"Boards entirely separate; supervisory board size set by national law; companies align with government objectives; values stakeholders"}]],[[{"text":"Japanese","bold":true}],[{"text":"Banks, affiliated entities ("},{"text":"keiretsu","bold":true},{"text":"), management, government"}],[{"text":"Board mostly insiders; keiretsu can remove directors if profits fall; small shareholders have no voice; low transparency"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Benefits of good governance:","bold":true},{"text":" trust, clear direction, long-term viability, investor confidence and capital raising, rising share prices, better reputation and customer retention, less loss, waste, risk and corruption. Bad governance does the opposite and can collapse profitability."}]},{"text":[{"text":"Assessing governance (9 areas):","bold":true},{"text":" disclosure practices, executive pay structure, risk management, conflict-of-interest policies, board members, contractual and social obligations, vendor relationships, complaints, audits."}]},{"text":[{"text":"Institutional investors (pension and mutual funds) are especially influential shareholders. In Nigeria the "},{"text":"Nigerian Code of Corporate Governance 2018","bold":true},{"text":" is issued by the Financial Reporting Council of Nigeria, and the "},{"text":"Securities and Exchange Commission (SEC)","bold":true},{"text":" regulates public companies."}]},{"text":[{"text":"Trap: the board does "},{"text":"not","bold":true},{"text":" run day-to-day operations; management does."}]}]}]},{"number":"5.6","title":"Mergers, acquisitions, strategic alliances and joint ventures","mustKnow":[{"type":"table","header":[[{"text":"Merger"}],[{"text":"Acquisition"}]],"rows":[[[{"text":"Two or more firms "},{"text":"unite into one","bold":true},{"text":" new entity"}],[{"text":"One firm buys part or all of another"}]],[[{"text":"Mutual; usually equals"}],[{"text":"Larger, stronger firm buys a smaller one; need not be mutual"}]],[[{"text":"New shares issued to both sets of shareholders; usually no cash"}],[{"text":"No new shares; buyer needs at least "},{"text":"51%","bold":true},{"text":" for control"}]],[[{"text":"New name and joint management usually"}],[{"text":"Target operates under the buyer's name"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3 types:","bold":true},{"text":" "},{"text":"horizontal","bold":true},{"text":" (competitors at the same stage in the same industry) · "},{"text":"vertical","bold":true},{"text":" (firms at different stages of one supply chain, e.g. a manufacturer and its supplier) · "},{"text":"conglomerate","bold":true},{"text":" (unrelated industries)."}]},{"text":[{"text":"Acquisition forms:","bold":true},{"text":" "},{"text":"stock sale","bold":true},{"text":" (buy the whole entity, assets and liabilities) and "},{"text":"asset sale","bold":true},{"text":" (buy particular assets). Selling a whole segment = "},{"text":"divestiture (carve-out)","bold":true},{"text":"."}]},{"text":[{"text":"3 reasons for acquisition:","bold":true},{"text":" expansion (Apple buying Beats, 2014) · defensive play (Facebook buying WhatsApp, 2014) · capability acquisition (technology or talent)."}]},{"text":[{"text":"Friendly","bold":true},{"text":" acquisition: target's board and shareholders approve. "},{"text":"Hostile takeover:","bold":true},{"text":" one company buys a "},{"text":"controlling interest in the voting stock","bold":true},{"text":" of another "},{"text":"against the wishes of its management","bold":true},{"text":"."}]},{"text":[{"text":"Strategic alliance:","bold":true},{"text":" a cooperative, often "},{"text":"long-term","bold":true},{"text":" agreement between separate businesses to share resources for mutually beneficial projects (production, R&D, marketing, distribution) while "},{"text":"each keeps its independence","bold":true},{"text":". Main advantage: "},{"text":"less risk and work than permanently integrating two companies","bold":true},{"text":"."}]},{"text":[{"text":"4 Cs:","bold":true},{"text":" complementarities, congruence of goals, compatibility of organisations, change."}]},{"text":[{"text":"3 types:","bold":true},{"text":" joint venture, "},{"text":"equity","bold":true},{"text":" alliance $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 20, $study_guide$(one buys an equity stake in the other, e.g. 40%), "},{"text":"non-equity","bold":true},{"text":" alliance (each brings core competencies; "},{"text":"most common","bold":true},{"text":")."}]},{"text":[{"text":"Joint venture (JV):","bold":true},{"text":" two or more parents create a "},{"text":"new, separate child company","bold":true},{"text":" for a specific goal or project. "},{"text":"50-50 JV","bold":true},{"text":" or "},{"text":"majority-owned venture","bold":true},{"text":" (e.g. 70/30). Types: "},{"text":"equity","bold":true},{"text":" and "},{"text":"contractual","bold":true},{"text":". Example: Sony Ericsson."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leveraged buyout:","bold":true},{"text":" buying a company mostly with borrowed money. Not the same as a hostile takeover."}]},{"text":[{"text":"Merger motives: market share, new markets, lower operating costs, more revenue, wider margins. In Nigeria, Access Bank's 2019 merger with Diamond Bank grew its customer base. Oil joint ventures between NNPC and international oil companies are well-known JVs."}]},{"text":[{"text":"Product life cycles and alliances:","bold":true},{"text":" slow cycle (medicine: access restricted markets, keep stability), standard cycle (pool resources, scale, market share), fast cycle (software: speed innovation, share R&D cost)."}]},{"text":[{"text":"How alliances create value (5):","bold":true},{"text":" short-term finances, removing entry barriers, business insight, shared financial risk, innovating beyond current capabilities."}]},{"text":[{"text":"7 steps to a small-business alliance:","bold":true},{"text":" put your house in order, set goals, identify partners, due diligence, get to know each other, make it win-win, keep clear communication."}]},{"text":[{"text":"Alliance advantages:","bold":true},{"text":" shared resources and expertise, innovation, competitive advantage, new-market penetration, economies of scale, revenue growth, risk mitigation, brand awareness. "},{"text":"Cons:","bold":true},{"text":" more coordination work, one side may gain more, conflict over strategy, possible damage to image."}]},{"text":[{"text":"JV steps (7):","bold":true},{"text":" purpose and goals → structure and ownership → resources → governance (board, management) → finances and profit sharing → risks and exit → monitoring. "},{"text":"Benefits:","bold":true},{"text":" new markets, shared costs and risks, combined expertise. "},{"text":"Challenges:","bold":true},{"text":" conflict of interest, cultural difference, shared control."}]},{"text":[{"text":"Traps: alliance = cooperative pact, "},{"text":"not","bold":true},{"text":" a permanent consolidation; JV = a new entity for a defined purpose, often limited in time; merger = one entity; acquisition = controlling interest."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Sole proprietorship: one owner, full control, independence, unlimited liability, most common, cannot sell shares."}]},{"text":[{"text":"Partnership: 2+ owners, shared profits, joint authority, unlimited liability (general); general, limited, LLP; active, sleeping, secret, nominal partners."}]},{"text":[{"text":"Company: separate legal entity, shareholders, limited liability, perpetual life, double taxation; memorandum (external) and articles (internal)."}]},{"text":[{"text":"Private Ltd 2-50, no public shares; Plc 7+, quoted, publishes accounts."}]},{"text":[{"text":"Cooperative: serves members, one member one vote; 5 types."}]},{"text":[{"text":"Public enterprises (parastatals, public corporations, SOEs) finance internally and externally; privatisation is partial or full."}]},{"text":[{"text":"Governance: 5 principles, 4 actors, 6 board duties; Anglo-American, Continental (two-tier), Japanese (keiretsu)."}]},{"text":[{"text":"M&A: horizontal, vertical, conglomerate; hostile takeover against management's wishes; alliance keeps independence; JV creates a new child company."}]}]}],"theory":{"itemId":"e59886c4-52f7-5e2c-8f64-a9ea1e460c27","question":[{"type":"paragraph","text":[{"text":"Distinguish between a private limited company and a public limited company, and state two advantages and two disadvantages of the corporate form."}]}]},"practice":[{"topic":"Forms of Business Ownership","named":false}]}},{"kind":"note","itemId":"38dd1187-cac0-5a05-9c01-4614cec71a8c","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Entrepreneurship and Small-Business Ownership","body":"What a small business is and why it matters to the economy; who entrepreneurs are and the entrepreneurial spirit; the start-up phase (three routes to ownership, the business plan); the growth phase and why small businesses fail; financing options (debt and equity, bank loans, microfinance, angel investors, venture capital, crowdfunding, bootstrapping); the franchise alternative (franchisor, franchisee, advantages and disadvantages).","noteType":"guide_topic","number":6,"mustKnow":[{"text":"What a small business is and why it matters to the economy; who entrepreneurs are and the entrepreneurial spirit; the start-up phase (three routes to ownership, the business plan); the growth phase and why small businesses fail; financing options (debt and equity, bank loans, microfinance, angel investors, venture capital, crowdfunding, bootstrapping); the franchise alternative (franchisor, franchisee, advantages and disadvantages)."}],"lessons":[{"number":"6.1","title":"The big world of small business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Small business:","bold":true},{"text":" a firm that is "},{"text":"independently owned and operated","bold":true},{"text":", is "},{"text":"not dominant in its field","bold":true},{"text":" (market), and is small by number of employees or annual sales. In the United States the usual cut-off is "},{"text":"fewer than 500 employees","bold":true},{"text":"."}]},{"text":[{"text":"Nigeria (MSMEs):","bold":true},{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 21, $study_guide$:" micro, small and medium enterprises are grouped by size. By employees: "},{"text":"micro","bold":true},{"text":" under 10, "},{"text":"small","bold":true},{"text":" 10 to 49, "},{"text":"medium","bold":true},{"text":" 50 to 199. The government agency that promotes and supports them is "},{"text":"SMEDAN","bold":true},{"text":" (Small and Medium Enterprises Development Agency of Nigeria)."}]}]},{"type":"paragraph","text":[{"text":"Typical characteristics of a small business:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Small employee count","bold":true},{"text":" (the feature most often examined)."}]},{"text":[{"text":"Owned and usually "},{"text":"managed by the owner","bold":true},{"text":" (owner-manager business)."}]},{"text":[{"text":"Limited capital","bold":true},{"text":" and resources."}]},{"text":[{"text":"Narrow focus","bold":true},{"text":": few products, often one location or a local market."}]},{"text":[{"text":"Close, personal contact","bold":true},{"text":" with customers and staff; quick, flexible decisions."}]}]},{"type":"paragraph","text":[{"text":"Role (importance) of small businesses in the economy:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Create jobs","bold":true},{"text":": together they employ a very large share of workers."}]},{"text":[{"text":"Drive innovation","bold":true},{"text":": introduce new products, services and ideas."}]},{"text":[{"text":"Give an outlet for entrepreneurs","bold":true},{"text":": a route for people to turn ideas into businesses."}]},{"text":[{"text":"Provide specialist support to larger companies","bold":true},{"text":": as suppliers, distributors and service providers."}]},{"text":[{"text":"Meet specialised needs of consumers","bold":true},{"text":" that big firms ignore."}]},{"text":[{"text":"Inject competition","bold":true},{"text":", which keeps prices and quality in check."}]},{"text":[{"text":"Support local economies","bold":true},{"text":" and spread income and opportunity."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"When a question asks why small businesses are important and offers several true reasons plus \"all the above\", the answer is "},{"text":"all the above","bold":true},{"text":": outlet for entrepreneurs, specialist support to big firms and innovation are all correct."}]},{"text":[{"text":"Trap:","bold":true},{"text":" small businesses do "},{"text":"not","bold":true},{"text":" cut employment, raise tax burdens or curb competition. They "},{"text":"foster jobs and innovation","bold":true},{"text":". \"Massive scale\", \"worldwide reach\" and \"heavy capital needs\" describe large corporations, not small businesses."}]},{"text":[{"text":"Lifestyle business vs high-growth venture:","bold":true},{"text":" a lifestyle business aims to give its owner a comfortable living and independence (a provision shop, a hair salon, a campus printing stand). A high-growth venture aims to grow quickly into a large firm (many tech start-ups in Yaba, Lagos)."}]},{"text":[{"text":"Most businesses in Nigeria are micro and small enterprises, many of them informal: market traders, tailors, mechanics, food sellers."}]}]}]},{"number":"6.2","title":"The entrepreneurial spirit","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Entrepreneur:","bold":true},{"text":" a person who "},{"text":"spots a business opportunity","bold":true},{"text":" and "},{"text":"assumes the risk","bold":true},{"text":" of starting and running a new business, in the hope of profit."}]},{"text":[{"text":"Entrepreneurship:","bold":true},{"text":" the "},{"text":"process of designing, creating and running a new business","bold":true},{"text":", accepting the risks involved."}]},{"text":[{"text":"Entrepreneurial spirit:","bold":true},{"text":" the positive, forward-thinking desire to create profitable, innovative business solutions. It involves "},{"text":"creativity, problem-solving and embracing risk","bold":true},{"text":"."}]},{"text":[{"text":"Intrapreneurship:","bold":true},{"text":" showing entrepreneurial behaviour (innovating, taking initiative) "},{"text":"inside an existing organisation","bold":true},{"text":" as an employee."}]}]},{"type":"paragraph","text":[{"text":"What entrepreneurship involves:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Spotting a business opportunity."}]},{"text":[{"text":"Developing an idea for a business."}]},{"text":[{"text":"Satisfying the needs of customers."}]},{"text":[{"text":"Taking (calculated) risks and organising resources."}]}]},{"type":"paragraph","text":[{"text":"Common traits of entrepreneurs:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Risk-taking","bold":true},{"text":" (willing to accept calculated risk)."}]},{"text":[{"text":"Creativity and innovation","bold":true},{"text":"."}]},{"text":[{"text":"Problem-solving","bold":true},{"text":" ability."}]},{"text":[{"text":"Self-confidence","bold":true},{"text":" and a desire to control their own destiny (independence)."}]},{"text":[{"text":"Drive, discipline and hard work","bold":true},{"text":"."}]},{"text":[{"text":"Optimism and persistence","bold":true},{"text":"; tolerance of failure and uncertainty."}]},{"text":[{"text":"Eagerness to learn","bold":true},{"text":" and ability to relate well to people."}]}]},{"type":"paragraph","text":[{"text":"Why people start businesses:","bold":true},{"text":" independence (being your own boss), financial rewards, personal satisfaction and achievement, passion for an idea, and lack of (or dissatisfaction with) paid employment."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Who is who:","bold":true},{"text":" an "},{"text":"investor","bold":true},{"text":" only supplies money; a "},{"text":"manager","bold":true},{"text":" runs a business that may belong to someone else; a "},{"text":"stakeholder"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 22, $study_guide$,"bold":true},{"text":" is anyone affected by the business. The person who "},{"text":"assumes the risk of starting","bold":true},{"text":" the business is the "},{"text":"entrepreneur","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"managing large businesses\" or \"managing a corporation\" is "},{"text":"management","bold":true},{"text":", not entrepreneurship. Entrepreneurship is about "},{"text":"creating new","bold":true},{"text":" businesses."}]},{"text":[{"text":"Trap:","bold":true},{"text":" "},{"text":"applying for a job","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" associated with entrepreneurship, because it means working for someone else."}]},{"text":[{"text":"Entrepreneurs are "},{"text":"not","bold":true},{"text":" risk-averse and do "},{"text":"not","bold":true},{"text":" stick to old ways or ignore market cues. Those are the opposite of the entrepreneurial spirit."}]},{"text":[{"text":"Challenges entrepreneurs face:","bold":true},{"text":" "},{"text":"navigating risks and unknowns","bold":true},{"text":" (uncertainty), limited funds, competition, long hours and heavy personal responsibility. They do not enjoy \"unlimited funding\" or \"zero competition\"."}]},{"text":[{"text":"Nigerian examples: Aliko Dangote built the Dangote Group from a trading business; many young founders build fintech firms in Lagos."}]}]}]},{"number":"6.3","title":"The start-up phase: planning and launching","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Start-up phase","bold":true},{"text":" (also called the "},{"text":"initiation stage","bold":true},{"text":"): getting the business off the ground. It includes "},{"text":"idea generation, writing the business plan, raising funds (for example loans and investors) and launching","bold":true},{"text":"."}]},{"text":[{"text":"3 routes to small-business ownership:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Start a new business from scratch","bold":true},{"text":" (a start-up)."}]},{"text":[{"text":"Buy an existing business","bold":true},{"text":"."}]},{"text":[{"text":"Buy a franchise","bold":true},{"text":"."}]}]}]}]},{"type":"table","header":[[{"text":"Route"}],[{"text":"Main advantage"}],[{"text":"Main disadvantage"}]],"rows":[[[{"text":"Start from scratch"}],[{"text":"Full freedom to shape the business"}],[{"text":"High failure rate","bold":true},{"text":"; no customers or track record"}]],[[{"text":"Buy an existing business"}],[{"text":"Customers, suppliers, staff and a track record already exist"}],[{"text":"Higher purchase cost; you may inherit hidden problems"}]],[[{"text":"Buy a franchise"}],[{"text":"Known brand and proven system; support"}],[{"text":"Fees and royalties; loss of independence"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Business plan:","bold":true},{"text":" a written document that sets out the business idea, its goals, the strategy for reaching them, and the resources (especially money) needed. It is prepared in the "},{"text":"initiation (start-up) stage","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Why a business plan is significant:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Persuades others","bold":true},{"text":" (lenders, investors) "},{"text":"to commit funding","bold":true},{"text":"."}]},{"text":[{"text":"Demonstrates the viability","bold":true},{"text":" of the venture (that it can succeed)."}]},{"text":[{"text":"Guides business activities by defining objectives","bold":true},{"text":"."}]},{"text":[{"text":"Forces the founder to think through every part of the business and spot problems early."}]}]},{"type":"paragraph","text":[{"text":"Typical contents of a business plan:","bold":true},{"text":" executive summary; mission and objectives; company overview; management team; target market and market analysis; competition and competitive advantage; marketing strategy; operations plan; financial plan (start-up costs, projected sales, cash flow, funding needed); critical risks."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"When \"all the above\" follows persuading funders, showing viability and guiding activities, choose "},{"text":"all the above","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the "},{"text":"high failure rate","bold":true},{"text":" is the recognised disadvantage of a start-up compared with buying a business or a franchise. A start-up does not usually need "},{"text":"more","bold":true},{"text":" funds than other routes; buying an established business or franchise often costs more."}]},{"text":[{"text":"Trap:","bold":true},{"text":" global expansion and maintaining growth belong to the "},{"text":"growth","bold":true},{"text":" stage; shutting down belongs to closure. A business plan is not written in the expansion, stability or downturn stage."}]},{"text":[{"text":"Before launch, the founder also chooses a form of ownership and registers it, in Nigeria with the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":"."}]}]}]},{"number":"6.4","title":"The growth phase and why small businesses fail","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Growth phase:","bold":true},{"text":" "},{"text":"nurturing and sustaining a young business","bold":true},{"text":", that is "},{"text":"building and sustaining progress","bold":true},{"text":". It focuses on "},{"text":"scaling operations, managing cash flow and building a customer base","bold":true},{"text":"."}]},{"text":[{"text":"Stages of a business (life cycle):","bold":true},{"text":" initiation (start-up) → growth (expansion) → maturity (stability) → possible decline (downturn)."}]}]},{"type":"paragraph","text":[{"text":"Tasks in the growth phase:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Scale up operations to meet ris$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 23, $study_guide$ing demand."}]},{"text":[{"text":"Manage cash flow carefully."}]},{"text":[{"text":"Build and keep a customer base."}]},{"text":[{"text":"Hire staff and "},{"text":"delegate","bold":true},{"text":": the owner can no longer do everything."}]},{"text":[{"text":"Seek advice and further finance."}]}]},{"type":"paragraph","text":[{"text":"Why small businesses fail:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Management incompetence or inexperience","bold":true},{"text":"."}]},{"text":[{"text":"Inadequate financing","bold":true},{"text":" (undercapitalisation) and "},{"text":"poor cash-flow management","bold":true},{"text":"."}]},{"text":[{"text":"Poor planning","bold":true},{"text":", including no proper business plan."}]},{"text":[{"text":"Weak marketing","bold":true},{"text":" or not enough customers (poor market research)."}]},{"text":[{"text":"Uncontrolled (too rapid) growth","bold":true},{"text":"."}]},{"text":[{"text":"Poor location","bold":true},{"text":", poor stock (inventory) control, failure to adapt to change."}]}]},{"type":"paragraph","text":[{"text":"Sources of help and advice:","bold":true},{"text":" mentors, advisory boards, networking, business incubators (which give new firms low-cost space and support services) and government agencies such as "},{"text":"SMEDAN","bold":true},{"text":" in Nigeria."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the growth phase is not about terminating, shrinking or dodging competitors. It is about building on early success."}]},{"text":[{"text":"A business can fail "},{"text":"while growing","bold":true},{"text":": fast sales growth can use up cash faster than it comes in, so cash-flow management is vital."}]},{"text":[{"text":"Many owners struggle to move from doing every job themselves to managing others. Learning to delegate is a key growth-phase skill."}]}]}]},{"number":"6.5","title":"Financing options for small businesses","mustKnow":[{"type":"table","header":[[],[{"text":"Debt financing","bold":true}],[{"text":"Equity financing","bold":true}]],"rows":[[[{"text":"Meaning"}],[{"text":"Borrowing money"}],[{"text":"Selling part-ownership (shares) in the business"}]],[[{"text":"Repayment"}],[{"text":"Must be repaid "},{"text":"with interest","bold":true}],[{"text":"No repayment"}]],[[{"text":"Control"}],[{"text":"Owner keeps ownership"}],[{"text":"Investors gain ownership and a share of profit, often a say"}]],[[{"text":"Examples"}],[{"text":"Bank loans, microfinance loans, supplier credit"}],[{"text":"Angel investors, venture capital, partners"}]]]},{"type":"paragraph","text":[{"text":"Main financing options:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Personal savings","bold":true},{"text":" and "},{"text":"family and friends","bold":true},{"text":": the most common first source."}]},{"text":[{"text":"Bootstrapping","bold":true},{"text":": funding the business from the owner's own resources and its own revenue, keeping costs low."}]},{"text":[{"text":"Commercial bank loans","bold":true},{"text":": a common source; banks usually want a business plan and collateral."}]},{"text":[{"text":"Microfinance","bold":true},{"text":": small loans to micro and small businesses that banks often turn down. In Nigeria "},{"text":"microfinance banks","bold":true},{"text":" are licensed and regulated by the "},{"text":"Central Bank of Nigeria (CBN)","bold":true},{"text":". The "},{"text":"Bank of Industry (BOI)","bold":true},{"text":" is a government development bank that also funds small businesses."}]},{"text":[{"text":"Angel investors","bold":true},{"text":": wealthy individuals who invest their "},{"text":"own money","bold":true},{"text":" in early-stage businesses in exchange for equity."}]},{"text":[{"text":"Venture capital","bold":true},{"text":": funding from firms (venture capitalists) that invest pooled money in "},{"text":"high-technology, high-risk, perceived high-reward","bold":true},{"text":" businesses in exchange for equity, expecting large returns."}]},{"text":[{"text":"Crowdfunding","bold":true},{"text":": raising small amounts from "},{"text":"many people","bold":true},{"text":", usually online."}]},{"text":[{"text":"Seed capital","bold":true},{"text":": the first small sum used to test an idea and set up the business."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Venture capital vs angel investors:","bold":true},{"text":" angels are "},{"text":"individuals","bold":true},{"text":" using their own money, usually earlier and in smaller sums. Venture capitalists are "},{"text":"firms","bold":true},{"text":", usually investing larger sums at a later stage, and they expect to exit by selling their stake (for example when the company lists on a stock exchange or is bought)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" fixed capital and current (working) capital describe "},{"text":"how","bold":true},{"text":" funds are used (long-term assets vs day-to-day running), not a source of funds. Seed capital is the first funding, not the high-risk, high-tech finance; that is "},{"text":"venture capital","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" tax revenue is government income, staff wages are money owed to workers, and client opinions are feedback. None is a financing option for a small business. "},{"text":"Commercial bank loans","bold":true},{"text":" are."}]},{"text":[{"text":"Informal sources are also common in Nigeria, such as rotating savings groups (esusu or ajo) and trade credit from suppliers."}]}]}]},{"number":"6.6","title":"The franchise alternative","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Franchise:","bold":true},{"text":" a business arrangement in which one party (the "},{"text":"franchisor","bold":true},{"text":") allows another (the "},{"text":"franchisee","bold":true},{"text":") to "},{"text":"u$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 24, $study_guide$se its business name, brand and system to sell its products or services","bold":true},{"text":", in return for fees. In short, "},{"text":"a licensed brand operation","bold":true},{"text":"."}]},{"text":[{"text":"Franchisor:","bold":true},{"text":" the company that owns the brand and system and grants the right."}]},{"text":[{"text":"Franchisee:","bold":true},{"text":" the person or firm that buys the right and runs the outlet."}]},{"text":[{"text":"Franchise agreement:","bold":true},{"text":" the contract setting out rights, duties, fees and rules. The franchisee usually pays an "},{"text":"initial franchise fee","bold":true},{"text":" plus continuing "},{"text":"royalties","bold":true},{"text":" (a share of sales)."}]},{"text":[{"text":"2 types:","bold":true},{"text":" (1) "},{"text":"product (trade-name) franchise","bold":true},{"text":": the right to sell the franchisor's products, e.g. car dealerships and soft-drink bottlers; (2) "},{"text":"business-format franchise","bold":true},{"text":": the whole way of running the business (name, layout, methods, training), e.g. fast-food chains."}]}]},{"type":"table","header":[[{"text":"Advantages to the franchisee"}],[{"text":"Disadvantages to the franchisee"}]],"rows":[[[{"text":"Pre-existing brand fame","bold":true},{"text":" (known name attracts customers)"}],[{"text":"High start-up cost","bold":true},{"text":" (franchise fee, equipment)"}]],[[{"text":"Proven business system; "},{"text":"lower risk of failure","bold":true}],[{"text":"Continuing "},{"text":"royalties","bold":true},{"text":" reduce profit"}]],[[{"text":"Training and support","bold":true},{"text":" from the franchisor"}],[{"text":"Loss of independence","bold":true},{"text":": strict rules on products, prices, layout"}]],[[{"text":"National advertising and group buying power"}],[{"text":"Franchisor's problems or bad publicity hurt every outlet"}]],[[{"text":"Easier to obtain finance"}],[{"text":"Agreement may limit selling the outlet and can be ended"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Advantages to the franchisor:","bold":true},{"text":" rapid expansion using franchisees' money, steady fee and royalty income, motivated owner-managers at each outlet."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" high risk, minimal franchisor support and steep initial investment are "},{"text":"not","bold":true},{"text":" advantages. The headline advantage is "},{"text":"pre-existing brand fame","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a franchise is not a state-owned operation (that is a public enterprise), a merger, a cooperative (owned by its members) or a solo-owner venture (sole proprietorship)."}]},{"text":[{"text":"Franchising is also a way to enter foreign markets (Topic 3). In Nigeria, the Nigerian Bottling Company bottles Coca-Cola products, an example of a product franchise, and international fast-food brands operate here through franchise arrangements."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Small business = independently owned, not dominant in its field, small employee count; Nigeria groups MSMEs by size and supports them through SMEDAN."}]},{"text":[{"text":"Small businesses create jobs, drive innovation, give entrepreneurs an outlet and support large firms."}]},{"text":[{"text":"Entrepreneur = assumes the risk of starting a business; entrepreneurship = designing and creating new businesses."}]},{"text":[{"text":"Entrepreneurial spirit = creativity, problem-solving and embracing risk; applying for a job is not entrepreneurship."}]},{"text":[{"text":"3 routes: start from scratch (high failure rate), buy an existing business, buy a franchise."}]},{"text":[{"text":"Business plan, written at the initiation stage: persuades funders, shows viability, guides by objectives."}]},{"text":[{"text":"Growth phase = building and sustaining progress: scaling, cash flow, customers."}]},{"text":[{"text":"Failure causes: poor management, too little finance, poor planning, weak marketing, uncontrolled growth."}]},{"text":[{"text":"Debt is repaid with interest; equity sells ownership. Venture capital funds high-tech, high-risk, high-reward projects."}]},{"text":[{"text":"Franchise = licensed brand operation; key advantage is brand fame, key drawbacks are fees, royalties and lost independence."}]}]}],"theory":{"itemId":"9957e3ea-8b1f-5d53-a98f-e88cdf2ae4ca","question":[{"type":"paragraph","text":[{"text":"Explain the franchise alternative and state three advantages and three disadvantages of franchising to the franchisee."}]}]},"practice":[{"topic":"Entrepreneurship and Small-Business Ownership","named":false}]}},{"kind":"note","itemId":"cb2abec1-e0e3-57e8-ae9f-1194b000e5fd","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Management Roles, Functions and Skills","body":"What management is and the manager's main job; the three groups of managerial roles; the three levels of management; the four functions (planning with vision, mission, goals, objectives and SWOT; organising with structure and teams; leading with leadership styles; controlling); and the four essential skills (technical, interpersonal, conceptual, decision-making).","noteType":"guide_topic","number":7,"mustKnow":[{"text":"What management is and the manager's main job; the three groups of managerial roles; the three levels of management; the four functions (planning with vision, mission, goals, objectives and SWOT; organising with structure and teams; leading with leadership styles; controlling); and the four essential skills (technical, interpersonal, conceptual, decision-making)."}],"lessons":[{"number":"7.1","title":"What managers do: roles and levels","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Management:","bold":true},{"text":" the process of planning, organising, leading and controlling an organisation's resources (people, money, mat$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 25, $study_guide$erials, information) to reach its goals effectively and efficiently."}]},{"text":[{"text":"Primary role of a manager:","bold":true},{"text":" to "},{"text":"drive organisational objectives","bold":true},{"text":", that is, to get the organisation's goals achieved through the work of others. It is not doing routine technical work, chasing promotion or avoiding choices."}]},{"text":[{"text":"Efficiency","bold":true},{"text":" = doing things right (least waste of resources). "},{"text":"Effectiveness","bold":true},{"text":" = doing the right things (reaching the goal)."}]}]},{"type":"paragraph","text":[{"text":"The three groups of managerial roles (10 roles in all):","bold":true}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Meaning"}],[{"text":"Roles inside it"}]],"rows":[[[{"text":"Interpersonal","bold":true},{"text":" (relationship-building)"}],[{"text":"dealing with people inside and outside the firm"}],[{"text":"figurehead, "},{"text":"leader","bold":true},{"text":", liaison"}]],[[{"text":"Informational","bold":true},{"text":" (information-sharing)"}],[{"text":"receiving, gathering and passing on information"}],[{"text":"monitor, disseminator, "},{"text":"spokesperson","bold":true}]],[[{"text":"Decisional","bold":true},{"text":" (decision-making)"}],[{"text":"making choices and solving problems"}],[{"text":"entrepreneur, "},{"text":"disturbance handler","bold":true},{"text":", resource allocator, negotiator"}]]]},{"type":"paragraph","text":[{"text":"The three levels of management (the management pyramid):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Top managers:","bold":true},{"text":" the highest level (CEO, managing director, chief financial officer). Set long-term direction and strategic plans, and represent the firm to outsiders."}]},{"text":[{"text":"Middle managers:","bold":true},{"text":" heads of departments, divisions or plants. Turn top management's strategy into departmental plans and link top and first-line managers."}]},{"text":[{"text":"First-line (supervisory) managers:","bold":true},{"text":" supervisors, team leaders, shift managers. Oversee the people who do the work and handle day-to-day operations."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Interpersonal:","bold":true},{"text":" the "},{"text":"figurehead","bold":true},{"text":" performs ceremonial duties (cutting the tape at a new branch); the "},{"text":"leader","bold":true},{"text":" guides and motivates staff; the "},{"text":"liaison","bold":true},{"text":" builds networks with people outside his unit."}]},{"text":[{"text":"Informational:","bold":true},{"text":" the "},{"text":"monitor","bold":true},{"text":" scans for information (reading business news, market reports); the "},{"text":"disseminator","bold":true},{"text":" passes information to staff; the "},{"text":"spokesperson","bold":true},{"text":" speaks for the organisation to outsiders such as the press, regulators or investors. When MTN Nigeria's CEO addresses journalists about a policy, he is a spokesperson, an "},{"text":"informational","bold":true},{"text":" role."}]},{"text":[{"text":"Decisional:","bold":true},{"text":" the "},{"text":"entrepreneur","bold":true},{"text":" starts improvements and new projects; the "},{"text":"disturbance handler","bold":true},{"text":" resolves conflicts and crises, acting as a "},{"text":"mediator","bold":true},{"text":"; the "},{"text":"resource allocator","bold":true},{"text":" decides who gets money, people and time; the "},{"text":"negotiator","bold":true},{"text":" bargains with unions, suppliers or partners."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"spokesperson\" sounds like talking to people, so students pick interpersonal. It is "},{"text":"informational","bold":true},{"text":". Resolving a conflict is decisional (disturbance handler), not interpersonal. \"Skill-based role\" or \"technical role\" is not one of the groups."}]},{"text":[{"text":"All managers perform all roles, but the mix changes with level: top managers spend more time as figurehead, spokesperson and negotiator; the leader role matters most for first-line managers on the shop floor."}]}]}]},{"number":"7.2","title":"The planning function","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Planning:","bold":true},{"text":" the function of "},{"text":"defining objectives (goals) and the strategies and tactics","bold":true},{"text":" to reach them. It is the first function; the others depend on it."}]},{"text":[{"text":"Vision statement:","bold":true},{"text":" a brief, inspiring statement of what the organisation wants to become in the future."}]},{"text":[{"text":"Mission statement:","bold":true},{"text":" a statement of the organisation's purpose: what it does, whom it serves and its basic values."}]},{"text":[{"text":"Goal:","bold":true},{"text":" a broad, long-range target. "},{"text":"Objective:","bold":true},{"text":" a specific, measurable, shorter-range target that helps reach a goal."}]},{"text":[{"text":"SWOT analysis:","bold":true},{"text":" "},{"text":"Strengths, Weaknesses, Opportunities and Threats","bold":true},{"text":". Strengths and weaknesses are "},{"text":"internal","bold":true},{"text":"; opportunities and threats are "},{"text":"external","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Types of plans:","bold":true}]},{"type":"table","header":[[{"text":"Plan"}],[{"text":"Made by"}],[{"text":"Time frame"}],[{"text":"Example"}]],"rows":[[[{"text":"Strategic","bold":true}],[{"text":"top managers"}],[{"text":"long term (several years)"}],[{"text":"enter West African markets under ECOWAS"}]],[[{"text":"Tactical","bold":true}],[{"text":"middle managers"}],[{"text":"medium term"}],[{"text":"a region's sales plan for the year"}]],[[{"text":"Operational","bold":true}],[{"text":"first-line managers"}],[{"text":"short term (days, weeks, months)"}],[{"text":"this week's production schedule"}]]]}],"ex$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 26, $study_guide$plainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Strategic planning steps:","bold":true},{"text":" (1) define the mission, vision and values; (2) assess the organisation's strengths, weaknesses, opportunities and threats (SWOT); (3) develop forecasts; (4) analyse the competition; (5) establish goals and objectives; (6) develop action plans (strategies and tactics) to reach them."}]},{"text":[{"text":"SWOT example (a Nigerian cement maker):","bold":true},{"text":" strength = large plant and strong brand; weakness = high diesel and power costs; opportunity = growing housing demand; threat = cheap imports or a sharp fall in the naira. Internal factors are within the firm's control; external ones are not."}]},{"text":[{"text":"Good objectives are "},{"text":"SMART","bold":true},{"text":": Specific, Measurable, Achievable, Relevant, Time-bound. \"Increase sales\" is a goal; \"increase sales in Lagos by 10% by December\" is an objective."}]},{"text":[{"text":"Crisis management (contingency planning):","bold":true},{"text":" planning ahead for emergencies such as fire, product recalls or system failure, so the firm can respond quickly and protect people and its reputation."}]},{"text":[{"text":"Trap:","bold":true},{"text":" budget goal-setting and fiscal forecasting are "},{"text":"planning","bold":true},{"text":", not organising or controlling. Tracking staff output is "},{"text":"controlling","bold":true},{"text":"; recruiting is "},{"text":"staffing/HR","bold":true},{"text":"; mediating disputes is "},{"text":"leading","bold":true},{"text":"."}]}]}]},{"number":"7.3","title":"The organising function: structure and teams","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Organising:","bold":true},{"text":" arranging resources, "},{"text":"assigning tasks, duties and roles","bold":true},{"text":", grouping people into departments and "},{"text":"delegating","bold":true},{"text":" authority so that plans can be carried out."}]},{"text":[{"text":"Organisation structure:","bold":true},{"text":" the framework that defines roles, "},{"text":"who does what and who reports to whom","bold":true},{"text":". An effective structure gives "},{"text":"clearly defined duties and roles","bold":true},{"text":", smooth communication and good output."}]},{"text":[{"text":"Chain of command:","bold":true},{"text":" the line of authority from the top to the bottom. "},{"text":"Span of control:","bold":true},{"text":" the number of people who report directly to one manager. "},{"text":"Delegation:","bold":true},{"text":" giving a subordinate authority and responsibility for a task."}]}]},{"type":"table","header":[[{"text":"Tall (hierarchical) structure"}],[{"text":"Flat structure"}]],"rows":[[[{"text":"many layers (tiers) of management"}],[{"text":"few (minimal)","bold":true},{"text":" layers of management"}]],[[{"text":"narrow span of control"}],[{"text":"wide span of control"}]],[[{"text":"slower decisions and communication"}],[{"text":"faster decisions, more staff freedom"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Other structures: "},{"text":"functional","bold":true},{"text":" (departments by function: marketing, finance, HR), "},{"text":"divisional","bold":true},{"text":" (by product or region), "},{"text":"matrix","bold":true},{"text":" (staff report to both a functional manager and a project manager)."}]},{"text":[{"text":"Unstructured (flexible) organisation:","bold":true},{"text":" few formal rules, loose roles, "},{"text":"adaptability and fluidity","bold":true},{"text":"; common in tech start-ups. Managing it requires "},{"text":"flexibility and ingenuity (creativity)","bold":true},{"text":", not tight oversight."}]},{"text":[{"text":"Team:","bold":true},{"text":" a group of people working together toward a "},{"text":"common goal","bold":true},{"text":", sharing responsibility for the result."}]}]},{"type":"paragraph","text":[{"text":"Benefits of organising in teams:","bold":true},{"text":" higher output (enhanced productivity) · quicker problem-solving · more ideas and creativity · better coordination · greater commitment and morale."}]},{"type":"paragraph","text":[{"text":"What makes teams productive (4):","bold":true},{"text":" clear (precise) goals · the tools and resources needed · open and clear communication · trust and unity among members."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Types of teams:","bold":true},{"text":" "},{"text":"functional","bold":true},{"text":" (people from one department), "},{"text":"cross-functional","bold":true},{"text":" (people from different departments, such as product launch teams), "},{"text":"problem-solving","bold":true},{"text":" (formed to fix a specific issue), "},{"text":"self-managed","bold":true},{"text":" (manage themselves with little supervision), "},{"text":"virtual","bold":true},{"text":" (members in different locations linked by technology, e.g. on Zoom or WhatsApp)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a flat structure still has authority levels; it simply has fewer of them. \"No authority levels\" is wrong."}]},{"text":[{"text":"Trap:","bold":true},{"text":" fixed chain of command and rigid rules describe a "},{"text":"highly structured","bold":true},{"text":" firm, not an unstructured one."}]},{"text":[{"text":"Team problems such as distrust, unclear targets, persistent disputes, slow decisions and stifled ideas are the result of "},{"text":"poorly managed","bold":true},{"text":" teams, never benefits. To foster teamwork, a manager builds trust, keeps everyone focused on shared objectives and invites every member's input; setting members against each other destroys it."}]}]}]},{"number":"7.4","title":"The leading function","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leading:","bold":true},{"text":" guiding, "},{"text":"motivating and inspiring","bold":true},{"text":" people (raising team morale) so they work wil$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 27, $study_guide$lingly toward the organisation's goals. It includes communicating, directing, coaching and resolving conflicts."}]},{"text":[{"text":"Leadership:","bold":true},{"text":" the ability to influence others to achieve goals. Managers plan and control; leaders inspire and set direction. Good managers do both."}]}]},{"type":"paragraph","text":[{"text":"Leadership styles:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Autocratic:","bold":true},{"text":" the leader makes decisions alone and expects obedience. Fast; useful in emergencies; can lower morale."}]},{"text":[{"text":"Democratic (participative):","bold":true},{"text":" the leader involves staff in decisions; final decision often by the leader or the group. Builds commitment; slower."}]},{"text":[{"text":"Laissez-faire (free-rein):","bold":true},{"text":" the leader gives broad goals and leaves employees to decide how to work. Suits skilled, self-motivated staff."}]},{"text":[{"text":"Situational (contingency) leadership:","bold":true},{"text":" no single best style; the leader adapts to the people, the task and the situation."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Coaching","bold":true},{"text":" is helping employees build skills and confidence through guidance and feedback. "},{"text":"Mentoring","bold":true},{"text":" is an experienced manager or employee guiding a less experienced colleague's career."}]},{"text":[{"text":"Leaders also "},{"text":"manage change","bold":true},{"text":" (helping staff accept new systems) and build "},{"text":"organisational culture","bold":true},{"text":": the shared values, beliefs and norms of the firm."}]},{"text":[{"text":"An autocratic style may suit a factory fire drill; a laissez-faire style suits a team of experienced software engineers."}]},{"text":[{"text":"Trap:","bold":true},{"text":" output oversight is controlling, not leading; fiscal forecasting is planning; product development is an operational activity, not a management function."}]}]}]},{"number":"7.5","title":"The controlling function","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Controlling:","bold":true},{"text":" "},{"text":"monitoring performance, comparing it with targets and taking corrective action","bold":true},{"text":" so that goals are met. It is the last function and feeds back into planning."}]}]},{"type":"paragraph","text":[{"text":"The control cycle (4 steps):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set standards","bold":true},{"text":" (targets drawn from the plan's objectives)."}]},{"text":[{"text":"Measure","bold":true},{"text":" actual performance."}]},{"text":[{"text":"Compare","bold":true},{"text":" performance with the standards."}]},{"text":[{"text":"Take corrective action","bold":true},{"text":" where there is a gap (or reward good results)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Example: a bank branch sets a target of opening 500 new accounts in a quarter. At mid-quarter it has opened 150, so the manager investigates and adds staff to the account-opening desk. That is controlling."}]},{"text":[{"text":"Balanced scorecard:","bold":true},{"text":" a control tool that measures performance from four perspectives (financial, customer, internal business processes, and learning and growth), not money alone."}]},{"text":[{"text":"Quality checks, budgets compared with actual spending, and performance reviews are all control tools. Performance reviews belong to "},{"text":"controlling","bold":true},{"text":", not organising."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"finances are overlooked\" is the opposite of control. Onboarding staff is staffing (HR); advertising goods is marketing."}]}]}]},{"number":"7.6","title":"Essential management skills","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Technical skills:","bold":true},{"text":" the knowledge and ability to perform the specific tasks of a job (hands-on expertise), such as accounting, coding or operating machinery. Most needed by "},{"text":"first-line","bold":true},{"text":" managers."}]},{"text":[{"text":"Interpersonal (human) skills:","bold":true},{"text":" the ability to communicate with, understand, motivate and work with people (teamwork aptitude). Includes "},{"text":"communication","bold":true},{"text":". Needed at "},{"text":"all levels","bold":true},{"text":"."}]},{"text":[{"text":"Conceptual skills:","bold":true},{"text":" the ability to see the organisation as a whole, think "},{"text":"strategically","bold":true},{"text":" and understand how its parts relate (big-picture or visionary capability). Most needed by "},{"text":"top","bold":true},{"text":" managers."}]},{"text":[{"text":"Decision-making skills:","bold":true},{"text":" the ability to define problems, weigh options and choose the best course of action (problem-solving, issue resolution)."}]}]},{"type":"paragraph","text":[{"text":"Steps in decision-making:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Recognise and define the problem or opportunity."}]},{"text":[{"text":"Identify and develop options."}]},{"text":[{"text":"Analyse the options."}]},{"text":[{"text":"Select the best option."}]},{"text":[{"text":"Implement the decision."}]},{"text":[{"text":"Monitor the results and adjust."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Dialogue (communication) and issue resolution (problem-solving)","bold":true},{"text":" are the essential management skills an exam expects. Dismissing input, shunning collaboration and a profit-only focus are weaknesses."}]},{"text":[{"text":"As a manager rises, technical skill matters less and conceptual skill matters more; interpersonal skill stays important throughout."}]},{"text":[{"text":"Programmed decisions","bold":true},{"text":" are routine and follow set rules (reo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 28, $study_guide$rdering stock when it falls to a set level). "},{"text":"Non-programmed decisions","bold":true},{"text":" are new, one-off and complex (entering a new country)."}]},{"text":[{"text":"Time management","bold":true},{"text":" (prioritising and delegating) supports all four skills."}]},{"text":[{"text":"Trap:","bold":true},{"text":" strategic thinking is "},{"text":"conceptual","bold":true},{"text":" skill, not technical (hands-on) or human (teamwork) skill."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A manager's primary role is to drive organisational objectives through planning, organising, leading and controlling."}]},{"text":[{"text":"10 roles in 3 groups: interpersonal (figurehead, leader, liaison), informational (monitor, disseminator, spokesperson), decisional (entrepreneur, disturbance handler, resource allocator, negotiator)."}]},{"text":[{"text":"Spokesperson = informational; resolving conflict = disturbance handler (mediator), decisional."}]},{"text":[{"text":"Levels: top (strategic), middle (tactical), first-line (operational)."}]},{"text":[{"text":"Planning = objectives and tactics; vision, mission, goals, objectives; SWOT = Strengths, Weaknesses, Opportunities, Threats."}]},{"text":[{"text":"Organising = assigning tasks and roles; flat structure = few management tiers; unstructured firm = adaptable and fluid, managed with flexibility and ingenuity."}]},{"text":[{"text":"Teams raise output and fix issues faster; they need clear goals, tools, open communication and trust."}]},{"text":[{"text":"Leading = inspiring and motivating; styles: autocratic, democratic, laissez-faire, situational."}]},{"text":[{"text":"Controlling = set standards, measure, compare, correct."}]},{"text":[{"text":"Skills: technical, interpersonal, conceptual (strategic thinking), decision-making."}]}]}],"theory":{"itemId":"453584a8-5d88-577a-b936-3903f3c291a1","question":[{"type":"paragraph","text":[{"text":"Explain the four functions of management, giving one example of each."}]}]},"practice":[{"topic":"Management Roles, Functions and Skills","named":true},{"topic":"Organization and Teamwork","named":true}]}},{"kind":"note","itemId":"8314272c-90fd-529a-a3c8-08685cb4adac","sourceKey":"guide-topic:8","position":8,"payload":{"title":"Production Systems and Operations","body":"The systems view of business (open systems, boundaries, input-process-output, feedback); value chains and value webs; supply chain management; production and operations management and the types of production; the distinctive challenges of service delivery; product quality and process quality.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"The systems view of business (open systems, boundaries, input-process-output, feedback); value chains and value webs; supply chain management; production and operations management and the types of production; the distinctive challenges of service delivery; product quality and process quality."}],"lessons":[{"number":"8.1","title":"The systems view of business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"System:","bold":true},{"text":" a series of related parts that are dependent on one another; a group of interacting or interrelated elements that act according to a set of rules to form a "},{"text":"unified whole","bold":true},{"text":"."}]},{"text":[{"text":"Business system:","bold":true},{"text":" a defined set of principles, practices and procedures applied to specific activities to achieve a specific result."}]},{"text":[{"text":"Systems view of business:","bold":true},{"text":" sees a company as a complex, "},{"text":"interconnected","bold":true},{"text":" system of "},{"text":"interdependent parts","bold":true},{"text":" (departments or functions). Each part contributes to the organisation's overall goals, and a change in one area can affect the entire system. It views the business "},{"text":"as a whole rather than as isolated parts","bold":true},{"text":", and takes account of its interactions with the external environment."}]},{"text":[{"text":"Organisational boundary:","bold":true},{"text":" the line that "},{"text":"separates the organisation (the system) from its environment","bold":true},{"text":". Inputs cross it coming in; outputs cross it going out."}]}]},{"type":"paragraph","text":[{"text":"4 basic points of the systems view:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Interdependence:","bold":true},{"text":" each component (marketing, finance, operations and so on) relies on the others, so a change in one area has ripple effects throughout the organisation."}]},{"text":[{"text":"Open system:","bold":true},{"text":" most businesses constantly interact with, and are influenced by, factors outside the organisation: market trends, customer needs, economic conditions."}]},{"text":[{"text":"Input-process-output:","bold":true},{"text":" inputs (resources, information) are transformed through processes into outputs (products, services)."}]},{"text":[{"text":"Feedback loop:","bold":true},{"text":" the system continuously monitors its performance and adjusts its processes based on feedback from the environment and from internal operations."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Open vs closed:","bold":true},{"text":" an open system interacts with its environment (inputs in, outputs out, feedback back); a closed system is cut off from it. Almost every real business is open."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A business transforms "},{"text":"lower-value inputs into higher-value outputs","bold":true},{"text":", adding value at every stage. A bakery takes in flour, labour, ovens and electricity (inputs), bakes (transformation) and sells bread (output). Complaints about stale bread are "},{"text":"feedback","bold":true},{"text":"."}]},{"text":[{"text":"Interdependence: if marketing runs a big promotion without telling product$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 29, $study_guide$ion, stock runs out and finance loses revenue."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the systems view focuses on "},{"text":"interconnected business parts","bold":true},{"text":", not on isolated job functions, promotion alone or budgeting alone."}]},{"text":[{"text":"Trap:","bold":true},{"text":" an "},{"text":"organisational","italic":true},{"text":" boundary surrounds the whole organisation; a "},{"text":"process","italic":true},{"text":" boundary marks the limits of a single process. Exams ask for the first."}]}]}]},{"number":"8.2","title":"Value chains and value webs","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Value chain:","bold":true},{"text":" a "},{"text":"linear sequence of activities within a company","bold":true},{"text":" that add value to a product or service at each stage, from raw materials to the final customer. In short, the steps that enhance a product's worth."}]},{"text":[{"text":"Value chain analysis:","bold":true},{"text":" a framework (Michael "},{"text":"Porter","bold":true},{"text":") for analysing a company's activities and identifying areas of "},{"text":"competitive advantage","bold":true},{"text":". It breaks operations into activities classified into "},{"text":"2 basic sets","bold":true},{"text":": "},{"text":"primary","bold":true},{"text":" and "},{"text":"support","bold":true},{"text":" activities."}]}]},{"type":"paragraph","text":[{"text":"5 primary activities","bold":true},{"text":" (directly make, sell and support the product):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Inbound logistics:","bold":true},{"text":" receiving, storing and handling raw materials and inputs coming in."}]},{"text":[{"text":"Operations:","bold":true},{"text":" turning inputs into the finished product."}]},{"text":[{"text":"Outbound logistics:","bold":true},{"text":" storing and "},{"text":"distributing finished goods (inventory)","bold":true},{"text":" to customers."}]},{"text":[{"text":"Marketing and sales:","bold":true},{"text":" persuading customers to buy; pricing, advertising, selling."}]},{"text":[{"text":"Service:","bold":true},{"text":" after-sales support: installation, repairs, customer care."}]}]},{"type":"paragraph","text":[{"text":"4 support activities","bold":true},{"text":" (help the primary activities work):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Procurement:","bold":true},{"text":" buying inputs."}]},{"text":[{"text":"Technology development:","bold":true},{"text":" research, design, process improvement, IT."}]},{"text":[{"text":"Human resource management:","bold":true},{"text":" recruiting, training, rewarding staff."}]},{"text":[{"text":"Firm infrastructure:","bold":true},{"text":" general management, planning, finance, legal, quality systems."}]}]},{"type":"paragraph","text":[{"text":"3 steps in value chain analysis:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify the primary activities."}]},{"text":[{"text":"Identify the support activities."}]},{"text":[{"text":"Analyse the linkages between these activities."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Value web:","bold":true},{"text":" a more complex "},{"text":"network of interconnected value chains across different companies","bold":true},{"text":", often involving collaborations and partnerships, where value is created through multiple interactions between stakeholders in a "},{"text":"less linear","bold":true},{"text":" fashion. Essentially, a value web is a "},{"text":"network of value chains","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Value chain"}],[{"text":"Value web"}]],"rows":[[[{"text":"Linear (straight-line)"}],[{"text":"Network, less linear"}]],[[{"text":"Within one company"}],[{"text":"Across many companies and partners"}]],[[{"text":"One firm does most steps itself"}],[{"text":"Firms specialise and link their chains together"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Count traps: "},{"text":"2","bold":true},{"text":" basic sets, "},{"text":"5","bold":true},{"text":" primary activities, "},{"text":"4","bold":true},{"text":" support activities, "},{"text":"3","bold":true},{"text":" steps of analysis. Read the question carefully to see which count it wants."}]},{"text":[{"text":"Trap:","bold":true},{"text":" technology development, procurement, HR management and firm infrastructure are "},{"text":"support","bold":true},{"text":", never primary. Marketing and sales and service are "},{"text":"primary","bold":true},{"text":"."}]},{"text":[{"text":"Trap:","bold":true},{"text":" inbound logistics = materials coming "},{"text":"in","bold":true},{"text":"; outbound logistics = finished goods going "},{"text":"out","bold":true},{"text":" (distribution of inventory)."}]},{"text":[{"text":"Example: a bottling company receives sugar (inbound), bottles drinks (operations), trucks crates to distributors (outbound), advertises (marketing and sales) and fixes shop coolers (service); its HR and IT are support."}]},{"text":[{"text":"Value webs arise when firms "},{"text":"outsource","bold":true},{"text":" and partner: a phone brand designs phones, buys chips from one firm, has another assemble them and sells bundles through MTN. Each firm runs its own chain; together they form a web, giving flexibility but less control."}]}]}]},{"number":"8.3","title":"Supply chain management","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Supply chain:","bold":true},{"text":" the set of firms and activities that bring a product from its raw materials to the end consumer."}]},{"text":[{"text":"Supply chain management (SCM):","bold":true},{"text":" coordinating and "},{"text":"overseeing","bold":true},{"text":" the activities involved in producing, distributing and delivering goods or services from their "},{"text":"source to the end consumer","bold":true},{"text":"; everything from s$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 30, $study_guide$ourcing raw components to delivering the final result. In short, managing the "},{"text":"flow of goods","bold":true},{"text":"."}]},{"text":[{"text":"Key activities:","bold":true},{"text":" sourcing, design, production, warehousing, shipping, distribution, order management."}]},{"text":[{"text":"Goal:","bold":true},{"text":" to improve "},{"text":"efficiency, quality, productivity and customer satisfaction","bold":true},{"text":"."}]},{"text":[{"text":"Scope:","bold":true},{"text":" managing internal resources, operations management, and coordinating with external partners: suppliers, manufacturers, distributors, retailers and customers."}]},{"text":[{"text":"Importance:","bold":true},{"text":" ensures products are available "},{"text":"when and where needed","bold":true},{"text":", minimising costs and maximising profits."}]}]},{"type":"paragraph","text":[{"text":"5 components of SCM:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Procurement:","bold":true},{"text":" sourcing raw materials and other components."}]},{"text":[{"text":"Production:","bold":true},{"text":" manufacturing the product."}]},{"text":[{"text":"Logistics:","bold":true},{"text":" managing the movement and storage of goods."}]},{"text":[{"text":"Distribution:","bold":true},{"text":" getting the finished product to the end customer."}]},{"text":[{"text":"Order management:","bold":true},{"text":" handling customer orders and ensuring timely fulfilment."}]}]},{"type":"paragraph","text":[{"text":"5 stages in the concept of SCM:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Planning the supply chain network:","bold":true},{"text":" plan each \"link\" so steps join smoothly and every stakeholder knows its responsibilities."}]},{"text":[{"text":"Sourcing materials:","bold":true},{"text":" choose suppliers, decide how much to order, track supplies, pay suppliers."}]},{"text":[{"text":"Organising manufacturers:","bold":true},{"text":" find the right manufacturer to turn raw materials into the end product."}]},{"text":[{"text":"Delivery of the product:","bold":true},{"text":" reliable logistics; damaged goods, late delivery or wrong orders hurt reputation and lose customers."}]},{"text":[{"text":"Managing return services:","bold":true},{"text":" convenient returns and exchanges; reduces waste, since returned items can go to other customers."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SCM involves the flow of "},{"text":"goods, information and money","bold":true},{"text":" among all the partners. It is about overseeing and coordinating flow, never halting production, ignoring vendors or restricting delivery."}]},{"text":[{"text":"Supply chain vs value chain:","bold":true},{"text":" the supply chain looks at how materials and products "},{"text":"move","bold":true},{"text":" from source to consumer; the value chain looks at how each activity "},{"text":"adds value","bold":true},{"text":". They overlap heavily, and SCM is how a firm manages its part of the value web."}]},{"text":[{"text":"Example: a Lagos supermarket chain orders from manufacturers, warehouses stock, trucks it to branches and handles returns; a break at any link (a port backlog, fuel scarcity) leaves empty shelves."}]},{"text":[{"text":"Inventory:","bold":true},{"text":" too much ties up money and space; too little loses sales. "},{"text":"Just-in-time (JIT)","bold":true},{"text":" delivers materials only as needed, cutting storage costs but exposing the firm to late suppliers."}]}]}]},{"number":"8.4","title":"Production and operations management","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Production system:","bold":true},{"text":" a system used to produce goods or services, often with multiple steps that must be completed to produce the final product. In operations management, it is the "},{"text":"organised set of activities, processes and resources involved in transforming inputs into finished goods or services","bold":true},{"text":"."}]},{"text":[{"text":"Production and operations management (POM):","bold":true},{"text":" the process of using (turning) an organisation's resources to "},{"text":"create and deliver goods and services","bold":true},{"text":". It involves "},{"text":"planning, scheduling and controlling","bold":true},{"text":" production so that products are made and delivered "},{"text":"on time and in line with customer demand","bold":true},{"text":"."}]},{"text":[{"text":"Production management","bold":true},{"text":" relates to the activities around "},{"text":"creating products","bold":true},{"text":". "},{"text":"Operations management","bold":true},{"text":" concerns the "},{"text":"production and delivery","bold":true},{"text":" of products and services."}]},{"text":[{"text":"Aim of operations management:","bold":true},{"text":" produce efficiently, "},{"text":"boosting quality and output","bold":true},{"text":" while using resources well and cutting waste."}]}]},{"type":"paragraph","text":[{"text":"Scope of production management","bold":true},{"text":" (planning, organising, directing and controlling production; it starts with input and ends with output, the finished good):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Location of facilities:","bold":true},{"text":" a key decision because large investment goes into land, buildings and machinery."}]},{"text":[{"text":"Plant layout and material handling:","bold":true},{"text":" layout = physical arrangement of facilities; material handling = moving materials from the storeroom to the machine and from one machine to the next."}]},{"text":[{"text":"Product design:","bold":true},{"text":" converting ideas about the product into reality."}]},{"text":[{"text":"Process design:","bold":true},{"text":" deciding the overall process route for converting raw materials into finished goods."}]}]},{"type":"table","header":[[{"text":"Production m$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 31, $study_guide$anagement"}],[{"text":"Operations management"}]],"rows":[[[{"text":"Manages all production activities"}],[{"text":"Manages complete overall business operations, including production and post-production stages"}]],[[{"text":"Limited scope: design, pricing, quality and quantity of goods"}],[{"text":"Broader scope: routine activities such as workforce and inventory management"}]],[[{"text":"High initial capital requirement"}],[{"text":"Lower capital requirement"}]],[[{"text":"Only where products are manufactured"}],[{"text":"All organisations, including banks and hospitals"}]]]},{"type":"paragraph","text":[{"text":"Types of production:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Mass production:","bold":true},{"text":" large quantities of "},{"text":"identical","bold":true},{"text":" (standardised) goods, usually on assembly lines, at low unit cost. Example: bottled water, cement."}]},{"text":[{"text":"Customised production:","bold":true},{"text":" goods or services made to "},{"text":"each customer's individual order","bold":true},{"text":" (also called job production when one-off). Example: a tailor sewing an agbada, a building contractor."}]},{"text":[{"text":"Mass customisation:","bold":true},{"text":" a blend: standard parts mass-produced, then combined to suit individual customers. Example: choosing a laptop's memory and storage when ordering."}]},{"text":[{"text":"Batch production:","bold":true},{"text":" a set quantity (batch) of one product is made, then the equipment is switched to the next batch. Example: a bakery baking batches of different breads."}]},{"text":[{"text":"Continuous production:","bold":true},{"text":" operations run "},{"text":"non-stop","bold":true},{"text":", often 24 hours a day, turning out a constant flow of standard output. Example: oil refining, cement and flour milling."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" POM focuses on "},{"text":"streamlined (efficient) goods creation","bold":true},{"text":", not advertising (marketing), recruitment (HR) or financial targets (finance)."}]},{"text":[{"text":"Trap:","bold":true},{"text":" operations management is the "},{"text":"broader","bold":true},{"text":" term and applies to service firms too; production management applies only where goods are manufactured."}]},{"text":[{"text":"Other POM decisions: "},{"text":"forecasting","bold":true},{"text":" demand, "},{"text":"capacity planning","bold":true},{"text":" (how much a plant, e.g. a Dangote cement plant, can produce), "},{"text":"scheduling","bold":true},{"text":" (what is done when) and "},{"text":"inventory control","bold":true},{"text":"."}]},{"text":[{"text":"Lean production:","bold":true},{"text":" maximum output with minimum waste; JIT is one lean tool."}]},{"text":[{"text":"Higher volume and standardisation lower unit cost but reduce flexibility; customised production is flexible but costly per unit."}]}]}]},{"number":"8.5","title":"Service delivery and quality","mustKnow":[{"type":"paragraph","text":[{"text":"Distinctive challenges of service delivery:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Intangibility:","bold":true},{"text":" services cannot be seen, touched or stored before purchase, so quality is hard to judge."}]},{"text":[{"text":"Perishability:","bold":true},{"text":" an unsold service is lost for ever (an empty seat on a flight, an unused hour of a barber's time); it cannot be stored as inventory."}]},{"text":[{"text":"Customer participation (involvement):","bold":true},{"text":" many services are produced while the customer is present and taking part (salon, clinic, classroom), so the customer's own input affects the result."}]},{"text":[{"text":"Variability (performance variability):","bold":true},{"text":" services are performed by people, so quality varies from one provider, customer or day to the next; "},{"text":"quality control is variable","bold":true},{"text":" and hard."}]},{"text":[{"text":"Location constraints and scalability:","bold":true},{"text":" many services must be delivered where the customer is, and grow only by adding people, so expanding is harder than running a factory extra hours."}]},{"text":[{"text":"Management difficulties:","bold":true},{"text":" service delivery needs planning and many management skills: "},{"text":"time management","bold":true},{"text":" (several jobs at once), "},{"text":"managing other people's work","bold":true},{"text":" (one of the biggest challenges) and "},{"text":"coordination","bold":true},{"text":": "},{"text":"poor coordination between departments leads to poor service quality","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Product quality vs process quality:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Product quality:","bold":true},{"text":" the inherent characteristics of the "},{"text":"final product","bold":true},{"text":", judged by whether it "},{"text":"meets customer expectations (standards)","bold":true},{"text":" in functionality, durability and other attributes."}]},{"text":[{"text":"Process quality:","bold":true},{"text":" how well a production "},{"text":"process","bold":true},{"text":" adheres to established standards and procedures, ensuring "},{"text":"consistency and minimising defects","bold":true},{"text":" at each step; the efficiency of the production method."}]},{"text":[{"text":"Link:","bold":true},{"text":" good process quality directly contributes to high product quality."}]},{"text":[{"text":"Process vs product:","bold":true},{"text":" a process is a set of steps that guides the work to a good product; a product is the result."}]}]},{"type":"table","header":[[{"text":"Product"}],[{"text":"Process"}]],"rows":[[[{"text":"The final output"}],[{"text":"A sequence of steps to create the output"}]],[[{"text":"Focuses on the final result"}],[{"text":"Focuses on completing$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 32, $study_guide$ each step"}]],[[{"text":"Follows firm guidelines"}],[{"text":"Consistently follows guidelines"}]],[[{"text":"Tends to be short-term"}],[{"text":"Tends to be long-term"}]],[[{"text":"Goal: complete the work successfully"}],[{"text":"Goal: make the quality better"}]],[[{"text":"Created from customers' needs and expectations"}],[{"text":"A model for producing various goods in a similar way"}]],[[{"text":"Product layout:","bold":true},{"text":" materials placed in a single line in the order of operations"}],[{"text":"Process layout:","bold":true},{"text":" resources with similar processes or functions grouped together"}]],[[{"text":"Product patents give greater protection"}],[{"text":"Process patents give only limited protection"}]]]},{"type":"paragraph","text":[{"text":"Quality tools:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Statistical process control (SPC):","bold":true},{"text":" sampling output and charting results to spot when a process drifts from its standard."}]},{"text":[{"text":"Continuous improvement (kaizen):","bold":true},{"text":" constant small improvements by everyone."}]},{"text":[{"text":"Total quality management (TQM):","bold":true},{"text":" an organisation-wide commitment to quality and customer satisfaction."}]},{"text":[{"text":"Six Sigma:","bold":true},{"text":" a data-driven method aiming at no more than "},{"text":"3.4 defects per million","bold":true},{"text":" opportunities."}]},{"text":[{"text":"ISO 9000 family:","bold":true},{"text":" international quality management standards; firms are certified under "},{"text":"ISO 9001","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the challenges of services are "},{"text":"variable quality control","bold":true},{"text":" and "},{"text":"client participation","bold":true},{"text":". \"Tangible consistency\", \"uniform execution\", \"low variation\" and \"minimal client contact\" describe physical goods, the opposite."}]},{"text":[{"text":"Trap:","bold":true},{"text":" product quality is about "},{"text":"meeting customer standards","bold":true},{"text":", not production cost, promotion, or looks alone. Process quality is about "},{"text":"production method efficiency","bold":true},{"text":", not costs, promotion or staff onboarding."}]},{"text":[{"text":"In Nigeria, the "},{"text":"Standards Organisation of Nigeria (SON)","bold":true},{"text":" sets and enforces standards for products. ISO 9001 certification signals that a firm's processes meet an international standard."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A system is interdependent parts forming a unified whole; the systems view sees a business as interconnected parts, not isolated functions."}]},{"text":[{"text":"Systems view: interdependence, open system, input-process-output, feedback loop. The organisational boundary separates the organisation from its environment."}]},{"text":[{"text":"Value chain = linear steps adding value inside one firm (Porter): 2 sets, 5 primary, 4 support activities, 3 steps of analysis."}]},{"text":[{"text":"Primary: inbound logistics, operations, outbound logistics (distribution of inventory), marketing and sales, service. Support: procurement, technology development, HRM, firm infrastructure."}]},{"text":[{"text":"Value web = a network of linked value chains across firms."}]},{"text":[{"text":"SCM oversees the flow of goods from source to end consumer: procurement, production, logistics, distribution, order management."}]},{"text":[{"text":"POM = planning, scheduling and controlling the turning of resources into goods and services; operations management is broader than production management."}]},{"text":[{"text":"Types of production: mass, customised, mass customisation, batch, continuous."}]},{"text":[{"text":"Service challenges: intangibility, perishability, customer participation, variability, coordination."}]},{"text":[{"text":"Product quality = meeting customer expectations; process quality = consistent, efficient production method."}]}]}],"theory":{"itemId":"b84670c8-cb91-50a2-a46c-3ca12b27c710","question":[{"type":"paragraph","text":[{"text":"Explain the value chain and identify its primary and support activities. How does a value web differ from a value chain?"}]}]},"practice":[{"topic":"Production Systems","named":false}]}},{"kind":"note","itemId":"2e86475e-0eb9-5cf3-a8b8-8397743dbcd4","sourceKey":"guide-topic:9","position":9,"payload":{"title":"Employee Motivation","body":"What motivation is and why it matters; what motivates employees (intrinsic vs extrinsic, financial vs non-financial); classical and human relations views (Taylor, Hawthorne); McGregor's Theory X and Y and Ouchi's Theory Z; Maslow's hierarchy and Herzberg's two-factor theory; equity, expectancy and goal-setting theories; redesigning jobs (enrichment, enlargement, rotation); reinforcing high-performance behaviour; motivational strategies.","noteType":"guide_topic","number":9,"mustKnow":[{"text":"What motivation is and why it matters; what motivates employees (intrinsic vs extrinsic, financial vs non-financial); classical and human relations views (Taylor, Hawthorne); McGregor's Theory X and Y and Ouchi's Theory Z; Maslow's hierarchy and Herzberg's two-factor theory; equity, expectancy and goal-setting theories; redesigning jobs (enrichment, enlargement, rotation); reinforcing high-performance behaviour; motivational strategies."}],"lessons":[{"number":"9.1","title":"What motivation is and why it matters","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Motivation:","bold":true},{"text":" a process of stimulating people to accomplish desired goals. In business, it is what makes employees put effort, energy and care into their work and keep at it."}]},{"text":[{"text":"Importance of motivation (3 core points):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"it$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 33, $study_guide$ems":[{"text":[{"text":"Improves employee involvement."}]},{"text":[{"text":"Promotes job satisfaction."}]},{"text":[{"text":"Promotes interpersonal cooperation."}]}]}]},{"text":[{"text":"Motivation also "},{"text":"enhances job performance","bold":true},{"text":" and productivity, encourages creativity and "},{"text":"reduces staff turnover","bold":true},{"text":" (people leaving)."}]}]},{"type":"paragraph","text":[{"text":"Factors that motivate employees to improve performance:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Meaningful work"}]},{"text":[{"text":"Clear goals and expectations"}]},{"text":[{"text":"Regular feedback, recognition and appreciation"}]},{"text":[{"text":"Opportunities for growth and development"}]},{"text":[{"text":"A positive work environment and strong leadership"}]},{"text":[{"text":"A sense of belonging"}]},{"text":[{"text":"Alignment with company values (feeling valued, challenged and empowered)"}]},{"text":[{"text":"Autonomy (freedom to decide how to do the work)"}]}]},{"type":"table","header":[[{"text":"Intrinsic motivation"}],[{"text":"Extrinsic motivation"}]],"rows":[[[{"text":"Comes from "},{"text":"inside","bold":true},{"text":" the person"}],[{"text":"Comes from "},{"text":"outside","bold":true},{"text":" the person"}]],[[{"text":"Satisfaction from the work itself: personal growth, interest, achievement"}],[{"text":"Rewards given by others: pay, bonuses, praise, promotion"}]]]},{"type":"table","header":[[{"text":"Financial motivators"}],[{"text":"Non-financial motivators"}]],"rows":[[[{"text":"Salary, wages, bonuses, overtime pay, commission, profit sharing"}],[{"text":"Recognition, praise, "},{"text":"promotion","bold":true},{"text":" (status and responsibility), training, job security, flexible hours, a pleasant work environment"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Employee choices:","bold":true},{"text":" the decisions employees make about their jobs and the benefits they receive, such as the design of welfare programmes, the benefits they take up and the development opportunities they pursue. Each choice is driven by intrinsic or extrinsic motivation."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Low motivation shows up as lateness, absenteeism, poor-quality work, low output and people resigning. Lower productivity, higher turnover and less creativity are "},{"text":"results of poor motivation","bold":true},{"text":", never reasons why motivation is important."}]},{"text":[{"text":"Trap:","bold":true},{"text":" a bonus, salary and overtime pay are all money, so they are financial. A promotion is classed as "},{"text":"non-financial","bold":true},{"text":" because its key value is higher status, more responsibility and growth, even though it often comes with a pay rise."}]},{"text":[{"text":"A bank officer in Lagos who stays late because she enjoys solving clients' problems is intrinsically motivated; one who stays only for overtime pay is extrinsically motivated. Most people are driven by a mix of both."}]}]}]},{"number":"9.2","title":"Early views: Taylor, Hawthorne, McGregor and Ouchi","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Frederick W. Taylor (scientific management, early 1900s):","bold":true},{"text":" studied work scientifically (time-and-motion studies) to find the \"one best way\" to do each task. He believed workers are motivated mainly by "},{"text":"money","bold":true},{"text":", so he used "},{"text":"piece-rate pay","bold":true},{"text":" (paying per unit produced)."}]},{"text":[{"text":"The Hawthorne studies (human relations movement):","bold":true},{"text":" carried out from the 1920s at Western Electric's Hawthorne plant near Chicago; "},{"text":"Elton Mayo","bold":true},{"text":" is the name linked with them. Productivity rose whatever the researchers changed (for example, lighting), because workers felt "},{"text":"noticed and valued","bold":true},{"text":" and belonged to a group."}]},{"text":[{"text":"Hawthorne effect:","bold":true},{"text":" people change (usually improve) their behaviour when they know they are being observed or given attention."}]},{"text":[{"text":"Douglas McGregor (1960)","bold":true},{"text":" described two sets of managerial assumptions:"}]}]},{"type":"table","header":[[{"text":"Theory X"}],[{"text":"Theory Y"}]],"rows":[[[{"text":"Workers dislike work and avoid it"}],[{"text":"Work is as natural as play or rest"}]],[[{"text":"Must be controlled, directed, threatened"}],[{"text":"Workers exercise self-direction and self-control"}]],[[{"text":"Avoid responsibility, have little ambition"}],[{"text":"Accept and seek responsibility"}]],[[{"text":"Want security above all"}],[{"text":"Are creative and committed to goals they value"}]],[[{"text":"Leads to an "},{"text":"authoritarian","bold":true},{"text":", close-control style"}],[{"text":"Leads to a "},{"text":"participative","bold":true},{"text":", trusting style"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"William Ouchi's Theory Z (1981):","bold":true},{"text":" blends Japanese and American practices: long-term employment, "},{"text":"collective (consensus) decision-making","bold":true},{"text":", individual responsibility, slow evaluation and promotion, and concern for the "},{"text":"whole person","bold":true},{"text":" and their family."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The shift in thinking: Taylor treated workers as \"economic beings\" moved by pay; Hawthorne showed that "},{"text":"social and psychological factors","bold":true},{"text":" (attention, group belonging, morale) also drive output. This gave birth to the human relations approach."}]},{"text":[{"text":"Trap:","bold":true},{"text":" Theory X and Y are assumptions "},{"text":"managers","bold":true},{"text":" hold about workers, not two types of worker. A manager who clocks staff in and out and threatens $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 34, $study_guide$query letters for every mistake is acting on Theory X; one who sets goals and lets the team decide how to meet them is acting on Theory Y."}]},{"text":[{"text":"Theory Z is by "},{"text":"Ouchi","bold":true},{"text":", not McGregor."}]}]}]},{"number":"9.3","title":"Needs theories: Maslow and Herzberg","mustKnow":[{"type":"paragraph","text":[{"text":"Abraham Maslow's hierarchy of needs","bold":true},{"text":" (from the base upwards, 5 levels):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physiological:","bold":true},{"text":" survival essentials: food, water, shelter, sleep. The "},{"text":"most basic","bold":true},{"text":" need. At work: a wage that pays for them."}]},{"text":[{"text":"Safety (security):","bold":true},{"text":" protection from harm, stable income. At work: job security, safe conditions, pension, health insurance."}]},{"text":[{"text":"Social (belongingness, love):","bold":true},{"text":" friendship, acceptance, being part of a group. At work: teamwork, friendly colleagues."}]},{"text":[{"text":"Esteem:","bold":true},{"text":" recognition, respect, status, self-respect. At work: titles, praise, awards, promotion."}]},{"text":[{"text":"Self-actualisation:","bold":true},{"text":" becoming all one is capable of; personal fulfilment. The "},{"text":"highest","bold":true},{"text":" need. At work: challenging, creative work and growth."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Lower needs must be largely met before higher needs motivate. A "},{"text":"satisfied need no longer motivates","bold":true},{"text":"."}]},{"text":[{"text":"Physiological and safety = lower-order needs; social, esteem and self-actualisation = higher-order needs."}]}]},{"type":"paragraph","text":[{"text":"Frederick Herzberg's two-factor theory","bold":true},{"text":" (also called motivation-hygiene theory):"}]},{"type":"table","header":[[{"text":"Motivators (satisfiers)"}],[{"text":"Hygiene factors (maintenance factors)"}]],"rows":[[[{"text":"Linked to the "},{"text":"content","bold":true},{"text":" of the job"}],[{"text":"Linked to the "},{"text":"context","bold":true},{"text":" (surroundings) of the job"}]],[[{"text":"Achievement, recognition, the work itself, responsibility, advancement, growth"}],[{"text":"Salary, company policy, supervision, working conditions, relationships with colleagues, job security, status"}]],[[{"text":"Present: "},{"text":"motivate","bold":true},{"text":" and satisfy"}],[{"text":"Absent: cause "},{"text":"dissatisfaction","bold":true},{"text":". Present: only prevent dissatisfaction, they do "},{"text":"not","bold":true},{"text":" motivate"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Herzberg's key point: the opposite of satisfaction is "},{"text":"no satisfaction","bold":true},{"text":", and the opposite of dissatisfaction is "},{"text":"no dissatisfaction","bold":true},{"text":". Raising pay may stop complaints, but lasting motivation comes from motivators such as responsibility and recognition."}]},{"text":[{"text":"Trap:","bold":true},{"text":" the two factors are \"motivation and maintenance (hygiene)\", never \"financial and relational\" or \"intrinsic and short-term\". Salary is a "},{"text":"hygiene","bold":true},{"text":" factor in Herzberg; recognition is a "},{"text":"motivator","bold":true},{"text":"."}]},{"text":[{"text":"Linking the two: Herzberg's hygiene factors roughly match Maslow's lower needs; his motivators match the higher needs (esteem, self-actualisation)."}]},{"text":[{"text":"Other needs-based ideas","bold":true},{"text":" you may meet: "},{"text":"David McClelland","bold":true},{"text":" (needs for achievement, affiliation and power) and "},{"text":"Lawrence and Nohria's four drives","bold":true},{"text":" (to acquire, to bond, to comprehend or learn, and to defend)."}]}]}]},{"number":"9.4","title":"Process theories: equity, expectancy and goal-setting","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Equity theory (J. Stacy Adams):","bold":true},{"text":" employees compare the ratio of their "},{"text":"inputs","bold":true},{"text":" (effort, skill, time, qualifications) to their "},{"text":"outcomes","bold":true},{"text":" (pay, recognition, promotion) with that of other people (a "},{"text":"referent","bold":true},{"text":"). They act based on whether the rewards seem "},{"text":"fair","bold":true},{"text":"."}]},{"text":[{"text":"If they feel under-rewarded they may: reduce effort, ask for a raise, cut quality, change who they compare with, or quit."}]},{"text":[{"text":"Expectancy theory (Victor Vroom):","bold":true},{"text":" people are motivated when they believe effort will lead to good performance, performance will bring a reward, and the reward is one they value. Three links:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Expectancy:","bold":true},{"text":" effort → performance (\"If I try, can I do it?\")"}]},{"text":[{"text":"Instrumentality:","bold":true},{"text":" performance → reward (\"If I do it, will I be rewarded?\")"}]},{"text":[{"text":"Valence:","bold":true},{"text":" value of the reward (\"Do I want that reward?\")"}]}]}]},{"text":[{"text":"If any link is zero, motivation collapses (Motivation = Expectancy × Instrumentality × Valence)."}]},{"text":[{"text":"Goal-setting theory (Edwin Locke):","bold":true},{"text":" "},{"text":"specific, challenging but attainable","bold":true},{"text":" goals produce higher performance than vague or easy goals (\"do your best\"), especially with "},{"text":"feedback","bold":true},{"text":" and when employees "},{"text":"accept","bold":true},{"text":" the goals."}]},{"text":[{"text":"Motivating with challenging goals:","bold":true},{"text":" setting goals that push people outside their comfort zone, so overcoming the difficulty brings a sense of accomplishment and personal growth, which raises motivation and engagement."}]},{"text":[{"text":"SMART goals:","bo$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 35, $study_guide$ld":true},{"text":" "},{"text":"S","bold":true},{"text":"pecific, "},{"text":"M","bold":true},{"text":"easurable, "},{"text":"A","bold":true},{"text":"chievable, "},{"text":"R","bold":true},{"text":"elevant, "},{"text":"T","bold":true},{"text":"ime-bound."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Management by objectives (MBO):","bold":true},{"text":" manager and employee agree goals together, the employee works towards them, and progress is reviewed and rewarded. Participation increases goal acceptance."}]},{"text":[{"text":"A good challenging goal is "},{"text":"precise and trackable","bold":true},{"text":": \"raise sales in Ikeja by 10% by December\" beats \"sell more\". Goals that are "},{"text":"beyond realistic reach","bold":true},{"text":" discourage people; vague, simple targets or lowered expectations fail to stretch them; goals must stay "},{"text":"linked to results","bold":true},{"text":"."}]},{"text":[{"text":"Equity is about "},{"text":"perceived","bold":true},{"text":" fairness. If two graduates join an MTN office on the same grade and one learns the other earns ₦50,000 more, the first may feel inequity even if her own pay is good."}]},{"text":[{"text":"Equity and expectancy are called "},{"text":"process","bold":true},{"text":" theories because they explain "},{"text":"how","bold":true},{"text":" people choose their behaviour; Maslow and Herzberg are "},{"text":"content (needs)","bold":true},{"text":" theories because they explain "},{"text":"what","bold":true},{"text":" motivates."}]}]}]},{"number":"9.5","title":"Redesigning jobs and reinforcing high-performance behaviour","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Job redesign:","bold":true},{"text":" a strategic process of reshaping jobs to fit business needs and the employee's skills and interests, so performance and satisfaction rise and roles stay relevant and engaging."}]},{"text":[{"text":"3 common types:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Job enrichment:","bold":true},{"text":" adds more tasks "},{"text":"and gives more authority","bold":true},{"text":" (responsibility, control, decision-making) to the job holder. Vertical expansion."}]},{"text":[{"text":"Job enlargement:","bold":true},{"text":" adds "},{"text":"more tasks at the same level","bold":true},{"text":" of difficulty and responsibility. Horizontal expansion; widens the range of tasks."}]},{"text":[{"text":"Job rotation:","bold":true},{"text":" moves employees "},{"text":"from one job to another","bold":true},{"text":" at intervals, giving variety and new skills (cross-training)."}]}]}]},{"text":[{"text":"Benefits of job redesign:","bold":true},{"text":" more control over work and more meaningful tasks; reduced stress; improved job satisfaction; reduced turnover."}]},{"text":[{"text":"Job characteristics model (Hackman and Oldham), 5 core dimensions:","bold":true},{"text":" skill variety, task identity, task significance, autonomy, feedback."}]},{"text":[{"text":"High-performance behaviours:","bold":true},{"text":" actions and attitudes that consistently lead to exceptional results and go beyond the job requirements: excellence, initiative, commitment."}]},{"text":[{"text":"Reinforcement theory:","bold":true},{"text":" behaviour that is followed by a pleasant consequence tends to be "},{"text":"repeated","bold":true},{"text":"; behaviour followed by an unpleasant consequence or no consequence tends to fade."}]}]},{"type":"table","header":[[{"text":"Method"}],[{"text":"What happens"}],[{"text":"Effect on behaviour"}]],"rows":[[[{"text":"Positive reinforcement","bold":true}],[{"text":"A reward is given (praise, bonus, extra days off)"}],[{"text":"Increases it"}]],[[{"text":"Negative reinforcement","bold":true}],[{"text":"Something unpleasant is removed when the right behaviour occurs"}],[{"text":"Increases it"}]],[[{"text":"Punishment","bold":true}],[{"text":"Something unpleasant is applied (query, fine)"}],[{"text":"Decreases it"}]],[[{"text":"Extinction","bold":true}],[{"text":"No response at all; behaviour is ignored"}],[{"text":"Decreases it"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" enrichment = "},{"text":"deeper","bold":true},{"text":" job (more authority); enlargement = "},{"text":"wider","bold":true},{"text":" job (more tasks, same level); rotation = "},{"text":"different","bold":true},{"text":" jobs in turn. Shrinking duties, narrowing tasks or limiting control is the opposite of good redesign."}]},{"text":[{"text":"Example: a cashier at a supermarket who now also orders stock and handles customer complaints with power to issue refunds has an "},{"text":"enriched","bold":true},{"text":" job. One who also packs bags and arranges shelves has an "},{"text":"enlarged","bold":true},{"text":" job. A trainee at Dangote moved through production, sales and logistics over a year is on "},{"text":"job rotation","bold":true},{"text":"."}]},{"text":[{"text":"Negative reinforcement is not punishment.","bold":true},{"text":" It "},{"text":"increases","bold":true},{"text":" good behaviour by removing something unpleasant, for example excusing a team that meets its targets from a tedious daily reporting requirement, or removing obstacles in their way."}]},{"text":[{"text":"Reinforcing high performance means "},{"text":"offering praise and rewards","bold":true},{"text":" promptly and specifically. Overlooking successes, cutting incentives or giving no feedback weakens the behaviour."}]}]}]},{"number":"9.6","title":"Motivational strategies","mustKnow":[{"type":"paragraph","text":[{"text":"Motivational strategies help employees feel more productive and engaged at work. They include:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Setting goals:","bold":true},{"text":" measurable and achievable, linked to the company's objectives."}]},{"text":[{"text":"Provi$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 36, $study_guide$ding feedback:","bold":true},{"text":" frequent, meaningful feedback that highlights progress."}]},{"text":[{"text":"Rewarding accomplishments:","bold":true},{"text":" bonuses, gift cards or public recognition."}]},{"text":[{"text":"Offering career development:","bold":true},{"text":" opportunities to learn and advance."}]},{"text":[{"text":"Creating a positive work environment:","bold":true},{"text":" inclusive and welcoming, so employees feel a sense of belonging."}]},{"text":[{"text":"Offering flexible work arrangements:","bold":true},{"text":" remote work or flexible hours, for work-life balance."}]}]},{"type":"paragraph","text":[{"text":"Also: a positive work culture, competitive pay, job security, recognising achievements and aligning personal and company goals build a motivated, high-performing team."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Good strategies "},{"text":"adapt to the individual","bold":true},{"text":" (a young graduate may value training; a parent may value flexible hours) and are "},{"text":"fair","bold":true},{"text":", which links back to equity theory."}]},{"text":[{"text":"Strategies that "},{"text":"lower","bold":true},{"text":" motivation: slashing perks, ignoring staff needs, piling on workloads, favouritism, delayed or no rewards."}]},{"text":[{"text":"Each strategy rests on a theory: goals (goal-setting), feedback and rewards (reinforcement, expectancy), career development (Maslow's esteem and self-actualisation, Herzberg's motivators), positive environment (Hawthorne, Maslow's social needs), fairness (equity)."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Motivation = a process of stimulating people to accomplish desired goals; it improves involvement, job satisfaction, cooperation and performance."}]},{"text":[{"text":"Intrinsic (from within) vs extrinsic (rewards); financial (pay, bonus, overtime) vs non-financial (recognition, promotion)."}]},{"text":[{"text":"Taylor: money and piece-rate pay. Hawthorne (Mayo): attention and social factors raise output."}]},{"text":[{"text":"McGregor: Theory X (control) vs Theory Y (self-direction). Ouchi: Theory Z (Japanese-style, consensus, long-term)."}]},{"text":[{"text":"Maslow: physiological, safety, social, esteem, self-actualisation; physiological is the most basic."}]},{"text":[{"text":"Herzberg: motivators (job content) vs hygiene/maintenance factors (job context, including salary)."}]},{"text":[{"text":"Equity = perceived fairness of rewards; expectancy = expectancy × instrumentality × valence; goal-setting = specific, challenging, attainable (SMART)."}]},{"text":[{"text":"Job redesign: enrichment (more authority), enlargement (more tasks), rotation (moving between jobs)."}]},{"text":[{"text":"Reinforcement: positive and negative increase behaviour; punishment and extinction decrease it."}]},{"text":[{"text":"Strategies: goals, feedback, rewards, career development, positive environment, flexible work."}]}]}],"theory":{"itemId":"b377583e-94c9-51ac-9e48-c9fdebfc90dc","question":[{"type":"paragraph","text":[{"text":"Explain Herzberg's two-factor theory and state three ways a manager can redesign jobs to motivate employees."}]}]},"practice":[{"topic":"Employee Motivation","named":false}]}},{"kind":"note","itemId":"74c39a6d-d5d9-5f48-865a-bc7ac7cfe7d5","sourceKey":"guide-topic:10","position":10,"payload":{"title":"E-business and Business Communication","body":"E-commerce vs e-business and the perspectives on e-commerce; the EC framework; click-only, click-and-mortar and brick-and-mortar firms; B2B, B2C, C2C, B2E and the other transaction types, including m-commerce; business models and online auctions (forward and reverse); benefits and limitations; the communication process model, ways of receiving information and channels; formal communication, the grapevine and barriers.","noteType":"guide_topic","number":10,"mustKnow":[{"text":"E-commerce vs e-business and the perspectives on e-commerce; the EC framework; click-only, click-and-mortar and brick-and-mortar firms; B2B, B2C, C2C, B2E and the other transaction types, including m-commerce; business models and online auctions (forward and reverse); benefits and limitations; the communication process model, ways of receiving information and channels; formal communication, the grapevine and barriers."}],"lessons":[{"number":"10.1","title":"E-commerce and e-business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Electronic commerce (EC or e-commerce):","bold":true},{"text":" the online exchange of goods, services and money between firms, and between firms and their customers. In short, buying, selling, transferring or exchanging products, services and information over computer networks, mostly the internet."}]},{"text":[{"text":"E-business (electronic business):","bold":true},{"text":" the conducting of business on the internet. It is a broader term: the use of electronic communications for "},{"text":"all business processes","bold":true},{"text":", not just buying and selling. It covers sales, purchasing and services on the internet, plus serving customers, collaborating with business partners, e-learning and transactions inside the organisation."}]},{"text":[{"text":"E-commerce goes beyond the sale itself: it can involve the events "},{"text":"leading to a purchase","bold":true},{"text":" (searching, comparing, advertising) as well as "},{"text":"customer service after the sale","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Perspectives on e-commerce:","bold":true},{"text":" e-commerce is often seen simply as buying and selling on the internet, but all these perspectives apply:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Communications:","bold":true},{"text":" delivering information, products, services or payments over telephone lines, computer networks or other electronic means."}]},{"text":[{"text":"Business process:","bold":tru$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 37, $study_guide$e},{"text":" applying technology to automate business transactions and workflows."}]},{"text":[{"text":"Service:","bold":true},{"text":" a tool that helps firms, consumers and management cut service costs while improving the quality and speed of service."}]},{"text":[{"text":"Online:","bold":true},{"text":" buying and selling products and information on the internet and other online services."}]}]},{"type":"paragraph","text":[{"text":"The EC framework:","bold":true},{"text":" EC "},{"text":"applications","bold":true},{"text":" (online shopping, auctions, banking, e-government and so on) rest on "},{"text":"infrastructure","bold":true},{"text":" (hardware, software, networks) and on "},{"text":"five support areas","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"People","bold":true},{"text":" (buyers, sellers, intermediaries, IT staff)"}]},{"text":[{"text":"Public policy","bold":true},{"text":" (laws, regulation, taxation, privacy)"}]},{"text":[{"text":"Marketing and advertisement","bold":true}]},{"text":[{"text":"Support services","bold":true},{"text":" (payments, logistics/delivery, security)"}]},{"text":[{"text":"Business partnerships","bold":true},{"text":" (joint ventures, partners along the supply chain)"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \"Competitors\" is "},{"text":"not","bold":true},{"text":" a support area of EC. If asked which is the exception, pick competitors."}]},{"text":[{"text":"Trap:","bold":true},{"text":" when e-commerce and e-business appear together, e-business is the "},{"text":"wider","bold":true},{"text":" term. \"An organisation selling direct to its customers online\" or \"buying from its suppliers online\" describes only part of e-business. \"Electronic communications for all business processes\" is the full definition."}]},{"text":[{"text":"When a question asks what is exchanged in EC and offers money, goods, services and \"all of the above\", choose "},{"text":"all of the above","bold":true},{"text":". The same goes for sales, purchasing and services as examples of e-business."}]},{"text":[{"text":"The internet and Web technologies together created a "},{"text":"global platform","bold":true},{"text":" where firms across the world compete for customers and gain access to "},{"text":"new markets","bold":true},{"text":". A Lagos fashion brand can sell to buyers in Accra or London through its website and Instagram page."}]}]}]},{"number":"10.2","title":"Types of e-commerce organisations and transactions","mustKnow":[{"type":"table","header":[[{"text":"Type of organisation"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"Brick-and-mortar","bold":true}],[{"text":"Old-economy firm doing business only offline, through physical premises"}],[{"text":"A neighbourhood provision shop"}]],[[{"text":"Click-and-mortar","bold":true},{"text":" (click-and-brick)"}],[{"text":"Keeps its physical locations but has added an "},{"text":"EC (electronic commerce)","bold":true},{"text":" component"}],[{"text":"A supermarket chain with shops plus an online store"}]],[[{"text":"Click-only","bold":true},{"text":" (virtual, pure-play)"}],[{"text":"Does business entirely online; has "},{"text":"no physical storefronts","bold":true}],[{"text":"Jiji, Jumia"}]]]},{"type":"paragraph","text":[{"text":"Transaction types (by who trades with whom):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"B2B (business-to-business):","bold":true},{"text":" transactions between businesses, e.g. a manufacturer buying raw materials from a supplier online. The largest type of EC by value."}]},{"text":[{"text":"B2C (business-to-consumer):","bold":true},{"text":" a business selling to individual shoppers (e-tailing), e.g. Jumia and Konga selling phones and household goods."}]},{"text":[{"text":"C2C (consumer-to-consumer):","bold":true},{"text":" individuals selling to individuals, e.g. a student listing a used laptop on "},{"text":"Jiji","bold":true},{"text":" and another person buying it."}]},{"text":[{"text":"B2E (business-to-employee):","bold":true},{"text":" an organisation delivering information or services to its own employees, usually through its "},{"text":"intranet","bold":true},{"text":", e.g. HR posting a Sales Department vacancy on the company intranet."}]},{"text":[{"text":"C2B (consumer-to-business):","bold":true},{"text":" individuals sell products or services to firms, or name what they will pay and firms compete to supply."}]},{"text":[{"text":"B2B2C:","bold":true},{"text":" a business sells to another business, which delivers to consumers."}]},{"text":[{"text":"Intrabusiness EC:","bold":true},{"text":" EC activities inside one organisation (B2E is part of it)."}]},{"text":[{"text":"E-government:","bold":true},{"text":" government using EC to deal with citizens (G2C) and businesses (G2B), e.g. online tax filing or paying fees and levies online."}]},{"text":[{"text":"Collaborative commerce (c-commerce):","bold":true},{"text":" business partners working together electronically, e.g. "},{"text":"Boeing designing a product together with its business partners","bold":true},{"text":"."}]},{"text":[{"text":"Nonbusiness EC:","bold":true},{"text":" non-profit bodies (universities, religious groups, NGOs, government agencies) using EC to cut costs or improve service."}]},{"text":[{"text":"M-commerce (mobile commerce):","bold":true},{"text":" EC carried out through "},{"text":"mobile","bold":true},{"text":" devices (smartphones, tablets) over wireless networks. The \"m\" means "},{"text":"mobile","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" click-only firms still have employees and supply chains, and many keep warehouses to store goods. What they lack is a "},{"text":"storefront","bold":true},{"text":" customers walk into."}]},{"text":[{"text":"Trap:",$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 38, $study_guide$"bold":true},{"text":" posting a job on the intranet is "},{"text":"B2E","bold":true},{"text":", not B2B. \"B2S\" and \"E2C\" are not standard categories."}]},{"text":[{"text":"Jiji's typical transaction is "},{"text":"C2C","bold":true},{"text":": Jiji provides the website, but buyer and seller are both individuals. Jumia also runs a marketplace where independent sellers list goods, but its typical transaction (a shop selling to you) is classed as "},{"text":"B2C","bold":true},{"text":"."}]},{"text":[{"text":"Nigeria is a mobile-first market, so m-commerce is huge here: ordering on a shopping app, buying airtime and data, and "},{"text":"mobile money","bold":true},{"text":" (sending, receiving and paying money from a phone through mobile money operators and payment apps)."}]}]}]},{"number":"10.3","title":"EC business models and online auctions","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business model:","bold":true},{"text":" the method by which a firm generates revenue to sustain itself."}]}]},{"type":"paragraph","text":[{"text":"Common EC business models:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Online direct marketing:","bold":true},{"text":" manufacturers or retailers selling straight to customers online, cutting out middlemen."}]},{"text":[{"text":"Electronic tendering systems:","bold":true},{"text":" large buyers invite sellers to bid (reverse auctions; see below)."}]},{"text":[{"text":"Name-your-own-price:","bold":true},{"text":" the buyer states the price he is willing to pay and the system looks for a seller willing to accept it."}]},{"text":[{"text":"Find-the-best-price:","bold":true},{"text":" the customer states a need and a search engine compares sellers to find the lowest price."}]},{"text":[{"text":"Affiliate marketing:","bold":true},{"text":" a firm pays partners a commission for customers they refer from their own websites or pages."}]},{"text":[{"text":"Viral marketing:","bold":true},{"text":" people pass a marketing message on to their friends and contacts (word of mouth online)."}]},{"text":[{"text":"Group purchasing:","bold":true},{"text":" pooling many small buyers' orders to get a volume discount."}]},{"text":[{"text":"Online auctions.","bold":true}]},{"text":[{"text":"Product and service customisation:","bold":true},{"text":" the buyer configures the product online to suit himself."}]},{"text":[{"text":"Electronic marketplaces and exchanges:","bold":true},{"text":" online meeting places where many buyers and many sellers trade."}]}]},{"type":"paragraph","text":[{"text":"Online auctions:","bold":true}]},{"type":"table","header":[[],[{"text":"Forward auction"}],[{"text":"Reverse auction"}]],"rows":[[[{"text":"Who sells, who bids"}],[{"text":"One seller","bold":true},{"text":", many buyers bid"}],[{"text":"One buyer","bold":true},{"text":", many sellers bid"}]],[[{"text":"Price movement"}],[{"text":"Goes "},{"text":"up","bold":true}],[{"text":"Goes "},{"text":"down","bold":true}]],[[{"text":"Status"}],[{"text":"The "},{"text":"most common, traditional","bold":true},{"text":" form of auction"}],[{"text":"Also called "},{"text":"electronic tendering","bold":true}]],[[{"text":"Typical user"}],[{"text":"A seller clearing goods to the highest bidder"}],[{"text":"Large private organisational buyers and "},{"text":"government agencies","bold":true},{"text":" making large-volume or large-value purchases"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" \"Reverse auction\" and \"electronic tendering system\" mean the same thing. Online direct marketing, name-your-own-price and viral marketing are other models, not reverse auctions."}]},{"text":[{"text":"A tendering system is buyer-led, so it can never be the answer for \"one seller, many buyers\". That is a "},{"text":"forward","bold":true},{"text":" auction."}]},{"text":[{"text":"A ministry inviting online bids for a supply contract, lowest acceptable bid winning, is a reverse auction."}]}]}]},{"number":"10.4","title":"Benefits and limitations of e-commerce","mustKnow":[{"type":"paragraph","text":[{"text":"Benefits to organisations:","bold":true},{"text":" wider (national and global) market reach at low cost · lower costs of creating, processing and storing information · lower inventory and overheads · 24-hour trading · customisation of products · faster communication with customers and partners · new business models."}]},{"type":"paragraph","text":[{"text":"Benefits to consumers:","bold":true},{"text":" shopping any time, anywhere · more choice of products and sellers · price comparison and often lower prices · quick delivery of digital products · participation in auctions · interaction with other consumers (reviews)."}]},{"type":"paragraph","text":[{"text":"Benefits to society:","bold":true},{"text":" people can work and shop from home, reducing travel and traffic · lower prices help the less well-off · access to services (education, health information, government services) in remote areas."}]},{"type":"table","header":[[{"text":"Limitations"}],[{"text":"Examples"}]],"rows":[[[{"text":"Technological","bold":true}],[{"text":"Poor or expensive internet access in some areas · limited bandwidth · weak security standards · difficulty integrating EC with existing systems"}]],[[{"text":"Non-technological","bold":true}],[{"text":"Fear of "},{"text":"fraud","bold":true},{"text":" and doubts about "},{"text":"security and privacy","bold":true},{"text":" · lack of "},{"text":"trust","bold":true},{"text":" in unseen sellers · customers wanting to touch and inspect goods · unclear legal issues · delivery (logistics) problems · not enough buyers and sellers for some markets"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Many Nigerian shoppers prefer to pay on delivery because they are wary of paying in advance to a seller they cannot see. That is a "},{"text":"trust","bold":tru$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 39, $study_guide$e},{"text":" limitation, not a technological one."}]},{"text":[{"text":"Personal data collected online is protected under the "},{"text":"Nigeria Data Protection Act 2023","bold":true},{"text":", an example of public policy as a support area."}]},{"text":[{"text":"Physical delivery in congested cities and to rural areas is a logistics limitation, solved partly by pick-up stations."}]}]}]},{"number":"10.5","title":"The communication process and channels","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communication:","bold":true},{"text":" the process of transferring "},{"text":"information and understanding","bold":true},{"text":" from one person (or group) to another. It has happened only when the receiver "},{"text":"understands","bold":true},{"text":" the message as the sender intended."}]}]},{"type":"paragraph","text":[{"text":"The basic communication model:","bold":true},{"text":" "},{"text":"sender, the message, channel, receiver and feedback.","bold":true},{"text":" In full, the process runs:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sender","bold":true},{"text":" has an idea and "},{"text":"encodes","bold":true},{"text":" it (puts it into words, symbols or gestures)."}]},{"text":[{"text":"Message:","bold":true},{"text":" the encoded idea."}]},{"text":[{"text":"Channel (medium):","bold":true},{"text":" the means used to carry it (face-to-face, phone, email, letter)."}]},{"text":[{"text":"Receiver","bold":true},{"text":" "},{"text":"decodes","bold":true},{"text":" (interprets) it."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" the receiver's response, which tells the sender whether the message was understood. It makes communication "},{"text":"two-way","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Noise:","bold":true},{"text":" anything that distorts or interrupts the message at any stage (a loud generator, a bad network, jargon, distraction)."}]}]},{"type":"paragraph","text":[{"text":"Ways of receiving information:","bold":true},{"text":" "},{"text":"visual","bold":true},{"text":" (seeing), "},{"text":"auditory","bold":true},{"text":" (hearing) and "},{"text":"kinesthetic","bold":true},{"text":" (doing, touching, feeling)."}]},{"type":"paragraph","text":[{"text":"Channels of communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Oral (verbal):","bold":true},{"text":" face-to-face talk, meetings, phone calls. Fast, with instant feedback, but leaves no permanent record."}]},{"text":[{"text":"Written:","bold":true},{"text":" letters, memos, reports, emails, notices. A permanent record, but slower and with delayed feedback."}]},{"text":[{"text":"Non-verbal:","bold":true},{"text":" body language, facial expression, gestures, tone of voice, posture."}]},{"text":[{"text":"Electronic/digital:","bold":true},{"text":" email, video calls, intranet, instant messaging, social media."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" noise and barriers are "},{"text":"not","bold":true},{"text":" elements of the basic model; they are what disturb it. Any option listing \"noise\", \"barriers\", \"data\" or \"para-verbal\" as core elements is wrong."}]},{"text":[{"text":"Trap:","bold":true},{"text":" \"shouting\" is not a way of receiving information, and \"auditory and visual only\" leaves out "},{"text":"kinesthetic","bold":true},{"text":"."}]},{"text":[{"text":"Channel richness:","bold":true},{"text":" face-to-face is the "},{"text":"richest","bold":true},{"text":" channel (voice, body language and instant feedback together); a printed notice is among the leanest. Use rich channels for sensitive or complex messages, such as telling a staff member he is being transferred."}]}]}]},{"number":"10.6","title":"Formal and informal communication; barriers","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Formal communication:","bold":true},{"text":" flows through the "},{"text":"official","bold":true},{"text":" lines of authority laid down by the organisation's structure."}]}]},{"type":"paragraph","text":[{"text":"Directions of formal communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Downward:","bold":true},{"text":" superior to subordinate (instructions, policies, feedback on performance)."}]},{"text":[{"text":"Upward:","bold":true},{"text":" subordinate to superior (reports, suggestions, complaints)."}]},{"text":[{"text":"Horizontal (lateral):","bold":true},{"text":" between people at the "},{"text":"same level","bold":true},{"text":", often across departments, for coordination."}]},{"text":[{"text":"Diagonal (cross-wise):","bold":true},{"text":" between people at "},{"text":"different levels in different departments","bold":true},{"text":", e.g. a sales officer contacting the finance manager directly."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Informal communication (the grapevine):","bold":true},{"text":" the unofficial network that grows from social relationships among staff and does not follow the chain of command. It is fast and can carry rumours."}]}]},{"type":"paragraph","text":[{"text":"Uses of the grapevine:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Acts as a "},{"text":"safety valve","bold":true},{"text":": employees let off steam and express feelings."}]},{"text":[{"text":"Helps employees enjoy "},{"text":"friendly relationships","bold":true},{"text":" and builds group unity."}]},{"text":[{"text":"Helps the organisation "},{"text":"discover gaps","bold":true},{"text":": problems and attitudes management did not know about."}]},{"text":[{"text":"Spreads information "},{"text":"quickly","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Barriers to effective communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 40, $study_guide$"text":"Physical:","bold":true},{"text":" noise, distance, poor network or equipment."}]},{"text":[{"text":"Semantic (language):","bold":true},{"text":" jargon, words with different meanings, poor translation."}]},{"text":[{"text":"Perceptual:","bold":true},{"text":" people interpret the same message differently."}]},{"text":[{"text":"Emotional/psychological:","bold":true},{"text":" anger, fear, distrust, prejudice."}]},{"text":[{"text":"Cultural:","bold":true},{"text":" different customs, values and gestures."}]},{"text":[{"text":"Organisational:","bold":true},{"text":" too many levels, rigid rules, status differences between boss and staff."}]},{"text":[{"text":"Information overload:","bold":true},{"text":" more messages than the receiver can handle."}]},{"text":[{"text":"Poor listening","bold":true},{"text":" and lack of feedback."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap:","bold":true},{"text":" the grapevine is "},{"text":"informal","bold":true},{"text":". Horizontal, diagonal, upward and downward are all "},{"text":"formal","bold":true},{"text":" directions. The question about a \"safety valve\" that \"helps organisations discover gaps\" always points to the grapevine."}]},{"text":[{"text":"Drawbacks of the grapevine: rumours, distortion, half-truths and leaks. Managers cannot abolish it, so they should feed it accurate information early."}]},{"text":[{"text":"Overcoming barriers:","bold":true},{"text":" use simple language, choose the right channel, listen actively, seek feedback, be aware of cultural differences, keep messages concise and factual, and cut unnecessary levels."}]},{"text":[{"text":"Good professional communication means: listen actively, give practical information, give facts rather than vague impressions, do not present opinions as facts, be concise, clarify expectations and responsibilities, and make persuasive, well-supported recommendations."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"E-commerce = online exchange of goods, services and money; it includes pre-purchase events and after-sale customer service."}]},{"text":[{"text":"E-business = conducting business on the internet; electronic communications for "},{"text":"all","bold":true},{"text":" business processes (wider than e-commerce)."}]},{"text":[{"text":"Perspectives on EC: communications, business process, service, online."}]},{"text":[{"text":"EC framework: infrastructure + 5 support areas (people, public policy, marketing and advertisement, support services, business partnerships). Competitors are not one."}]},{"text":[{"text":"Click-only = no storefronts; click-and-mortar = physical shops plus an EC component."}]},{"text":[{"text":"B2B, B2C, C2C (Jiji), B2E (intranet job posting), c-commerce (Boeing), m-commerce (m = mobile)."}]},{"text":[{"text":"Forward auction = one seller, many buyers (most common); reverse auction = electronic tendering, one buyer, many sellers."}]},{"text":[{"text":"Communication model: sender, message, channel, receiver, feedback; noise disturbs it."}]},{"text":[{"text":"Receiving information: visual, auditory, kinesthetic."}]},{"text":[{"text":"Grapevine = informal; safety valve, friendly relationships, discovers gaps."}]}]}],"theory":{"itemId":"45748893-ca91-51ce-974f-4428998bdbb0","question":[{"type":"paragraph","text":[{"text":"Distinguish between e-commerce and e-business, and explain four types of e-commerce transactions with examples."}]}]}}}],"theory":[{"kind":"theory_question","itemId":"673bffa2-543e-5b27-b905-4445464c011f","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"Explain the five environments in which every business operates, and state two ways business benefits society."},"answer":{"kind":"model_answer","itemId":"51b76e5f-0c95-52dc-9ccc-d491e48ece22","sourceKey":"guide-answer:1","payload":{"body":"Define business environment (forces that affect and are affected by business). Then 1-2 lines each, with a Nigerian example: social (trends in society), technological (application of science), economic (cost and availability of goods, services, labour), legal and regulatory (laws, e.g. CAMA 2020 administered by CAC), market (customers, buying influences, competitors). Close with two benefits: goods and services, employment, taxes, national growth and stability."}}},{"kind":"theory_question","itemId":"a920fd06-e86d-5415-ba0d-9a989c7f7d21","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"Distinguish between a market economy and a command economy, and explain the role of government in a free-market system."},"answer":{"kind":"model_answer","itemId":"f82f9081-8c6b-5897-ad96-bba4ff1ec54f","sourceKey":"guide-answer:2","payload":{"body":"Define an economic system. Market economy: demand and supply decide production and prices; private ownership, competition, freedom of choice, limited government intervention. Command economy: central government planning, government ownership of key businesses, control of wages and means of production, little competition and limited choice. Then list and explain government's roles in a free market: legal and social framework (fair-play rules), economic stability (monetary and fiscal policy), maintaining competition (anti-trust body), public goods, income redistribution, international relations. Give a Nigerian example for at least two (e.g. CBN, FCCPC)."}}},{"kind":"theory_question","itemId":"f4adf133-ee00-5bcd-a52b-549479b7fd84","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"Explain four forms of international business activity a Nigerian firm could use to enter a foreign market."},"answer":{"kind":"model_answer","itemId":"b9bb2d13-e876-53bb-8eee-aab7f8279640","sourceKey":"guide-answer:3","payload":{"body":"Define international business. Then 2-3 lines each on any four: exporting (sell abroad from home, low risk); licensing (foreign firm uses your brand or technology for royalties); franchising (foreign franchisee runs your$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_bua101', 41, $study_guide$ business system for fees); joint venture (new firm co-owned with a local partner, shared risk); FDI (own a factory or subsidiary abroad, most control and risk). Close by noting that commitment, control and risk rise from exporting to FDI."}}},{"kind":"theory_question","itemId":"63ce438b-49e2-5b06-8a85-df5c773c3a39","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Define corporate social responsibility and explain the four perspectives on CSR."},"answer":{"kind":"model_answer","itemId":"f03b068c-ba2a-50ba-a119-14be13182eec","sourceKey":"guide-answer:4","payload":{"body":"Define CSR (duty to society beyond profit). Then 1-2 lines each: minimalist (only profit within the law), defensive (CSR to avoid criticism and regulation), cynical (CSR as a PR tool), proactive (CSR as a moral obligation). Close with one example of CSR towards the environment, consumers or employees."}}},{"kind":"theory_question","itemId":"e59886c4-52f7-5e2c-8f64-a9ea1e460c27","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Distinguish between a private limited company and a public limited company, and state two advantages and two disadvantages of the corporate form."},"answer":{"kind":"model_answer","itemId":"b28044fe-70c1-56ac-ac95-567cecc8d881","sourceKey":"guide-answer:5","payload":{"body":"Define a company as a separate legal entity owned by shareholders. Give four differences: membership (2-50 vs 7+), share transfer and public subscription, publication of accounts, stock-exchange quotation (or debentures, Ltd vs Plc). Advantages: limited liability, perpetual life, access to capital. Disadvantages: double taxation, cost and disclosure requirements."}}},{"kind":"theory_question","itemId":"9957e3ea-8b1f-5d53-a98f-e88cdf2ae4ca","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"Explain the franchise alternative and state three advantages and three disadvantages of franchising to the franchisee."},"answer":{"kind":"model_answer","itemId":"5e11f8df-9553-51b5-8eaa-c496c40825bd","sourceKey":"guide-answer:6","payload":{"body":"Define a franchise; name franchisor and franchisee; mention the fee and royalties. Advantages: pre-existing brand fame, proven system with lower failure risk, training and support. Disadvantages: high start-up cost, continuing royalties, loss of independence under strict rules."}}},{"kind":"theory_question","itemId":"453584a8-5d88-577a-b936-3903f3c291a1","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"Explain the four functions of management, giving one example of each."},"answer":{"kind":"model_answer","itemId":"f8559c1a-a8a1-5528-80c1-7e0805cb276b","sourceKey":"guide-answer:7","payload":{"body":"Define management. Planning: setting objectives and strategies (e.g. SWOT, mission statement). Organising: assigning tasks, roles and resources (e.g. forming a cross-functional team). Leading: motivating and guiding people (e.g. a democratic manager involving staff). Controlling: setting standards, measuring, comparing and correcting (e.g. comparing monthly sales with target). Conclude that the functions form a continuous cycle."}}},{"kind":"theory_question","itemId":"b84670c8-cb91-50a2-a46c-3ca12b27c710","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"Explain the value chain and identify its primary and support activities. How does a value web differ from a value chain?"},"answer":{"kind":"model_answer","itemId":"4487c4d0-aec5-59b6-a6e5-663489b27f49","sourceKey":"guide-answer:8","payload":{"body":"Define the value chain (linear sequence of value-adding activities within a firm; Porter). List the 5 primary activities with a line each, then the 4 support activities. Mention the 3 steps of value chain analysis. Define the value web (network of interconnected value chains across companies, less linear, built on partnerships) and contrast it with the value chain in two or three points."}}},{"kind":"theory_question","itemId":"b377583e-94c9-51ac-9e48-c9fdebfc90dc","sourceKey":"guide-theory:9","position":9,"payload":{"prompt":"Explain Herzberg's two-factor theory and state three ways a manager can redesign jobs to motivate employees."},"answer":{"kind":"model_answer","itemId":"b2fc1d06-ed01-50e6-a6eb-3ab9307635b1","sourceKey":"guide-answer:9","payload":{"body":"Define motivation. Herzberg: motivators (achievement, recognition, responsibility, the work itself, advancement) relate to job content and create satisfaction; hygiene or maintenance factors (salary, policy, supervision, working conditions, job security) relate to job context and only prevent dissatisfaction. Job redesign: enrichment (more tasks and authority), enlargement (more tasks at the same level), rotation (moving between jobs for variety), each with a short example and one benefit (satisfaction, less turnover)."}}},{"kind":"theory_question","itemId":"45748893-ca91-51ce-974f-4428998bdbb0","sourceKey":"guide-theory:10","position":10,"payload":{"prompt":"Distinguish between e-commerce and e-business, and explain four types of e-commerce transactions with examples."},"answer":{"kind":"model_answer","itemId":"2f398e99-5b70-5354-a637-3a9afa6fd47a","sourceKey":"guide-answer:10","payload":{"body":"Define e-commerce (online exchange of goods, services and money between firms and between firms and customers) and e-business (conducting business on the internet; electronic communications for all business processes, including serving customers and collaborating with partners). State that e-business is the wider term. Then 2 lines each, with an example: B2B (firm buying supplies from another firm online), B2C (Jumia or Konga selling to shoppers), C2C (individuals trading on Jiji), B2E (HR posting a vacancy on the intranet). M-commerce or c-commerce may replace any one of these."}}}]}$study_guide$);
